    const MF_UNIT_FINDER_DIAGNOSTICS_KEY =
        'mf_unit_finder_diagnostics_v1';
    const MF_UNIT_FINDER_DIAGNOSTICS_LIMIT = 24;
    const MF_UNIT_FINDER_DIAGNOSTICS_MAX_STORAGE_CHARS = 750000;
    let mfUnitFinderDiagnosticContext = {
        missionKey: '',
        mode: 'idle',
        sourceLabel: '',
        suppliedRows: [],
        processedRows: [],
        updatedAt: 0
    };
