    function getVehicleMatchCandidates(originalName, mappedName) {
        const raw = String(originalName || '').replace(/\s+/g, ' ').trim();
        const mapped = String(mappedName || '').replace(/\s+/g, ' ').trim();
        const cacheKey = `${raw.toLowerCase()}|${mapped.toLowerCase()}`;
        const cached = mfVehicleMatchCandidateCache.get(cacheKey);

        if (cached) return cached;

        const candidates = new Set([raw, mapped]);

        const add = value => {
            if (value) candidates.add(String(value).replace(/\s+/g, ' ').trim());
        };

        const lowerMapped = mapped.toLowerCase();
        const lowerRaw = raw.toLowerCase();

        if (lowerMapped.includes('fire engine') || lowerRaw.includes('pump') || lowerRaw.includes('rescue support')) {
            add('Fire Engine');
            add('Pump');
            add('Pumps');
            add('Rescue Pump');
            add('Rescue Support Unit');
            add('Rescue Support Vehicle');
        }

        if (lowerMapped === 'police atc' || lowerRaw.includes('traffic car')) {
            add('Traffic Car');
            add('Traffic Cars');
            add('Police ATC');
        }

        if (lowerMapped === 'police car' || lowerRaw.includes('police car')) {
            add('Police Car');
            add('Police Cars');
        }

        if (
            isAtvCarrierRequirement(
                originalName,
                mappedName
            )
        ) {
            add('ATV');
            add('ATV Carrier');
            add('ATV Carriers');
            add('ATC Carrier');
            add('ATC Carriers');
        }

        if (lowerMapped === 'police dsu' || lowerRaw.includes('dog support')) {
            add('Dog Support Unit (DSU)');
            add('Dog Support Units (DSU)');
            add('Dog Support Units (DSUs)');
            add('Police DSU');
            add('DSU');
        }

        const policeAirMode =
            getPoliceAirRequirementMode(
                originalName,
                mappedName
            );

        if (
            policeAirMode === 'flexible' ||
            policeAirMode === 'helicopter'
        ) {
            add('Police Helicopter');
            add('Police Helicopters');
            add('Policehelicopter');
            add('Policehelicopters');
        }

        if (
            policeAirMode === 'flexible' ||
            policeAirMode === 'drone' ||
            policeAirMode === 'generic-drone'
        ) {
            add('Police Drone');
            add('Police Drones');
            add('Drone Vehicle(Police Station)');
            add('Drone Vehicle (Police Station)');
        }

        if (policeAirMode === 'generic-drone') {
            add('Drone Vehicle SAR HQ');
            add('Drone Vehicle (SAR HQ)');
            add('SAR Drone Vehicle');
        }

        if (lowerMapped === 'welfare vehicle' || lowerRaw.includes('welfare vehicle')) {
            add('Welfare Vehicle');
            add('Welfare Vehicles');
        }

        if (
            isIccuOrAmbulanceControlRequirement(
                originalName,
                mappedName
            )
        ) {
            add('ICCU');
            add('ICCUs');
            add('Incident Command and Control Unit');
            add('Incident Command and Control Units');
            add('Ambulance Control Unit');
            add('Ambulance Control Units');
            add('ACU');
            add('ACUs');
        }

        if (
            lowerMapped === 'operational support van' ||
            lowerRaw.includes('operational support van') ||
            lowerRaw.includes('personal sar vehicle')
        ) {
            add('Operational Support Van');
            add('Operational Support Vans');
            add('OSV');
            add('OSVs');
        }

        if (
            lowerMapped === 'alb' ||
            lowerMapped === 'abl' ||
            lowerRaw.includes('seagoing vessel') ||
            lowerRaw.includes('all-weather lifeboat') ||
            lowerRaw.includes('all weather lifeboat')
        ) {
            add('ALB');
            add('ALBs');
            add('All-weather Lifeboat');
            add('All Weather Lifeboat');
            add('Seagoing Vessel');
            add('Seagoing Vessels');
            add('ABL');
            add('ABLs');
        }

        if (lowerMapped === 'ilb' || lowerRaw.includes('ilb')) {
            add('ILB');
            add('ILBs');
        }

        if (isRrvRequirement(originalName, mappedName)) {
            add('RRV');
            add('RRVs');
            add('Specialist Paramedic RRV');
            add('Specialist Paramedic RRVs');
            add('Rapid Response Vehicle');
            add('Rapid Response Vehicles');
        }

        if (isRivRequirement(originalName, mappedName)) {
            add('RIV');
            add('RIVs');
            add('Rapid Intervention Vehicle');
            add('Rapid Intervention Vehicles');
        }

        let result;

        // Ambulance Officer must never fall through to normal Ambulance matching.
        if (lowerMapped.includes('ambulance officer') || lowerRaw.includes('ambulance officer')) {
            result = ['ambulance officer', 'ambulance officers'];
        } else {
            if (
                lowerMapped === 'ambulance x 01' ||
                lowerMapped === 'ambulance' ||
                lowerMapped === 'ambulances' ||
                /^ambulances?$/i.test(raw)
            ) {
                add('Ambulance');
                add('Ambulances');
                add('Ambulance x 01');
            }

            result = Array.from(candidates)
                .filter(Boolean)
                .map(normaliseVehicleText);
        }

        if (mfVehicleMatchCandidateCache.size >= MF_VEHICLE_MATCH_CACHE_LIMIT) {
            mfVehicleMatchCandidateCache.clear();
        }

        mfVehicleMatchCandidateCache.set(cacheKey, result);
        return result;
    }

    let mfVehicleSelectionDocumentCache = {
        expiresAt: 0,
        missionKey: '',
        document: null
    };

    function getVehicleSelectionDocument(
        forceRefresh = false
    ) {
        const now = Date.now();
        let missionKey = '';

        try {
            missionKey = getLocalMissionInstanceKey();
        } catch (_error) {}

        const cachedDocument =
            mfVehicleSelectionDocumentCache.document;

        let cachedDocumentUsable = false;

        if (cachedDocument?.documentElement) {
            try {
                cachedDocumentUsable =
                    isCachedMissionDocumentUsable(
                        cachedDocument
                    ) &&
                    isMissionDocumentVisible(
                        cachedDocument
                    );
            } catch (_error) {
                cachedDocumentUsable =
                    cachedDocument === document;
            }
        }

        if (
            !forceRefresh &&
            cachedDocumentUsable &&
            missionKey ===
                mfVehicleSelectionDocumentCache.missionKey &&
            now <
                mfVehicleSelectionDocumentCache.expiresAt
        ) {
            return cachedDocument;
        }

        let candidateDocument = document;

        try {
            const primaryDocument =
                getPrimaryMissionRequirementDocument();

            if (
                primaryDocument?.querySelectorAll &&
                isCachedMissionDocumentUsable(
                    primaryDocument
                ) &&
                isMissionDocumentVisible(
                    primaryDocument
                )
            ) {
                candidateDocument =
                    primaryDocument;
            }
        } catch (_error) {}

        mfVehicleSelectionDocumentCache = {
            expiresAt: now + 250,
            missionKey,
            document: candidateDocument
        };

        return candidateDocument;
    }

    function queryVehicleSelectionElements(
        selector,
        forceRefresh = false
    ) {
        const selectionDocument =
            getVehicleSelectionDocument(
                forceRefresh
            );

        try {
            return Array.from(
                selectionDocument.querySelectorAll(
                    selector
                )
            );
        } catch (_error) {
            return [];
        }
    }

    function isVehicleSelectionElementVisible(
        element
    ) {
        if (
            !element ||
            element.isConnected === false
        ) {
            return false;
        }

        try {
            const ownerWindow =
                element.ownerDocument
                    ?.defaultView ||
                window;

            const style =
                ownerWindow.getComputedStyle(
                    element
                );

            if (
                style.display === 'none' ||
                style.visibility === 'hidden'
            ) {
                return false;
            }

            return element.getClientRects().length > 0;
        } catch (_error) {
            return true;
        }
    }

    function invalidateVehicleCheckboxCache() {
        mfVehicleCheckboxCache = {
            expiresAt: 0,
            nodes: [],
            document: null
        };

        mfVehicleSelectionDocumentCache = {
            expiresAt: 0,
            missionKey: '',
            document: null
        };

        // Vehicle rows are replaced during Load Missing and mission changes.
        // WeakMaps avoid retaining detached DOM nodes; resetting them also
        // handles MissionChief reusing a row with changed attributes.
        mfCheckboxVehicleValueCache = new WeakMap();
        mfExtendedVehicleValueCache = new WeakMap();
        mfSartecDisplayedValueCache = new WeakMap();
        mfVehicleTypeIdentifierCache = new WeakMap();
        mfVehicleArrivalMetricCache = new WeakMap();
    }

    function getVehicleCheckboxSnapshot(
        forceRefresh = false
    ) {
        const now = Date.now();
        const selectionDocument =
            getVehicleSelectionDocument(
                forceRefresh
            );
        const cachedNodes =
            mfVehicleCheckboxCache.nodes;
        const firstNode = cachedNodes[0];
        const lastNode =
            cachedNodes[
                cachedNodes.length - 1
            ];
        const cacheStillConnected =
            cachedNodes.length === 0 ||
            (
                firstNode?.isConnected !== false &&
                lastNode?.isConnected !== false
            );
        const cacheMatchesDocument =
            mfVehicleCheckboxCache.document ===
            selectionDocument;

        if (
            !forceRefresh &&
            now <
                mfVehicleCheckboxCache.expiresAt &&
            cacheStillConnected &&
            cacheMatchesDocument
        ) {
            return cachedNodes;
        }

        let nodes = [];

        try {
            nodes = Array.from(
                selectionDocument.querySelectorAll(
                    'input.vehicle_checkbox'
                )
            );
        } catch (_error) {}

        mfVehicleCheckboxCache = {
            expiresAt:
                now +
                (nodes.length ? 500 : 120),
            nodes,
            document: selectionDocument
        };

        return nodes;
    }

    function getCheckboxVehicleValues(input) {
        if (!input) return [];

        const cached = mfCheckboxVehicleValueCache.get(input);
        if (cached) return cached;

        const row = input.closest('tr');
        const values = [
            input.getAttribute('vehicle_caption'),
            input.getAttribute('vehicle_type_caption'),
            input.getAttribute('search_attribute'),
            input.getAttribute('vehicle_type'),
            row?.getAttribute('vehicle_caption'),
            row?.getAttribute('vehicle_type_caption'),
            row?.getAttribute('vehicle_type'),
            row?.querySelector('td:nth-child(2)')?.innerText
        ]
        .filter(Boolean)
        .map(normaliseVehicleText);

        mfCheckboxVehicleValueCache.set(input, values);
        return values;
    }

    function getExtendedVehicleValues(input) {
        if (!input) return [];

        const cached = mfExtendedVehicleValueCache.get(input);
        if (cached) return cached;

        const row = input.closest && input.closest('tr');
        const labelById = input.id
            ? document.getElementById(`label_${input.id}`)
            : null;

        const rowLabel = row && input.id
            ? Array.from(row.querySelectorAll('label[for]')).find(
                label => label.htmlFor === input.id
            )
            : null;

        const values = [
            ...getCheckboxVehicleValues(input),
            labelById?.textContent,
            labelById?.innerText,
            rowLabel?.textContent,
            rowLabel?.innerText,
            row?.querySelector('td[vehicle_type_id]')?.innerText
        ]
            .filter(Boolean)
            .map(normaliseVehicleText);

        mfExtendedVehicleValueCache.set(input, values);
        return values;
    }

    function isAmbulanceTransportRequest(originalName, mappedName) {
        const raw = normaliseVehicleText(originalName);
        const mapped = normaliseVehicleText(mappedName);

        if (raw.includes('ambulance officer') || mapped.includes('ambulance officer')) {
            return false;
        }

        return mapped === 'ambulance x 01'
            || mapped === 'ambulance'
            || mapped === 'ambulances'
            || raw === 'ambulance'
            || raw === 'ambulances'
            || raw === 'ambulance x 01';
    }

    function isAmbulanceOfficerVehicleCheckbox(input) {
        if (!input) return false;

        const typeIds = getVehicleTypeIdentifiers(input);

        if (typeIds.includes('34')) {
            return true;
        }

        if (typeIds.length > 0) {
            return false;
        }

        return getExtendedVehicleValues(input).some(value => {
            const normalised = normaliseVehicleText(value);
            return normalised === 'ambulance officer' ||
                normalised === 'ambulance officers';
        });
    }

    function vehicleValuesMatchCandidates(values, candidates, strictExactOnly) {
        if (strictExactOnly) {
            return values.some(value => candidates.some(candidate => value === candidate));
        }

        return values.some(value => candidates.some(candidate => value === candidate || value.includes(candidate)));
    }

    function getVehicleCheckboxForElement(
        element
    ) {
        if (!element) return null;

        if (
            element.matches?.(
                'input.vehicle_checkbox'
            )
        ) {
            return element;
        }

        const row =
            element.closest?.('tr');

        return row?.querySelector?.(
            'input.vehicle_checkbox'
        ) || null;
    }

    function getAssociatedVehicleCheckboxLabel(
        checkbox
    ) {
        if (!checkbox) return null;

        try {
            const directLabel =
                Array.from(
                    checkbox.labels || []
                )[0];

            if (directLabel) {
                return directLabel;
            }
        } catch (_error) {}

        const wrappingLabel =
            checkbox.closest?.('label');

        if (wrappingLabel) {
            return wrappingLabel;
        }

        const checkboxId =
            String(checkbox.id || '').trim();

        if (!checkboxId) return null;

        const ownerDocument =
            checkbox.ownerDocument ||
            document;

        try {
            return Array.from(
                ownerDocument.querySelectorAll(
                    'label[for]'
                )
            ).find(label => {
                return String(
                    label.htmlFor ||
                    label.getAttribute('for') ||
                    ''
                ) === checkboxId;
            }) || null;
        } catch (_error) {
            return null;
        }
    }

    function dispatchVehicleCheckboxStateEvent(
        checkbox,
        type
    ) {
        try {
            const ownerWindow =
                checkbox.ownerDocument
                    ?.defaultView ||
                window;

            const EventConstructor =
                ownerWindow.Event ||
                Event;

            checkbox.dispatchEvent(
                new EventConstructor(
                    type,
                    {
                        bubbles: true,
                        cancelable: false,
                        composed: true
                    }
                )
            );

            return true;
        } catch (_error) {
            return false;
        }
    }

    function forceVehicleCheckboxSelection(
        checkbox
    ) {
        if (
            !checkbox ||
            checkbox.disabled ||
            checkbox.isConnected === false
        ) {
            return false;
        }

        try {
            const ownerWindow =
                checkbox.ownerDocument
                    ?.defaultView ||
                window;

            const inputPrototype =
                ownerWindow.HTMLInputElement
                    ?.prototype;

            const checkedDescriptor =
                inputPrototype
                    ? Object.getOwnPropertyDescriptor(
                        inputPrototype,
                        'checked'
                    )
                    : null;

            if (checkedDescriptor?.set) {
                checkedDescriptor.set.call(
                    checkbox,
                    true
                );
            } else {
                checkbox.checked = true;
            }
        } catch (_error) {
            try {
                checkbox.checked = true;
            } catch (_innerError) {}
        }

        if (checkbox.checked !== true) {
            return false;
        }

        dispatchVehicleCheckboxStateEvent(
            checkbox,
            'input'
        );
        dispatchVehicleCheckboxStateEvent(
            checkbox,
            'change'
        );

        return checkbox.checked === true;
    }

    function isVehicleElementAlreadySelected(
        element
    ) {
        const checkbox =
            getVehicleCheckboxForElement(
                element
            );

        return checkbox
            ? checkbox.checked === true
            : false;
    }

    function clickVehicleElement(element) {
        if (
            !element ||
            element.isConnected === false
        ) {
            return false;
        }

        const checkbox =
            getVehicleCheckboxForElement(
                element
            );

        if (checkbox) {
            if (
                checkbox.disabled ||
                checkbox.isConnected === false
            ) {
                return false;
            }

            if (checkbox.checked === true) {
                return true;
            }

            try {
                checkbox.click();
            } catch (_error) {}

            if (checkbox.checked === true) {
                mfVehicleCheckboxCache.expiresAt = 0;
                return true;
            }

            const associatedLabel =
                getAssociatedVehicleCheckboxLabel(
                    checkbox
                );

            if (
                associatedLabel &&
                associatedLabel !== element
            ) {
                try {
                    associatedLabel.click();
                } catch (_error) {}
            }

            if (checkbox.checked === true) {
                mfVehicleCheckboxCache.expiresAt = 0;
                return true;
            }

            const forced =
                forceVehicleCheckboxSelection(
                    checkbox
                );

            if (forced) {
                mfVehicleCheckboxCache.expiresAt = 0;
            }

            return forced &&
                checkbox.checked === true;
        }

        let clickIssued = false;

        try {
            element.click();
            clickIssued = true;
        } catch (_error) {}

        if (!clickIssued) {
            try {
                clickIssued =
                    realClickForQueueRestart(
                        element
                    );
            } catch (_error) {}
        }

        return clickIssued;
    }

    function sortVehicleCheckboxesByBestArrival(matches) {
        const getMetrics = input => {
            const now = Date.now();
            const cached = mfVehicleArrivalMetricCache.get(input);

            if (cached && now < cached.expiresAt) {
                return cached;
            }

            const journey =
                readMissionLoggerUnitJourneyMetrics(input);
            const metrics = {
                delay:
                    journey.estimatedEtaSeconds ?? 999999,
                distance:
                    journey.estimatedDistanceKm ?? 999999,
                expiresAt: now + 500
            };

            mfVehicleArrivalMetricCache.set(input, metrics);
            return metrics;
        };

        matches.sort((a, b) => {
            const metricsA = getMetrics(a);
            const metricsB = getMetrics(b);
            return (
                metricsA.delay - metricsB.delay ||
                metricsA.distance - metricsB.distance
            );
        });

        return matches;
    }

    function getEodResponseRequirementMode(
        originalName,
        mappedName
    ) {
        const values = [
            originalName,
            mappedName
        ].map(normaliseVehicleText);

        const normalEod = new Set([
            'eod response vehicle',
            'eod response vehicles',
            'required eod response vehicle',
            'required eod response vehicles'
        ]);
        const marineEod = new Set([
            'marine eod response vehicle',
            'marine eod response vehicles',
            'required marine eod response vehicle',
            'required marine eod response vehicles'
        ]);

        if (values.some(value => marineEod.has(value))) {
            return 'marine';
        }
        if (values.some(value => normalEod.has(value))) {
            return 'normal';
        }
        return '';
    }

    function isEodResponseVehicleCheckbox(input) {
        if (!input) return false;
        const typeIds = getVehicleTypeIdentifiers(input);
        if (typeIds.includes('110')) return true;
        if (typeIds.length > 0) return false;
        return getExtendedVehicleValues(input).some(value => {
            const normalised = normaliseVehicleText(value);
            return normalised === 'eod response vehicle' ||
                normalised === 'eod response vehicles';
        });
    }

    function isMarineEodResponseVehicleCheckbox(input) {
        if (!input) return false;
        const typeIds = getVehicleTypeIdentifiers(input);
        if (typeIds.includes('113')) return true;
        if (typeIds.length > 0) return false;
        return getExtendedVehicleValues(input).some(value => {
            const normalised = normaliseVehicleText(value);
            return normalised === 'marine eod response vehicle' ||
                normalised === 'marine eod response vehicles';
        });
    }

    function getAllMatchingVehicleCheckboxes(originalName, mappedName, includeChecked) {
        // BASU, Welfare and HazMat share the same selected exact type-39 Fire OSU.
        if (isFireOperationalSupportRequirement(originalName, mappedName)) {
            return sortVehicleCheckboxesByBestArrival(getVehicleCheckboxSnapshot().filter(input => {
                if (input.disabled) return false;
                if (!includeChecked && input.checked) return false;
                return isFireOperationalSupportUnitCheckbox(input);
            }));
        }
        if (isFireEngineRequirement(originalName, mappedName)) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) return false;
                    if (!includeChecked && input.checked) return false;
                    return isFireEngineVehicleCheckbox(input);
                })
            );
        }

        const eodResponseMode =
            getEodResponseRequirementMode(
                originalName,
                mappedName
            );

        if (eodResponseMode) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) return false;
                    if (!includeChecked && input.checked) return false;
                    return eodResponseMode === 'marine'
                        ? isMarineEodResponseVehicleCheckbox(input)
                        : isEodResponseVehicleCheckbox(input);
                })
            );
        }

        const candidates = getVehicleMatchCandidates(originalName, mappedName);
        const strictExactOnly = isAmbulanceTransportRequest(originalName, mappedName);
        const standardAmbulanceEtaPreferred = strictExactOnly;
        const ambulanceOfficerOnly =
            isAmbulanceOfficerRequirement(
                originalName,
                mappedName
            );
        const sartecPrefixOnly = isSartecRequirement(
            originalName,
            mappedName
        );

        const rrvTypeOnly =
            isRrvRequirement(
                originalName,
                mappedName
            );

        const aerialApplianceOrRescueStairsPreferred =
            isAerialApplianceOrRescueStairsRequirement(
                originalName
            );

        const fireEngineOrRivPreferred =
            isFireEngineOrRivRequirement(
                originalName
            );

        const rivTypeOnly =
            isRivRequirement(
                originalName,
                mappedName
            );

        const rivOrMajorFoamTenderPreferred =
            isRivOrMajorFoamTenderRequirement(
                originalName,
                mappedName
            );

        const policeAirMode =
            getPoliceAirRequirementMode(
                originalName,
                mappedName
            );

        const policeCarOnly =
            isPoliceCarRequirement(
                originalName,
                mappedName
            );

        const roadRailOnly =
            isRoadRailUnitRequirement(
                originalName,
                mappedName
            );

        const flatbedRecoveryOnly =
            isFlatbedRecoveryVehicleRequirement(
                originalName,
                mappedName
            );

        const hgvRecoveryOnly =
            isHgvRecoveryVehicleRequirement(
                originalName,
                mappedName
            );

        const searchDogUnitOnly =
            isSearchDogUnitRequirement(
                originalName,
                mappedName
            );

        const crvOnly =
            isCrvRequirement(
                originalName,
                mappedName
            );

        const controlVanOnly =
            isControlVanRequirement(
                originalName,
                mappedName
            );

        const airAmbulanceOnly =
            isAirAmbulanceRequirement(
                originalName,
                mappedName
            );

        const criticalCareTransferOnly =
            isCriticalCareTransferAmbulanceRequirement(
                originalName,
                mappedName
            );

        const genericCriticalCare =
            isGenericCriticalCareRequirement(
                originalName,
                mappedName
            );

        const atvCarrierOnly =
            isAtvCarrierRequirement(
                originalName,
                mappedName
            );

        const seagoingVesselOnly =
            isSeagoingVesselRequirement(
                originalName,
                mappedName
            );

        const dogSupportOnly =
            isDogSupportUnitRequirement(
                originalName,
                mappedName
            );

        const operationalSupportOnly =
            isOperationalSupportOrSarVehicleRequirement(
                originalName,
                mappedName
            );

        const generic4x4Only =
            isGeneric4x4VehicleRequirement(
                originalName,
                mappedName
            );

        const mountainRescue4x4Preferred =
            isMountainRescueOrSar4x4Requirement(
                originalName,
                mappedName
            );

        const iccuPreferred =
            isIccuOrAmbulanceControlRequirement(
                originalName,
                mappedName
            );


        if (standardAmbulanceEtaPreferred) {
            const orderedAmbulanceMatches =
                sortVehicleCheckboxesByBestArrival(
                    getVehicleCheckboxSnapshot().filter(input => {
                        if (input.disabled) return false;
                        if (!includeChecked && input.checked) return false;
                        return isStandardAmbulanceEtaVehicleCheckbox(input);
                    })
                );

            if (mfDebugEnabled) {
                const roadCount = orderedAmbulanceMatches.filter(input =>
                    getVehicleTypeIdentifiers(input).includes('5')
                ).length;
                const hemsCount = orderedAmbulanceMatches.filter(input =>
                    getVehicleTypeIdentifiers(input).includes('9')
                ).length;
                debugLog(
                    'AMBULANCE ETA PRIORITY',
                    `${originalName} -> ${mappedName} | road=${roadCount} | HEMS=${hemsCount} | first=${orderedAmbulanceMatches[0] ? getVehicleDebugName(orderedAmbulanceMatches[0]) : 'none'}`
                );
            }

            return orderedAmbulanceMatches;
        }

        if (roadRailOnly) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) return false;
                    if (!includeChecked && input.checked) return false;
                    return isRoadRailUnitVehicleCheckbox(input);
                })
            );
        }

        if (flatbedRecoveryOnly) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) return false;
                    if (!includeChecked && input.checked) return false;
                    return isFlatbedRecoveryVehicleCheckbox(input);
                })
            );
        }

        if (searchDogUnitOnly) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) return false;
                    if (!includeChecked && input.checked) return false;
                    return isSearchDogUnitVehicleCheckbox(input);
                })
            );
        }

        if (hgvRecoveryOnly) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) return false;
                    if (!includeChecked && input.checked) return false;
                    return isHgvRecoveryVehicleCheckbox(input);
                })
            );
        }

        if (crvOnly) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) return false;
                    if (!includeChecked && input.checked) return false;
                    return isCrvVehicleCheckbox(input);
                })
            );
        }

        if (controlVanOnly) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) return false;
                    if (!includeChecked && input.checked) return false;
                    return isControlVanVehicleCheckbox(input);
                })
            );
        }

        if (airAmbulanceOnly) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) return false;
                    if (!includeChecked && input.checked) return false;
                    return isAirAmbulanceVehicleCheckbox(input);
                })
            );
        }

        if (criticalCareTransferOnly) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) return false;
                    if (!includeChecked && input.checked) return false;
                    return isCriticalCareTransferAmbulanceCheckbox(input);
                })
            );
        }

        if (genericCriticalCare) {
            const registry = readPersonnelTrainingRegistry();
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) return false;
                    if (!includeChecked && input.checked) return false;
                    return isGenericCriticalCareVehicleCheckbox(input, registry);
                })
            );
        }

        if (seagoingVesselOnly) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) return false;
                    if (!includeChecked && input.checked) return false;
                    return isSeagoingVesselCheckbox(input);
                })
            );
        }

        if (
            aerialApplianceOrRescueStairsPreferred
        ) {
            const orderedMatches =
                getAerialApplianceOrRescueStairsVehicleCheckboxes(
                    includeChecked
                );

            if (mfDebugEnabled) {
                const rescueStairsCount =
                    orderedMatches.filter(
                        isRescueStairsVehicleCheckbox
                    ).length;

                const carpCount =
                    orderedMatches.length -
                    rescueStairsCount;

                debugLog(
                    'RESCUE STAIRS CARP PRIORITY',
                    `${originalName} -> ${mappedName} | Rescue Stairs matches=${rescueStairsCount} first | CARP remainder matches=${carpCount} | returned=${orderedMatches.length}`
                );
            }

            return orderedMatches;
        }

        if (
            fireEngineOrRivPreferred
        ) {
            const orderedMatches =
                getFireEngineOrRivVehicleCheckboxes(
                    includeChecked
                );

            if (mfDebugEnabled) {
                const rivCount =
                    orderedMatches.filter(
                        isRivVehicleCheckbox
                    ).length;

                const rescuePumpCount =
                    orderedMatches.length -
                    rivCount;

                debugLog(
                    'RIV FIRE ENGINE PRIORITY',
                    `${originalName} -> ${mappedName} | RIV matches=${rivCount} first | Rescue Pump remainder matches=${rescuePumpCount} | returned=${orderedMatches.length}`
                );
            }

            return orderedMatches;
        }


        if (
            rivOrMajorFoamTenderPreferred
        ) {
            const eligible =
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) {
                        return false;
                    }

                    if (
                        !includeChecked &&
                        input.checked
                    ) {
                        return false;
                    }

                    return (
                        isRivVehicleCheckbox(
                            input
                        ) ||
                        isMajorFoamTenderVehicleCheckbox(
                            input
                        )
                    );
                });

            const rivMatches =
                sortVehicleCheckboxesByBestArrival(
                    eligible.filter(
                        isRivVehicleCheckbox
                    )
                );

            if (
                rivMatches.length >
                0
            ) {
                return rivMatches;
            }

            return sortVehicleCheckboxesByBestArrival(
                eligible.filter(
                    isMajorFoamTenderVehicleCheckbox
                )
            );
        }

        if (atvCarrierOnly) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) {
                        return false;
                    }

                    if (
                        !includeChecked &&
                        input.checked
                    ) {
                        return false;
                    }

                    return isAtvCarrierCheckbox(
                        input
                    );
                })
            );
        }

        if (dogSupportOnly) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) {
                        return false;
                    }

                    if (
                        !includeChecked &&
                        input.checked
                    ) {
                        return false;
                    }

                    return isDogSupportUnitCheckbox(
                        input
                    );
                })
            );
        }

        if (operationalSupportOnly) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) return false;
                    if (!includeChecked && input.checked) return false;
                    return isOperationalSupportVanCheckbox(input);
                })
            );
        }

        if (iccuPreferred) {
            const eligible =
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) {
                        return false;
                    }

                    if (
                        !includeChecked &&
                        input.checked
                    ) {
                        return false;
                    }

                    return (
                        isIccuVehicleCheckbox(
                            input
                        ) ||
                        isAmbulanceControlUnitCheckbox(
                            input
                        )
                    );
                });

            const iccuMatches =
                sortVehicleCheckboxesByBestArrival(
                    eligible.filter(
                        isIccuVehicleCheckbox
                    )
                );

            const ambulanceControlFallbackMatches =
                sortVehicleCheckboxesByBestArrival(
                    eligible.filter(
                        input =>
                            !isIccuVehicleCheckbox(input) &&
                            isAmbulanceControlUnitCheckbox(input)
                    )
                );

            return [
                ...iccuMatches,
                ...ambulanceControlFallbackMatches
            ];
        }

        if (generic4x4Only) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) {
                        return false;
                    }

                    if (
                        !includeChecked &&
                        input.checked
                    ) {
                        return false;
                    }

                    return isGeneric4x4VehicleCheckbox(
                        input
                    );
                })
            );
        }

        if (mountainRescue4x4Preferred) {
            const eligible =
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) {
                        return false;
                    }

                    if (
                        !includeChecked &&
                        input.checked
                    ) {
                        return false;
                    }

                    return (
                        isMountainRescue4x4Checkbox(
                            input
                        ) ||
                        isSar4x4Checkbox(
                            input
                        )
                    );
                });

            const mountainRescueMatches =
                sortVehicleCheckboxesByBestArrival(
                    eligible.filter(
                        isMountainRescue4x4Checkbox
                    )
                );

            const sarFallbackMatches =
                sortVehicleCheckboxesByBestArrival(
                    eligible.filter(
                        isSar4x4Checkbox
                    )
                );

            const orderedMatches = [
                ...mountainRescueMatches,
                ...sarFallbackMatches
            ];

            if (mfDebugEnabled) {
                debugLog(
                    'MOUNTAIN 4X4 PRIORITY',
                    `${originalName} -> ${mappedName} | Mountain Rescue 4x4 matches=${mountainRescueMatches.length} first | SAR 4x4 matches=${sarFallbackMatches.length} fallback | returned=${orderedMatches.length}`
                );
            }

            return orderedMatches;
        }

        if (policeAirMode) {
            const eligible =
                getVehicleCheckboxSnapshot().filter(input => {
                    if (input.disabled) {
                        return false;
                    }

                    if (
                        !includeChecked &&
                        input.checked
                    ) {
                        return false;
                    }

                    if (policeAirMode === 'helicopter') {
                        return isPoliceHelicopterCheckbox(input);
                    }

                    if (policeAirMode === 'drone') {
                        return isPoliceDroneCheckbox(input);
                    }

                    if (policeAirMode === 'generic-drone') {
                        return isGenericDroneCheckbox(input);
                    }

                    return (
                        isPoliceHelicopterCheckbox(input) ||
                        isPoliceDroneCheckbox(input)
                    );
                });

            if (policeAirMode === 'helicopter') {
                return sortVehicleCheckboxesByBestArrival(
                    eligible.filter(
                        isPoliceHelicopterCheckbox
                    )
                );
            }

            if (policeAirMode === 'drone') {
                return sortVehicleCheckboxesByBestArrival(
                    eligible.filter(
                        isPoliceDroneCheckbox
                    )
                );
            }

            if (policeAirMode === 'generic-drone') {
                return sortVehicleCheckboxesByBestArrival(
                    eligible.filter(
                        isGenericDroneCheckbox
                    )
                );
            }

            const sortedDroneMatches =
                sortVehicleCheckboxesByBestArrival(
                    eligible.filter(
                        isPoliceDroneCheckbox
                    )
                );

            const sortedHelicopterMatches =
                sortVehicleCheckboxesByBestArrival(
                    eligible.filter(
                        isPoliceHelicopterCheckbox
                    )
                );

            // Flexible wording only: Drone first, Police Helicopter fallback.
            return [
                ...sortedDroneMatches,
                ...sortedHelicopterMatches
            ];
        }

        if (policeCarOnly) {
            const registry =
                readPersonnelTrainingRegistry();

            const policeCarCandidates =
                sortVehicleCheckboxesByBestArrival(
                    getVehicleCheckboxSnapshot().filter(input => {
                        if (input.disabled) return false;
                        if (!includeChecked && input.checked) return false;

                        return isOrdinaryPoliceIrvCheckboxEligible(
                            input,
                            registry,
                            {
                                allowUnknown: true,
                                allowProtected: true
                            }
                        );
                    })
                );

            return orderOrdinaryPoliceIrvCandidates(
                policeCarCandidates,
                registry
            );
        }

        const matches = getVehicleCheckboxSnapshot().filter(input => {
            if (input.disabled) return false;
            if (!includeChecked && input.checked) return false;

            if (ambulanceOfficerOnly) {
                return isAmbulanceOfficerVehicleCheckbox(
                    input
                );
            }

            if (sartecPrefixOnly) {
                return isSartecVehicleCheckbox(
                    input
                );
            }

            if (rrvTypeOnly) {
                return isRrvVehicleCheckbox(
                    input
                );
            }

            if (rivTypeOnly) {
                return isRivVehicleCheckbox(
                    input
                );
            }

            if (policeCarOnly) {
                return isPoliceCarVehicleCheckbox(
                    input
                );
            }

            const values = getCheckboxVehicleValues(input);
            return vehicleValuesMatchCandidates(values, candidates, strictExactOnly);
        });

        if (mfDebugEnabled && strictExactOnly) {
            debugLog('AMBULANCE STRICT', `${originalName} -> ${mappedName} | exact-match boxes=${matches.length}`);
        }

        if (mfDebugEnabled && sartecPrefixOnly) {
            debugLog(
                'SARTEC PREFIX',
                `${originalName} -> ${mappedName} | displayed-name-prefix boxes=${matches.length}`
            );
        }

        if (
            mfDebugEnabled &&
            rrvTypeOnly
        ) {
            debugLog(
                'RRV STRICT',
                `${originalName} -> ${mappedName} | RRV type boxes=${matches.length}`
            );
        }

        if (
            mfDebugEnabled &&
            rivTypeOnly
        ) {
            debugLog(
                'RIV STRICT',
                `${originalName} -> ${mappedName} | RIV type boxes=${matches.length}`
            );
        }

        if (
            mfDebugEnabled &&
            policeCarOnly
        ) {
            debugLog(
                'POLICE CAR STRICT',
                `${originalName} -> ${mappedName} | Police Car/IRV type boxes=${matches.length}`
            );
        }

        return sortVehicleCheckboxesByBestArrival(matches);
    }

    function getMatchingVehicleCheckboxes(originalName, mappedName) {
        return getAllMatchingVehicleCheckboxes(originalName, mappedName, false);
    }

    function countSelectedMatchingVehicles(originalName, mappedName) {
        if (isFireOperationalSupportRequirement(originalName, mappedName)) {
            return getVehicleCheckboxSnapshot().filter(input =>
                input.checked && isFireOperationalSupportUnitCheckbox(input)).length;
        }
        if (isFireEngineRequirement(originalName, mappedName)) {
            return getVehicleCheckboxSnapshot().filter(input => (
                input.checked &&
                isFireEngineVehicleCheckbox(input)
            )).length;
        }

        const eodResponseMode =
            getEodResponseRequirementMode(
                originalName,
                mappedName
            );

        if (eodResponseMode) {
            return getVehicleCheckboxSnapshot().filter(input => {
                if (!input.checked) return false;
                return eodResponseMode === 'marine'
                    ? isMarineEodResponseVehicleCheckbox(input)
                    : isEodResponseVehicleCheckbox(input);
            }).length;
        }

        const candidates = getVehicleMatchCandidates(originalName, mappedName);
        const strictExactOnly = isAmbulanceTransportRequest(originalName, mappedName);
        const standardAmbulanceEtaPreferred = strictExactOnly;
        const ambulanceOfficerOnly =
            isAmbulanceOfficerRequirement(
                originalName,
                mappedName
            );
        const sartecPrefixOnly = isSartecRequirement(originalName, mappedName);
        const rrvTypeOnly = isRrvRequirement(originalName, mappedName);
        const aerialApplianceOrRescueStairsPreferred =
            isAerialApplianceOrRescueStairsRequirement(
                originalName
            );
        const fireEngineOrRivPreferred =
            isFireEngineOrRivRequirement(
                originalName
            );
        const rivTypeOnly = isRivRequirement(originalName, mappedName);

        const rivOrMajorFoamTenderPreferred =
            isRivOrMajorFoamTenderRequirement(
                originalName,
                mappedName
            );
        const policeAirMode = getPoliceAirRequirementMode(originalName, mappedName);
        const policeCarOnly = isPoliceCarRequirement(originalName, mappedName);
        const roadRailOnly = isRoadRailUnitRequirement(originalName, mappedName);
        const flatbedRecoveryOnly =
            isFlatbedRecoveryVehicleRequirement(originalName, mappedName);
        const hgvRecoveryOnly =
            isHgvRecoveryVehicleRequirement(originalName, mappedName);
        const searchDogUnitOnly =
            isSearchDogUnitRequirement(originalName, mappedName);
        const crvOnly = isCrvRequirement(originalName, mappedName);
        const controlVanOnly = isControlVanRequirement(originalName, mappedName);
        const airAmbulanceOnly = isAirAmbulanceRequirement(originalName, mappedName);
        const criticalCareTransferOnly = isCriticalCareTransferAmbulanceRequirement(originalName, mappedName);
        const genericCriticalCare = isGenericCriticalCareRequirement(originalName, mappedName);
        const criticalCareRegistry = genericCriticalCare ? readPersonnelTrainingRegistry() : null;
        const atvCarrierOnly = isAtvCarrierRequirement(originalName, mappedName);
        const seagoingVesselOnly = isSeagoingVesselRequirement(originalName, mappedName);
        const dogSupportOnly = isDogSupportUnitRequirement(originalName, mappedName);
        const operationalSupportOnly =
            isOperationalSupportOrSarVehicleRequirement(
                originalName,
                mappedName
            );

        const generic4x4Only =
            isGeneric4x4VehicleRequirement(
                originalName,
                mappedName
            );

        const mountainRescue4x4Preferred =
            isMountainRescueOrSar4x4Requirement(
                originalName,
                mappedName
            );
        const iccuPreferred =
            isIccuOrAmbulanceControlRequirement(
                originalName,
                mappedName
            );

        if (
            aerialApplianceOrRescueStairsPreferred
        ) {
            return getVehicleCheckboxSnapshot().filter(input => {
                if (!input.checked) return false;

                return (
                    isRescueStairsVehicleCheckbox(
                        input
                    ) ||
                    isCarpVehicleCheckbox(
                        input
                    )
                );
            }).length;
        }

        if (
            fireEngineOrRivPreferred
        ) {
            return getVehicleCheckboxSnapshot().filter(input => {
                if (!input.checked) return false;

                return (
                    isRivVehicleCheckbox(
                        input
                    ) ||
                    isRescuePumpVehicleCheckbox(
                        input
                    )
                );
            }).length;
        }

        if (
            rivOrMajorFoamTenderPreferred
        ) {
            const selected =
                getVehicleCheckboxSnapshot().filter(
                    input =>
                        input.checked
                );

            const selectedRivs =
                selected.filter(
                    isRivVehicleCheckbox
                ).length;

            if (
                selectedRivs >
                0
            ) {
                return selectedRivs;
            }

            return selected.filter(
                isMajorFoamTenderVehicleCheckbox
            ).length;
        }

        let count = 0;

        for (const input of getVehicleCheckboxSnapshot()) {
            // A vehicle that is already checked still counts toward the
            // requirement even when MissionChief disables its checkbox after
            // selection. V10.6.48 skipped disabled checked boxes, which made a
            // successfully selected vehicle look missing during verification.
            if (!input.checked) continue;

            let matches = false;

            if (ambulanceOfficerOnly) {
                matches = isAmbulanceOfficerVehicleCheckbox(
                    input
                );
            } else if (standardAmbulanceEtaPreferred) {
                matches = isStandardAmbulanceEtaVehicleCheckbox(input);
            } else if (roadRailOnly) {
                matches = isRoadRailUnitVehicleCheckbox(input);
            } else if (flatbedRecoveryOnly) {
                matches = isFlatbedRecoveryVehicleCheckbox(input);
            } else if (searchDogUnitOnly) {
                matches = isSearchDogUnitVehicleCheckbox(input);
            } else if (hgvRecoveryOnly) {
                matches = isHgvRecoveryVehicleCheckbox(input);
            } else if (crvOnly) {
                matches = isCrvVehicleCheckbox(input);
            } else if (controlVanOnly) {
                matches = isControlVanVehicleCheckbox(input);
            } else if (airAmbulanceOnly) {
                matches = isAirAmbulanceVehicleCheckbox(input);
            } else if (criticalCareTransferOnly) {
                matches = isCriticalCareTransferAmbulanceCheckbox(input);
            } else if (genericCriticalCare) {
                matches = isGenericCriticalCareVehicleCheckbox(input, criticalCareRegistry);
            } else if (seagoingVesselOnly) {
                matches = isSeagoingVesselCheckbox(
                    input
                );
            } else if (atvCarrierOnly) {
                matches = isAtvCarrierCheckbox(
                    input
                );
            } else if (dogSupportOnly) {
                matches = isDogSupportUnitCheckbox(
                    input
                );
            } else if (operationalSupportOnly) {
                matches = isOperationalSupportVanCheckbox(input);
            } else if (iccuPreferred) {
                matches =
                    isIccuVehicleCheckbox(input) ||
                    isAmbulanceControlUnitCheckbox(input);
            } else if (generic4x4Only) {
                matches = isGeneric4x4VehicleCheckbox(input);
            } else if (mountainRescue4x4Preferred) {
                matches =
                    isMountainRescue4x4Checkbox(input) ||
                    isSar4x4Checkbox(input);
            } else if (policeAirMode === 'helicopter') {
                matches = isPoliceHelicopterCheckbox(input);
            } else if (policeAirMode === 'drone') {
                matches = isPoliceDroneCheckbox(input);
            } else if (policeAirMode === 'generic-drone') {
                matches = isGenericDroneCheckbox(input);
            } else if (policeAirMode === 'flexible') {
                matches =
                    isPoliceHelicopterCheckbox(input) ||
                    isPoliceDroneCheckbox(input);
            } else if (sartecPrefixOnly) {
                matches = isSartecVehicleCheckbox(input);
            } else if (rrvTypeOnly) {
                matches = isRrvVehicleCheckbox(input);
            } else if (rivTypeOnly) {
                matches = isRivVehicleCheckbox(input);
            } else if (policeCarOnly) {
                // Any selected exact type-8 IRV satisfies generic Police
                // attendance. Training data controls preference only; named
                // specialist requirements still use their strict selectors.
                matches = isPoliceCarVehicleCheckbox(input);
            } else {
                matches = vehicleValuesMatchCandidates(
                    getCheckboxVehicleValues(input),
                    candidates,
                    strictExactOnly
                );
            }

            if (matches) count += 1;
        }

        return count;
    }

    function refreshVehicleRequirementCounters() {
        // V9.2.1: DISPLAY ONLY. This updates the panel counters from the current ticked checkboxes.
        // It must not decide what to send and must not trigger any selections.
        vehicleLoadState.rows.forEach(row => {
            const required = Number(row.required || 0);
            const selected = countSelectedMatchingVehicles(row.originalName, row.mappedName);
            row.selected = Math.min(selected, required);
        });
    }

    function findUnitButton(mappedName, originalName) {
        if (isFireOperationalSupportRequirement(originalName, mappedName)) {
            return sortVehicleCheckboxesByBestArrival(getVehicleCheckboxSnapshot().filter(input =>
                !input.disabled && !input.checked && isFireOperationalSupportUnitCheckbox(input)))[0] || null;
        }
        if (isFireEngineRequirement(originalName, mappedName)) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => (
                    !input.disabled &&
                    !input.checked &&
                    isFireEngineVehicleCheckbox(input)
                ))
            )[0] || null;
        }

        const requestedName =
            originalName ||
            mappedName;


        if (
            isAmbulanceTransportRequest(
                requestedName,
                mappedName
            ) ||
            isCrvRequirement(
                requestedName,
                mappedName
            ) ||
            isControlVanRequirement(
                requestedName,
                mappedName
            ) ||
            isAirAmbulanceRequirement(
                requestedName,
                mappedName
            ) ||
            isCriticalCareTransferAmbulanceRequirement(
                requestedName,
                mappedName
            ) ||
            isGenericCriticalCareRequirement(
                requestedName,
                mappedName
            )
        ) {
            return getAllMatchingVehicleCheckboxes(
                requestedName,
                mappedName,
                false
            )[0] || null;
        }

        if (
            isSeagoingVesselRequirement(
                requestedName,
                mappedName
            )
        ) {
            return getVehicleCheckboxSnapshot(true).find(input => {
                return (
                    !input.disabled &&
                    !input.checked &&
                    isSeagoingVesselCheckbox(input)
                );
            }) || null;
        }

        if (
            isDogSupportUnitRequirement(
                requestedName,
                mappedName
            )
        ) {
            // Never use the AAO/ARR group button as proof of a DSU selection.
            // It previously returned a successful click while no matching
            // vehicle checkbox was checked, causing the repeated false
            // "Final missing units: Dog Support Units" popup.
            return getVehicleCheckboxSnapshot(
                true
            ).find(input => {
                return (
                    !input.disabled &&
                    !input.checked &&
                    isDogSupportUnitCheckbox(
                        input
                    )
                );
            }) || null;
        }

        if (
            isOperationalSupportOrSarVehicleRequirement(
                requestedName,
                mappedName
            )
        ) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => (
                    !input.disabled &&
                    !input.checked &&
                    isOperationalSupportVanCheckbox(input)
                ))
            )[0] || null;
        }

        if (
            isIccuOrAmbulanceControlRequirement(
                requestedName,
                mappedName
            )
        ) {
            const available =
                getVehicleCheckboxSnapshot().filter(input => {
                    return (
                        !input.disabled &&
                        !input.checked
                    );
                });

            const iccuCheckbox =
                available.find(
                    isIccuVehicleCheckbox
                );

            if (iccuCheckbox) {
                return iccuCheckbox;
            }

            const iccuButton =
                queryVehicleSelectionElements('a[search_attribute]').find(anchor => {
                    const value =
                        normaliseVehicleText(
                            anchor.getAttribute(
                                'search_attribute'
                            )
                        );

                    return (
                        value === 'iccu' ||
                        value === 'iccus' ||
                        value.includes(
                            'incident command and control unit'
                        ) ||
                        /(?:^|\b)iccu(?:s)?(?:\b|$)/i.test(value)
                    );
                });

            if (iccuButton) {
                return iccuButton;
            }

            const ambulanceControlCheckbox =
                available.find(
                    isAmbulanceControlUnitCheckbox
                );

            if (ambulanceControlCheckbox) {
                return ambulanceControlCheckbox;
            }

            return queryVehicleSelectionElements('a[search_attribute]').find(anchor => {
                const value =
                    normaliseVehicleText(
                        anchor.getAttribute(
                            'search_attribute'
                        )
                    );

                return (
                    value === 'acu' ||
                    value === 'acus' ||
                    value.includes(
                        'ambulance control unit'
                    ) ||
                    /(?:^|\b)acu(?:s)?(?:\b|$)/i.test(value)
                );
            }) || null;
        }

        if (
            isGeneric4x4VehicleRequirement(
                requestedName,
                mappedName
            )
        ) {
            return sortVehicleCheckboxesByBestArrival(
                getVehicleCheckboxSnapshot().filter(input => {
                    return (
                        !input.disabled &&
                        !input.checked &&
                        isGeneric4x4VehicleCheckbox(
                            input
                        )
                    );
                })
            )[0] || null;
        }

        if (
            isMountainRescueOrSar4x4Requirement(
                requestedName,
                mappedName
            )
        ) {
            const available =
                getVehicleCheckboxSnapshot().filter(input => {
                    return (
                        !input.disabled &&
                        !input.checked
                    );
                });

            const mountainRescueMatches =
                sortVehicleCheckboxesByBestArrival(
                    available.filter(
                        isMountainRescue4x4Checkbox
                    )
                );

            if (mountainRescueMatches.length > 0) {
                return mountainRescueMatches[0];
            }

            const sarMatches =
                sortVehicleCheckboxesByBestArrival(
                    available.filter(
                        isSar4x4Checkbox
                    )
                );

            // Do not fall back to an AAO/ARR group button. A group-button click
            // cannot be verified as a selected vehicle and caused the false
            // "Final missing units: 4x4 Vehicles" popup.
            return sarMatches[0] || null;
        }

        if (
            isSartecRequirement(
                requestedName,
                mappedName
            )
        ) {
            // SARTEC must only come from the actual available-vehicle
            // checkbox list and must begin the displayed vehicle name.
            return getVehicleCheckboxSnapshot().find(input => {
                return (
                    !input.disabled &&
                    !input.checked &&
                    isSartecVehicleCheckbox(
                        input
                    )
                );
            }) || null;
        }

        if (
            isRrvRequirement(
                requestedName,
                mappedName
            )
        ) {
            return getVehicleCheckboxSnapshot().find(input => {
                return (
                    !input.disabled &&
                    !input.checked &&
                    isRrvVehicleCheckbox(
                        input
                    )
                );
            }) || null;
        }

        if (
            isRivRequirement(
                requestedName,
                mappedName
            )
        ) {
            return getVehicleCheckboxSnapshot().find(input => {
                return (
                    !input.disabled &&
                    !input.checked &&
                    isRivVehicleCheckbox(
                        input
                    )
                );
            }) || null;
        }

        const policeAirMode =
            getPoliceAirRequirementMode(
                requestedName,
                mappedName
            );

        if (policeAirMode) {
            const eligible =
                getVehicleCheckboxSnapshot().filter(input => {
                    return (
                        !input.disabled &&
                        !input.checked
                    );
                });

            if (policeAirMode === 'helicopter') {
                return eligible.find(
                    isPoliceHelicopterCheckbox
                ) || null;
            }

            if (policeAirMode === 'drone') {
                return eligible.find(
                    isPoliceDroneCheckbox
                ) || null;
            }

            if (policeAirMode === 'generic-drone') {
                return sortVehicleCheckboxesByBestArrival(
                    eligible.filter(
                        isGenericDroneCheckbox
                    )
                )[0] || null;
            }

            return (
                eligible.find(
                    isPoliceDroneCheckbox
                ) ||
                eligible.find(
                    isPoliceHelicopterCheckbox
                ) ||
                null
            );
        }

        if (
            isPoliceCarRequirement(
                requestedName,
                mappedName
            )
        ) {
            return getAllMatchingVehicleCheckboxes(
                requestedName,
                mappedName,
                false
            )[0] || null;
        }

        const candidates = getVehicleMatchCandidates(requestedName, mappedName);

        const strictExactOnly = isAmbulanceTransportRequest(requestedName, mappedName);

        const checkbox = getVehicleCheckboxSnapshot().find(input => {
            if (input.disabled || input.checked) return false;
            const values = getCheckboxVehicleValues(input);
            return vehicleValuesMatchCandidates(values, candidates, strictExactOnly);
        });

        if (checkbox) return checkbox;

        const button = queryVehicleSelectionElements('a[search_attribute]').find(anchor => {
            const value = normaliseVehicleText(anchor.getAttribute('search_attribute'));
            return candidates.some(candidate => value === candidate || value.includes(candidate));
        });

        return button || null;
    }

