        panel.appendChild(controlBody);

        function syncMissionControlCollapseButton() {
            const expanded = !mfMissionControlCollapsed;
            controlMinimizeBtn.textContent = missionFinderIosSafari
                ? (expanded ? '▴' : '▾')
                : (expanded ? '−' : '+');
            controlMinimizeBtn.title = expanded
                ? 'Collapse Mission Control'
                : 'Expand Mission Control';
            controlMinimizeBtn.setAttribute(
                'aria-label',
                controlMinimizeBtn.title
            );
            controlMinimizeBtn.setAttribute(
                'aria-controls',
                'mf-control-body'
            );
            controlMinimizeBtn.setAttribute(
                'aria-expanded',
                String(expanded)
            );
            dragHandle.setAttribute(
                'aria-controls',
                'mf-control-body'
            );
            dragHandle.setAttribute(
                'aria-expanded',
                String(expanded)
            );
            panel.dataset.collapsed =
                String(mfMissionControlCollapsed);

            if (!missionFinderIosSafari) {
                wrapper.classList.toggle(
                    'mf-compact-shell-collapsed',
                    mfMissionControlCollapsed
                );
            }

            if (missionFinderIphoneSafari) {
                const expanded =
                    !mfMissionControlCollapsed;
                iphoneMissionLauncherButton.classList.toggle(
                    'mf2026-active',
                    expanded
                );
                iphoneMissionLauncherButton.setAttribute(
                    'aria-pressed',
                    String(expanded)
                );
                iphoneMissionLauncherButton.setAttribute(
                    'aria-expanded',
                    String(expanded)
                );
            }
        }

        function toggleMissionControlCollapsed() {
            if (missionFinderIphoneSafari) {
                toggleIphoneLauncherPanel('mission');
                return;
            }

            mfMissionControlCollapsed = !mfMissionControlCollapsed;
            localStorage.setItem(
                MF_CONTROL_COLLAPSED_KEY,
                String(mfMissionControlCollapsed)
            );
            panel.classList.toggle(
                'mf2026-control-collapsed',
                mfMissionControlCollapsed
            );
            syncMissionControlCollapseButton();

            if (!mfMissionControlCollapsed) {
                renderVehicleLoadList();
            }

            requestAnimationFrame(() => {
                keepMissionFinderWindowOnScreen(wrapper);
            });
        }

        syncMissionControlCollapseButton();

        function consumeIphoneDisclosureEvent(event) {
            if (!missionFinderIphoneSafari || !event) return;
            event.preventDefault();
            event.stopPropagation();
            event.stopImmediatePropagation?.();
        }

        controlMinimizeBtn.addEventListener(
            'click',
            function(event) {
                consumeIphoneDisclosureEvent(event);
                toggleMissionControlCollapsed();
            }
        );

        dragHandle.addEventListener('click', function(event) {
            if (missionFinderIphoneSafari) {
                consumeIphoneDisclosureEvent(event);
                toggleMissionControlCollapsed();
                return;
            }

            if (mfMissionControlCollapsed) {
                toggleMissionControlCollapsed();
            }
        });

        if (missionFinderIphoneSafari) {
            dragHandle.setAttribute('role', 'button');
            dragHandle.tabIndex = 0;
            dragHandle.addEventListener('keydown', function(event) {
                if (
                    event.key !== 'Enter' &&
                    event.key !== ' '
                ) {
                    return;
                }

                consumeIphoneDisclosureEvent(event);
                toggleMissionControlCollapsed();
            });
        }

