    function installMissionFinderResizeHandler() {
        if (mfMissionFinderResizeHandler) return;

        mfMissionFinderResizeHandler = function(event) {
            const activeWrapper =
                document.getElementById(
                    'mission-finder-wrapper'
                );

            if (!activeWrapper) return;

            if (
                isMissionFinderIosSafariWebsite()
                && (
                    event?.type === 'orientationchange'
                    || event?.type === 'pageshow'
                )
            ) {
                resetMissionFinderIosPosition(
                    activeWrapper,
                    event.type
                );
                return;
            }

            keepMissionFinderWindowOnScreen(
                activeWrapper
            );

            if (
                !isMissionFinderIosSafariWebsite()
                && mfKeepPanelPosition
            ) {
                saveMissionFinderWindowPosition(
                    activeWrapper,
                    'browser resized'
                );
            }
        };

        window.addEventListener(
            'resize',
            mfMissionFinderResizeHandler,
            { passive: true }
        );

        if (isMissionFinderIosSafariWebsite()) {
            window.addEventListener(
                'orientationchange',
                mfMissionFinderResizeHandler,
                { passive: true }
            );
            window.addEventListener(
                'pageshow',
                mfMissionFinderResizeHandler,
                { passive: true }
            );
            window.visualViewport?.addEventListener(
                'resize',
                mfMissionFinderResizeHandler,
                { passive: true }
            );
            window.visualViewport?.addEventListener(
                'scroll',
                mfMissionFinderResizeHandler,
                { passive: true }
            );
        }
    }

    function saveMissionFinderWindowPosition(panel, reason) {
        if (
            !panel
            || !mfKeepPanelPosition
            || isMissionFinderIosSafariWebsite()
        ) return;

        keepMissionFinderWindowOnScreen(panel);

        const left = panel.style.left ||
            `${Math.round(panel.getBoundingClientRect().left)}px`;

        const top = panel.style.top ||
            `${Math.round(panel.getBoundingClientRect().top)}px`;

        localStorage.setItem(MF_PANEL_LEFT_KEY, left);
        localStorage.setItem(MF_PANEL_TOP_KEY, top);

        if (mfDebugEnabled) {
            debugLog(
                'CONTROL WINDOW',
                `Saved position | reason=${reason || 'unknown'} | left=${left} | top=${top}`
            );
        }
    }

    function applySavedMissionFinderWindowPosition(panel, reason) {
        if (
            !panel
            || isMissionFinderIosSafariWebsite()
        ) return false;

        const left = localStorage.getItem(MF_PANEL_LEFT_KEY);
        const top = localStorage.getItem(MF_PANEL_TOP_KEY);

        if (!mfKeepPanelPosition || !left || !top) {
            return false;
        }

        panel.style.left = left;
        panel.style.top = top;
        panel.style.right = 'auto';
        panel.style.bottom = 'auto';
        panel.style.visibility = 'visible';

        requestAnimationFrame(() => {
            keepMissionFinderWindowOnScreen(panel);
            saveMissionFinderWindowPosition(
                panel,
                reason || 'apply saved position'
            );
        });

        if (mfDebugEnabled) {
            debugLog(
                'CONTROL WINDOW',
                `Applied saved position | reason=${reason || 'unknown'} | left=${left} | top=${top}`
            );
        }

        return true;
    }


    function getMissionFinderViewportBounds() {
        const viewport = window.visualViewport;
        const left = Math.max(
            0,
            Number(viewport?.offsetLeft || 0)
        );
        const top = Math.max(
            0,
            Number(viewport?.offsetTop || 0)
        );
        const width = Math.max(
            1,
            Number(
                viewport?.width
                || window.innerWidth
                || 1
            )
        );
        const height = Math.max(
            1,
            Number(
                viewport?.height
                || window.innerHeight
                || 1
            )
        );

        return {
            left,
            top,
            width,
            height,
            right: left + width,
            bottom: top + height
        };
    }

    function getMissionFinderIphoneCloseControlGutter() {
        const fallback = 48;

        if (!isMissionFinderIphoneSafariWebsite()) {
            return 0;
        }

        const bounds = getMissionFinderViewportBounds();
        const selectors = [
            '.control-btn-container .lightbox-close[title="Close"]',
            '.vm--modal .lightbox-close[title="Close"]',
            '.vm--modal-close',
            '.lightbox-close[aria-label="Close"]',
            'button.close[aria-label="Close"]'
        ];
        const candidates = [];

        selectors.forEach(selector => {
            try {
                document.querySelectorAll(selector).forEach(element => {
                    if (!candidates.includes(element)) {
                        candidates.push(element);
                    }
                });
            } catch (_error) {}
        });

        let gutter = fallback;

        candidates.forEach(element => {
            if (
                !element ||
                element.isConnected === false ||
                element.closest?.('#mission-finder-wrapper')
            ) {
                return;
            }

            try {
                const style = window.getComputedStyle(element);
                const rect = element.getBoundingClientRect();

                if (
                    style.display === 'none' ||
                    style.visibility === 'hidden' ||
                    rect.width <= 0 ||
                    rect.height <= 0 ||
                    rect.top > bounds.top + 150 ||
                    rect.right < bounds.right - 150
                ) {
                    return;
                }

                gutter = Math.max(
                    gutter,
                    bounds.right - rect.left + 8
                );
            } catch (_error) {}
        });

        return Math.min(92, Math.max(fallback, gutter));
    }



    function getMissionFinderIphoneNativeControlContainer() {
        if (!isMissionFinderIphoneSafariWebsite()) {
            return null;
        }

        const bounds = getMissionFinderViewportBounds();
        const selectors = [
            '.control-btn-container',
            '.control-btn-container button',
            '.control-btn-container a',
            '.control-btn-container [role="button"]',
            '.control-btn-container .lightbox-close',
            '.vm--modal button',
            '.vm--modal a',
            '.modal button',
            '.modal a',
            '.lightbox button',
            '.lightbox a'
        ];
        const candidates = [];

        selectors.forEach(selector => {
            try {
                document.querySelectorAll(selector).forEach(
                    element => {
                        if (!candidates.includes(element)) {
                            candidates.push(element);
                        }
                    }
                );
            } catch (_error) {}
        });

        const visibleControls = candidates
            .map(element => {
                try {
                    if (
                        !element ||
                        element.isConnected === false ||
                        element.closest?.(
                            '#mission-finder-wrapper'
                        )
                    ) {
                        return null;
                    }

                    const style =
                        window.getComputedStyle(element);
                    const rect =
                        element.getBoundingClientRect();
                    const elementName = String(
                        element.tagName || ''
                    ).toUpperCase();
                    const interactive = Boolean(
                        /^(?:BUTTON|A)$/.test(elementName) ||
                        element.matches?.(
                            '[role="button"], .lightbox-close, [aria-label], [title]'
                        )
                    );

                    if (
                        !interactive ||
                        style.display === 'none' ||
                        style.visibility === 'hidden' ||
                        style.pointerEvents === 'none' ||
                        rect.width <= 0 ||
                        rect.height <= 0 ||
                        rect.width > 76 ||
                        rect.height > 76 ||
                        rect.top > bounds.top + 155 ||
                        rect.bottom < bounds.top ||
                        rect.right < bounds.right - 150 ||
                        rect.left > bounds.right
                    ) {
                        return null;
                    }

                    return { element, rect };
                } catch (_error) {
                    return null;
                }
            })
            .filter(Boolean);

        if (!visibleControls.length) {
            return null;
        }

        const cluster = visibleControls.reduce(
            (result, entry) => {
                result.left = Math.min(
                    result.left,
                    entry.rect.left
                );
                result.top = Math.min(
                    result.top,
                    entry.rect.top
                );
                result.right = Math.max(
                    result.right,
                    entry.rect.right
                );
                result.bottom = Math.max(
                    result.bottom,
                    entry.rect.bottom
                );
                result.elements.push(entry.element);
                return result;
            },
            {
                left: Number.POSITIVE_INFINITY,
                top: Number.POSITIVE_INFINITY,
                right: Number.NEGATIVE_INFINITY,
                bottom: Number.NEGATIVE_INFINITY,
                elements: []
            }
        );

        cluster.width = cluster.right - cluster.left;
        cluster.height = cluster.bottom - cluster.top;
        cluster.capturedAt = Date.now();
        mfIphoneLauncherLastNativeCluster = cluster;
        return cluster;
    }



    function getMissionFinderIphoneLauncherGeometry(
        panelRect,
        bounds,
        clusterRect,
        fallbackGutter
    ) {
        const clearance = 16;
        const fallbackRight = Math.max(
            112,
            Number(fallbackGutter || 0) + 64
        );
        let launcherTop = 0;
        let launcherRight = fallbackRight;
        let launcherMaxWidth = Math.max(
            132,
            Number(bounds?.width || 0) -
                fallbackRight - 8
        );
        let expandedPanelTop = 42;

        if (
            clusterRect &&
            Number.isFinite(clusterRect.left) &&
            Number.isFinite(clusterRect.top) &&
            Number.isFinite(clusterRect.bottom)
        ) {
            launcherTop = Math.max(
                0,
                clusterRect.top - panelRect.top
            );
            launcherRight = Math.max(
                fallbackRight,
                panelRect.right -
                    clusterRect.left +
                    clearance
            );
            launcherMaxWidth = Math.max(
                132,
                clusterRect.left -
                    panelRect.left -
                    clearance
            );
            expandedPanelTop = Math.max(
                42,
                clusterRect.bottom -
                    panelRect.top + 8
            );
        }

        return {
            launcherTop: Math.ceil(launcherTop),
            launcherRight: Math.ceil(launcherRight),
            launcherMaxWidth: Math.floor(launcherMaxWidth),
            expandedPanelTop: Math.ceil(expandedPanelTop)
        };
    }

    function setMissionFinderIphoneStablePixelProperty(
        element,
        property,
        value,
        tolerance = 2
    ) {
        if (!element?.style) return false;
        const next = Math.round(Number(value) || 0);
        const previous = parseFloat(
            element.style.getPropertyValue(property)
        );

        if (
            Number.isFinite(previous) &&
            Math.abs(previous - next) <= tolerance
        ) {
            return false;
        }

        element.style.setProperty(
            property,
            `${next}px`
        );
        return true;
    }

    function syncMissionFinderIphoneLauncherPlacement(panel) {
        if (!panel) return false;

        if (!isMissionFinderIphoneSafariWebsite()) {
            [
                '--mf-iphone-launcher-top',
                '--mf-iphone-launcher-right',
                '--mf-iphone-launcher-max-width',
                '--mf-iphone-panel-top'
            ].forEach(property => {
                panel.style.removeProperty(property);
            });
            mfIphoneLauncherLastNativeCluster = null;
            return false;
        }

        const bounds = getMissionFinderViewportBounds();
        const panelRect = panel.getBoundingClientRect();
        const liveCluster =
            getMissionFinderIphoneNativeControlContainer();
        const cachedCluster =
            mfIphoneLauncherLastNativeCluster &&
            Date.now() -
                mfIphoneLauncherLastNativeCluster.capturedAt <
                2500
                ? mfIphoneLauncherLastNativeCluster
                : null;
        const cluster = liveCluster || cachedCluster;
        const geometry =
            getMissionFinderIphoneLauncherGeometry(
                panelRect,
                bounds,
                cluster,
                getMissionFinderIphoneCloseControlGutter()
            );

        let changed = false;
        changed =
            setMissionFinderIphoneStablePixelProperty(
                panel,
                '--mf-iphone-launcher-top',
                geometry.launcherTop
            ) || changed;
        changed =
            setMissionFinderIphoneStablePixelProperty(
                panel,
                '--mf-iphone-launcher-right',
                geometry.launcherRight
            ) || changed;
        changed =
            setMissionFinderIphoneStablePixelProperty(
                panel,
                '--mf-iphone-launcher-max-width',
                geometry.launcherMaxWidth
            ) || changed;
        changed =
            setMissionFinderIphoneStablePixelProperty(
                panel,
                '--mf-iphone-panel-top',
                geometry.expandedPanelTop
            ) || changed;

        return changed;
    }

    function syncMissionFinderIphoneCloseControlClearance(panel) {
        if (!panel) return;

        if (!isMissionFinderIphoneSafariWebsite()) {
            panel.style.removeProperty(
                '--mf-iphone-close-gutter'
            );
            return;
        }

        panel.style.setProperty(
            '--mf-iphone-close-gutter',
            `${Math.ceil(
                getMissionFinderIphoneCloseControlGutter()
            )}px`
        );
        syncMissionFinderIphoneLauncherPlacement(
            panel
        );
    }

    function resetMissionFinderIosPosition(panel, reason) {
        if (
            !panel
            || !isMissionFinderIosSafariWebsite()
        ) {
            return false;
        }

        panel.style.left = '';
        panel.style.top = '';
        panel.style.right = '';
        panel.style.bottom = '';
        panel.style.width = '';
        syncMissionFinderIphoneCloseControlClearance(panel);
        panel.style.visibility = 'visible';

        localStorage.removeItem(MF_PANEL_LEFT_KEY);
        localStorage.removeItem(MF_PANEL_TOP_KEY);

        requestAnimationFrame(() => {
            keepMissionFinderWindowOnScreen(panel);
        });

        if (mfDebugEnabled) {
            debugLog(
                'CONTROL WINDOW',
                `iOS Safari top placement restored | reason=${reason || 'unknown'}`
            );
        }

        return true;
    }

    function centreMissionFinderWindow(panel, reason) {
        if (!panel) return;

        if (
            resetMissionFinderIosPosition(
                panel,
                reason || 'centre requested'
            )
        ) {
            return;
        }

        const applyCentre = () => {
            const rect = panel.getBoundingClientRect();
            const margin = 8;

            const availableWidth = Math.max(
                0,
                window.innerWidth - rect.width
            );

            const availableHeight = Math.max(
                0,
                window.innerHeight - rect.height
            );

            const left = Math.max(
                margin,
                Math.round(availableWidth / 2)
            );

            const top = Math.max(
                margin,
                Math.round(availableHeight / 2)
            );

            panel.style.left = `${left}px`;
            panel.style.top = `${top}px`;
            panel.style.right = 'auto';
            panel.style.bottom = 'auto';
            panel.style.visibility = 'visible';

            localStorage.removeItem('panel-left');
            localStorage.removeItem('panel-top');

            if (mfKeepPanelPosition) {
                localStorage.setItem(
                    MF_PANEL_LEFT_KEY,
                    panel.style.left
                );
                localStorage.setItem(
                    MF_PANEL_TOP_KEY,
                    panel.style.top
                );
            } else {
                localStorage.removeItem(MF_PANEL_LEFT_KEY);
                localStorage.removeItem(MF_PANEL_TOP_KEY);
            }

            if (mfDebugEnabled) {
                debugLog(
                    'CONTROL WINDOW',
                    `Centred | reason=${reason || 'unknown'} | left=${left}px | top=${top}px`
                );
            }
        };

        requestAnimationFrame(() => {
            requestAnimationFrame(applyCentre);
        });
    }

    function keepMissionFinderWindowOnScreen(panel) {
        if (!panel) return;

        if (
            isMissionFinderIosSafariWebsite()
            && !panel.style.left
            && !panel.style.top
        ) {
            syncMissionFinderIphoneCloseControlClearance(panel);
            panel.style.visibility = 'visible';
            return;
        }

        const rect = panel.getBoundingClientRect();
        const margin = 8;
        const missionFinderIosSafari =
            isMissionFinderIosSafariWebsite();
        const bounds = missionFinderIosSafari
            ? getMissionFinderViewportBounds()
            : {
                left: 0,
                top: 0,
                right: window.innerWidth,
                bottom: window.innerHeight,
                width: window.innerWidth,
                height: window.innerHeight
            };

        const maxLeft = Math.max(
            bounds.left + margin,
            bounds.right - rect.width - margin
        );

        const maxTop = missionFinderIosSafari
            ? Math.max(
                bounds.top + margin,
                bounds.bottom - 48
            )
            : Math.max(
                margin,
                window.innerHeight - Math.min(
                    rect.height,
                    window.innerHeight - margin
                )
            );

        const currentLeft = parseFloat(panel.style.left);
        const currentTop = parseFloat(panel.style.top);

        const safeLeft = Math.min(
            maxLeft,
            Math.max(
                bounds.left + margin,
                Number.isFinite(currentLeft)
                    ? currentLeft
                    : rect.left
            )
        );

        const safeTop = Math.min(
            maxTop,
            Math.max(
                bounds.top + margin,
                Number.isFinite(currentTop)
                    ? currentTop
                    : rect.top
            )
        );

        panel.style.left = `${Math.round(safeLeft)}px`;
        panel.style.top = `${Math.round(safeTop)}px`;
        panel.style.right = 'auto';
        panel.style.visibility = 'visible';
    }

    function makePanelDraggable(panel, dragHandle) {
        if (
            isMissionFinderIosSafariWebsite()
            && window.PointerEvent
        ) {
            let activePointerId = null;
            let startX = 0;
            let startY = 0;
            let startLeft = 0;
            let startTop = 0;
            let moved = false;

            const finishPointerDrag = event => {
                if (
                    activePointerId == null
                    || (
                        event?.pointerId != null
                        && event.pointerId !== activePointerId
                    )
                ) {
                    return;
                }

                if (
                    dragHandle.hasPointerCapture?.(
                        activePointerId
                    )
                ) {
                    try {
                        dragHandle.releasePointerCapture(
                            activePointerId
                        );
                    } catch (_error) {}
                }

                activePointerId = null;
                keepMissionFinderWindowOnScreen(panel);

                localStorage.removeItem(MF_PANEL_LEFT_KEY);
                localStorage.removeItem(MF_PANEL_TOP_KEY);
                localStorage.removeItem('panel-left');
                localStorage.removeItem('panel-top');

                if (moved) {
                    const suppressClick = clickEvent => {
                        clickEvent.preventDefault();
                        clickEvent.stopPropagation();
                    };
                    dragHandle.addEventListener(
                        'click',
                        suppressClick,
                        {
                            once: true,
                            capture: true
                        }
                    );
                }
            };

            dragHandle.addEventListener(
                'pointerdown',
                event => {
                    if (
                        event.button != null
                        && event.button !== 0
                    ) {
                        return;
                    }

                    const rect =
                        panel.getBoundingClientRect();

                    activePointerId = event.pointerId;
                    startX = event.clientX;
                    startY = event.clientY;
                    startLeft = rect.left;
                    startTop = rect.top;
                    moved = false;

                    panel.style.width =
                        `${Math.round(rect.width)}px`;
                    panel.style.left =
                        `${Math.round(startLeft)}px`;
                    panel.style.top =
                        `${Math.round(startTop)}px`;
                    panel.style.right = 'auto';
                    panel.style.bottom = 'auto';

                    try {
                        dragHandle.setPointerCapture?.(
                            activePointerId
                        );
                    } catch (_error) {}

                    event.preventDefault();
                }
            );

            dragHandle.addEventListener(
                'pointermove',
                event => {
                    if (
                        activePointerId == null
                        || event.pointerId !== activePointerId
                    ) {
                        return;
                    }

                    const deltaX =
                        event.clientX - startX;
                    const deltaY =
                        event.clientY - startY;

                    if (
                        Math.abs(deltaX) > 4
                        || Math.abs(deltaY) > 4
                    ) {
                        moved = true;
                    }

                    const bounds =
                        getMissionFinderViewportBounds();
                    const rect =
                        panel.getBoundingClientRect();
                    const margin = 8;

                    const maxLeft = Math.max(
                        bounds.left + margin,
                        bounds.right - rect.width - margin
                    );
                    const maxTop = Math.max(
                        bounds.top + margin,
                        bounds.bottom - 48
                    );

                    const nextLeft = Math.min(
                        maxLeft,
                        Math.max(
                            bounds.left + margin,
                            startLeft + deltaX
                        )
                    );
                    const nextTop = Math.min(
                        maxTop,
                        Math.max(
                            bounds.top + margin,
                            startTop + deltaY
                        )
                    );

                    panel.style.left =
                        `${Math.round(nextLeft)}px`;
                    panel.style.top =
                        `${Math.round(nextTop)}px`;

                    event.preventDefault();
                }
            );

            dragHandle.addEventListener(
                'pointerup',
                finishPointerDrag
            );
            dragHandle.addEventListener(
                'pointercancel',
                finishPointerDrag
            );

            return;
        }

        let isDragging = false;
        let startX, startY, initialLeft, initialTop;

        dragHandle.addEventListener('mousedown', function(e) {
            if (e.button !== 0) return;

            isDragging = true;
            startX = e.clientX;
            startY = e.clientY;

            const computed = window.getComputedStyle(panel);

            initialLeft = parseInt(computed.left, 10);
            initialTop = parseInt(computed.top, 10);

            if (!Number.isFinite(initialLeft)) {
                initialLeft = panel.getBoundingClientRect().left;
            }

            if (!Number.isFinite(initialTop)) {
                initialTop = panel.getBoundingClientRect().top;
            }

            e.preventDefault();

            document.addEventListener('mousemove', onMouseMove);
            document.addEventListener('mouseup', onMouseUp);
        });

        function onMouseMove(e) {
            if (!isDragging) return;

            const rect = panel.getBoundingClientRect();
            const margin = 8;

            const requestedLeft =
                initialLeft + e.clientX - startX;

            const requestedTop =
                initialTop + e.clientY - startY;

            const maxLeft = Math.max(
                margin,
                window.innerWidth - rect.width - margin
            );

            const visibleHeaderHeight = 48;

            const maxTop = Math.max(
                margin,
                window.innerHeight - visibleHeaderHeight
            );

            panel.style.left = `${
                Math.round(
                    Math.min(
                        maxLeft,
                        Math.max(margin, requestedLeft)
                    )
                )
            }px`;

            panel.style.top = `${
                Math.round(
                    Math.min(
                        maxTop,
                        Math.max(margin, requestedTop)
                    )
                )
            }px`;
        }

        function onMouseUp() {
            if (!isDragging) return;

            isDragging = false;

            document.removeEventListener('mousemove', onMouseMove);
            document.removeEventListener('mouseup', onMouseUp);

            keepMissionFinderWindowOnScreen(panel);

            if (mfKeepPanelPosition) {
                saveMissionFinderWindowPosition(
                    panel,
                    'drag completed'
                );
            } else {
                localStorage.removeItem(MF_PANEL_LEFT_KEY);
                localStorage.removeItem(MF_PANEL_TOP_KEY);
            }

            localStorage.removeItem('panel-left');
            localStorage.removeItem('panel-top');
        }
    }

    function getMissionReadyDelay() {
        const value = parseInt(localStorage.getItem('mf_mission_ready_delay_ms') || String(missionReadyDelayMs), 10);
        return Number.isFinite(value) ? Math.max(500, Math.min(15000, value)) : DEFAULT_MISSION_READY_DELAY;
    }

    function getDispatchReadinessSignature() {
        const selectedCount = document.querySelectorAll(
            'input[type="checkbox"]:checked, input.vehicle_checkbox:checked'
        ).length;

        const now = Date.now();

        if (now >= mfDispatchReadinessExpensiveCache.expiresAt) {
            mfDispatchReadinessExpensiveCache = {
                expiresAt: now + 200,
                updateRowsSignature: getMissionUpdateRowsSignature(
                    readMissionUpdateRows({
                        silent: true
                    })
                ),
                staffingText: getVisibleStaffingShortageText()
            };
        }

        const rowState = vehicleLoadState.rows
            .map(row => [
                row.originalName,
                row.mappedName,
                row.required,
                row.found,
                row.status
            ].join(':'))
            .sort()
            .join('|');

        return [
            selectedCount,
            mfDispatchReadinessExpensiveCache.updateRowsSignature,
            rowState,
            vehicleLoadState.ready ? 'ready' : 'not-ready',
            isLoadingBarVisible() ? 'loading' : 'idle',
            mfDispatchReadinessExpensiveCache.staffingText
        ].join('||');
    }

    async function waitForFastDispatchReadiness(
        reason,
        options = {}
    ) {
        const minimumWait = Number.isFinite(options.minimumWait)
            ? options.minimumWait
            : 250;

        const stableFor = Number.isFinite(options.stableFor)
            ? options.stableFor
            : 450;

        const timeout = Number.isFinite(options.timeout)
            ? options.timeout
            : 2000;

        const startedAt = Date.now();
        let lastSignature = '';
        let stableSince = 0;

        while (Date.now() - startedAt < timeout) {
            if (
                isManualAutoStopActive() ||
                !autoModeRunning
            ) {
                return false;
            }

            if (
                detectAndLatchStaffingBlock(
                    `fast-ready-${reason}`
                )
            ) {
                return false;
            }

            const signature =
                getDispatchReadinessSignature();

            if (signature !== lastSignature) {
                lastSignature = signature;
                stableSince = Date.now();
            }

            const elapsed = Date.now() - startedAt;
            const stableElapsed = Date.now() - stableSince;

            if (
                elapsed >= minimumWait &&
                stableElapsed >= stableFor &&
                !isLoadingBarVisible()
            ) {
                if (mfDebugEnabled) {
                    debugLog(
                        'FAST DISPATCH',
                        `${reason || 'selection'} stable after ${elapsed}ms`
                    );
                }

                return true;
            }

            await wait(100);
        }

        if (mfDebugEnabled) {
            debugLog(
                'FAST DISPATCH',
                `${reason || 'selection'} reached ${timeout}ms safety limit`
            );
        }

        return true;
    }


    function createDefaultSessionStats() {
        return {
            startedAt: Date.now(),
            completed: 0,
            skipped: 0,
            updates: 0,
            credits: 0,
            entries: []
        };
    }

    function loadSessionStats() {
        try {
            const raw = sessionStorage.getItem(SESSION_STATS_KEY);
            if (!raw) return createDefaultSessionStats();

            const parsed = JSON.parse(raw);
            return Object.assign(createDefaultSessionStats(), parsed, {
                entries: Array.isArray(parsed.entries) ? parsed.entries : []
            });
        } catch (error) {
            console.warn('Mission Control session stats reset after parse error:', error);
            return createDefaultSessionStats();
        }
    }

    function saveSessionStats(stats) {
        sessionStorage.setItem(SESSION_STATS_KEY, JSON.stringify(stats));
    }

    function getCurrentMissionName() {
        const generalInfo = document.querySelector('#mission_general_info');

        if (generalInfo) {
            const dataTitle = generalInfo.getAttribute('data-mission-title');

            if (dataTitle && dataTitle.trim()) {
                return dataTitle.trim();
            }
        }

        const missionH1 = document.querySelector('#missionH1');

        if (missionH1) {
            const title = missionH1.innerText.replace(/\s+/g,' ').trim();
            if (title) return title;
        }

        const candidates=[
            '#mission_caption',
            '#mission_general_info h1',
            '.mission_title',
            '.mission-title',
            'h1',
            'h2'
        ];

        for(const selector of candidates){
            const element=document.querySelector(selector);
            const text=element&&element.innerText?element.innerText.replace(/\s+/g,' ').trim():'';
            if(text && !text.toLowerCase().includes('mission control')){
                return text;
            }
        }

        return 'Mission';
    }

    function isConfiguredHighRiskMissingPersonMission(
        missionName = getCurrentMissionName()
    ) {
        const normalisedTitle = String(
            missionName || ''
        )
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();

        return /\b(?:very\s+)?high\s+risk\s+missing\s+persons?\b/.test(
            normalisedTitle
        );
    }

        function normaliseConfiguredAmbulanceOfficerThreshold(
        value
    ) {
        const parsed = Number.parseInt(
            String(value == null ? '' : value),
            10
        );

        if (!Number.isFinite(parsed)) {
            return MF_AMBULANCE_OFFICER_THRESHOLD_DEFAULT;
        }

        return Math.min(
            MF_AMBULANCE_OFFICER_THRESHOLD_MAX,
            Math.max(
                MF_AMBULANCE_OFFICER_THRESHOLD_MIN,
                parsed
            )
        );
    }

    function isAmbulanceOfficerRequirement(
        originalName,
        mappedName
    ) {
        return [originalName, mappedName].some(value => {
            const cleaned = String(value || '')
                .replace(/\s+/g, ' ')
                .trim();

            return /^(?:Required\s+)?(?:\d+\s+)?Ambulance Officers?$/i.test(
                cleaned
            );
        });
    }

    function hasAmbulanceOfficerThresholdAlreadySatisfied() {
        const missionKey =
            getLocalMissionInstanceKey();

        const liveRequirementSatisfied =
            !!(
                missionKey &&
                mfMissionUpdateRowsCache
                    .missionKey === missionKey &&
                mfMissionUpdateRowsCache
                    .ambulanceOfficerSatisfied === true
            );

        const alreadySelected =
            countSelectedMatchingVehicles(
                'Ambulance Officer',
                'Ambulance Officer'
            ) > 0;

        return (
            alreadySelected ||
            liveRequirementSatisfied ||
            vehicleLoadState
                .ambulanceOfficer === true
        );
    }

        function addConfiguredAmbulanceOfficerThresholdRequirement(
        rows,
        additionalRows = []
    ) {
        const sourceRows =
            (Array.isArray(rows) ? rows : [])
                .filter(Boolean);
        const comparisonRows = [
            ...sourceRows,
            ...(Array.isArray(additionalRows)
                ? additionalRows.filter(Boolean)
                : [])
        ];

        if (!mfAmbulanceOfficerThresholdEnabled) {
            return sourceRows.slice();
        }

        const threshold =
            normaliseConfiguredAmbulanceOfficerThreshold(
                mfAmbulanceOfficerThreshold
            );
        const ambulanceCount = comparisonRows.reduce(
            (total, row) => {
                const originalName =
                    row.originalName ||
                    row.unitName ||
                    '';
                const mappedName =
                    row.unitName ||
                    resolveUnitName(originalName);

                if (
                    !isAmbulanceTransportRequest(
                        originalName,
                        mappedName
                    )
                ) {
                    return total;
                }

                return total + Math.max(
                    0,
                    Number(row.stillNeeded) || 0
                );
            },
            0
        );

        if (ambulanceCount <= threshold) {
            return sourceRows.slice();
        }

        const alreadyRequiresOfficer =
            comparisonRows.some(row => {
                const originalName =
                    row.originalName ||
                    row.unitName ||
                    '';
                const mappedName =
                    row.unitName ||
                    resolveUnitName(originalName);
                const quantity = Math.max(
                    0,
                    Number(row.stillNeeded) || 0
                );

                return (
                    quantity > 0 &&
                    isAmbulanceOfficerRequirement(
                        originalName,
                        mappedName
                    )
                );
            });

        if (alreadyRequiresOfficer) {
            return sourceRows.slice();
        }

        if (
            hasAmbulanceOfficerThresholdAlreadySatisfied()
        ) {
            return sourceRows.slice();
        }

        return [
            ...sourceRows,
            {
                unitName: 'Ambulance Officer',
                stillNeeded: 1,
                source:
                    'settings-ambulance-officer-threshold',
                configuredAmbulanceOfficerThreshold:
                    true,
                configuredAmbulanceCount:
                    ambulanceCount,
                configuredAmbulanceThreshold:
                    threshold
            }
        ];
    }

function addConfiguredHighRiskMissingPersonAmbulanceRequirement(
        rows
    ) {
        const sourceRows =
            (Array.isArray(rows) ? rows : [])
                .filter(Boolean);

        if (
            !mfAlwaysSendAmbulanceToHighRiskMissingPerson ||
            !isConfiguredHighRiskMissingPersonMission()
        ) {
            return sourceRows.slice();
        }

        const alreadyRequiresAmbulance =
            sourceRows.some(row => {
                if (
                    row?.isTrainedPersonnelRequirement === true ||
                    Math.max(
                        0,
                        parseInt(row?.stillNeeded, 10) || 0
                    ) <= 0
                ) {
                    return false;
                }

                const originalName =
                    String(row?.unitName || '')
                        .replace(/\s+/g, ' ')
                        .trim();

                return Boolean(
                    originalName &&
                    isAmbulanceTransportRequest(
                        originalName,
                        resolveUnitName(originalName)
                    )
                );
            });

        if (alreadyRequiresAmbulance) {
            return sourceRows.slice();
        }

        return [
            ...sourceRows,
            {
                unitName: 'Ambulance',
                stillNeeded: 1,
                source:
                    'settings-high-risk-missing-person-ambulance',
                configuredHighRiskMissingPersonAmbulance:
                    true
            }
        ];
    }

        function applyConfiguredFreshMissionVehicleRequirements(
        rows,
        additionalRows = []
    ) {
        return addConfiguredAmbulanceOfficerThresholdRequirement(
            addConfiguredHighRiskMissingPersonAmbulanceRequirement(
                rows
            ),
            additionalRows
        );
    }

    function buildFreshAmbulanceOfficerThresholdAdditionalRows(
        patientRequirementRows = [],
        patientCount = 0
    ) {
        const sourceRows =
            (Array.isArray(patientRequirementRows)
                ? patientRequirementRows
                : [])
                .filter(Boolean);

        const explicitPatientAmbulanceCount =
            sourceRows.reduce((total, row) => {
                const originalName =
                    row.originalName ||
                    row.unitName ||
                    '';
                const mappedName =
                    row.unitName ||
                    resolveUnitName(originalName);

                if (
                    !isAmbulanceTransportRequest(
                        originalName,
                        mappedName
                    )
                ) {
                    return total;
                }

                return total + Math.max(
                    0,
                    Number(row.stillNeeded) || 0
                );
            }, 0);

        // Fresh Unit Finder deliberately selects ordinary Ambulances from
        // the current patient badge count and suppresses the duplicate
        // Ambulance row in the mission-help table. Feed that already-owned
        // demand into the Officer threshold without adding it to any explicit
        // patient "We need: Ambulance" total a second time.
        const freshPatientAmbulanceCount =
            Math.max(
                explicitPatientAmbulanceCount,
                Math.max(
                    0,
                    parseInt(patientCount, 10) || 0
                )
            );

        const nonAmbulanceRows =
            sourceRows.filter(row => {
                const originalName =
                    row.originalName ||
                    row.unitName ||
                    '';
                const mappedName =
                    row.unitName ||
                    resolveUnitName(originalName);

                return !isAmbulanceTransportRequest(
                    originalName,
                    mappedName
                );
            });

        if (freshPatientAmbulanceCount <= 0) {
            return nonAmbulanceRows;
        }

        return [
            ...nonAmbulanceRows,
            {
                unitName: 'Ambulance x 01',
                stillNeeded:
                    freshPatientAmbulanceCount,
                source:
                    'fresh-patient-ambulance-total',
                patientRequirementType:
                    'ambulance',
                configuredFreshPatientAmbulanceTotal:
                    true
            }
        ];
    }


    function getCurrentMissionValueScope() {
        const missionInfo =
            document.querySelector('#mission_general_info');

        const missionModal =
            missionInfo &&
            missionInfo.closest &&
            missionInfo.closest('.vm--modal, .modal, .lightbox');

        return missionModal ||
            document.querySelector(
                '#mission_general_info, #mission_content, #iframe-inside-container'
            ) ||
            document;
    }

    function parseCreditValueFromText(text) {
        const value = String(text || '')
            .replace(/\u00a0/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();

        if (!value) return 0;

        const patterns = [
            /(?:average\s+credits?|mission\s+value|reward|credits?)\s*:?\s*~?\s*([\d,.]+)/i,
            /~?\s*([\d,.]+)\s*credits?/i
        ];

        for (const pattern of patterns) {
            const match = value.match(pattern);

            if (!match) continue;

            const parsed = parseInt(
                match[1].replace(/[^\d]/g, ''),
                10
            );

            if (
                Number.isFinite(parsed) &&
                parsed > 0 &&
                parsed < 100000000
            ) {
                return parsed;
            }
        }

        return 0;
    }

    function extractMissionAdvertisedCreditsFromDocument(doc) {
        if (!doc) return 0;

        const attributeCandidates = Array.from(
            doc.querySelectorAll?.(
                '[data-mission-credits], [data-credits], [data-reward]'
            ) || []
        );

        for (const element of attributeCandidates) {
            const raw =
                element.getAttribute?.('data-mission-credits') ||
                element.getAttribute?.('data-credits') ||
                element.getAttribute?.('data-reward') ||
                '';
            const parsed = parseInt(
                String(raw).replace(/[^\d]/g, ''),
                10
            );

            if (
                Number.isFinite(parsed) &&
                parsed > 0 &&
                parsed < 100000000
            ) {
                return parsed;
            }
        }

        const rows = Array.from(
            doc.querySelectorAll?.(
                'table tbody tr, table tr'
            ) || []
        );

        for (const row of rows) {
            const cells = Array.from(
                row.querySelectorAll?.('td, th') || []
            ).map(cell => {
                return String(cell.textContent || '')
                    .replace(/\u00a0/g, ' ')
                    .replace(/\s+/g, ' ')
                    .trim();
            });

            if (cells.length < 2) continue;

            const label = cells[0]
                .replace(/\s*:\s*$/, '')
                .trim();

            if (
                !/^(?:average\s+credits?|mission\s+value|reward)$/i
                    .test(label)
            ) {
                continue;
            }

            const parsed = parseCreditValueFromText(
                `${label}: ${cells.slice(1).join(' ')}`
            );

            if (parsed > 0) return parsed;
        }

        return parseCreditValueFromText(
            doc.body?.innerText ||
            doc.body?.textContent ||
            ''
        );
    }

    function extractMissionGeneratorFromDocument(doc) {
        const empty = {
            stationId: '',
            stationName: '',
            source: ''
        };
        if (!doc) return empty;

        const explicit = doc.querySelector?.(
            '[data-generator-building-id], [data-generator-building-name], ' +
            '[data-generated-by], #mission_generated_by, .mission-generated-by'
        );
        if (explicit) {
            const link = explicit.matches?.('a[href*="/buildings/"]')
                ? explicit
                : explicit.querySelector?.(
                    'a[href*="/buildings/"]'
                );
            const id = String(
                explicit.getAttribute?.(
                    'data-generator-building-id'
                ) ||
                link?.getAttribute?.('href')?.match(
                    /\/buildings\/(\d+)/i
                )?.[1] ||
                ''
            ).trim();
            const name = trimMissionLoggerText(
                explicit.getAttribute?.(
                    'data-generator-building-name'
                ) ||
                explicit.getAttribute?.('data-generated-by') ||
                link?.textContent ||
                explicit.textContent ||
                '',
                160
            );

            if (id || name) {
                return {
                    stationId: /^\d+$/.test(id) ? id : '',
                    stationName: name,
                    source: 'mission-definition'
                };
            }
        }

        const rows = Array.from(
            doc.querySelectorAll?.(
                'table tbody tr, table tr'
            ) || []
        );

        for (const row of rows) {
            const cells = Array.from(
                row.querySelectorAll?.('td, th') || []
            );
            if (cells.length < 2) continue;

            const label = trimMissionLoggerText(
                cells[0]?.textContent || '',
                120
            ).replace(/\s*:\s*$/, '');
            if (
                !/^(?:generated\s+by|generating\s+(?:station|building)|generator)$/i
                    .test(label)
            ) {
                continue;
            }

            const valueCell = cells.slice(1).find(cell => {
                return trimMissionLoggerText(
                    cell?.textContent || '',
                    160
                );
            });
            const link = valueCell?.querySelector?.(
                'a[href*="/buildings/"]'
            );
            const id = String(
                link?.getAttribute?.('href')?.match(
                    /\/buildings\/(\d+)/i
                )?.[1] ||
                valueCell?.getAttribute?.(
                    'data-generator-building-id'
                ) ||
                ''
            ).trim();
            const name = trimMissionLoggerText(
                link?.textContent ||
                valueCell?.textContent ||
                '',
                160
            );

            if (id || name) {
                return {
                    stationId: /^\d+$/.test(id) ? id : '',
                    stationName: name,
                    source: 'mission-definition'
                };
            }
        }

        return empty;
    }

    function getMissionCredits() {
        const scope = getCurrentMissionValueScope();

        const attributeCandidates = Array.from(
            scope.querySelectorAll(
                '[data-mission-credits], [data-credits], [data-reward]'
            )
        );

        for (const element of attributeCandidates) {
            const raw =
                element.getAttribute('data-mission-credits') ||
                element.getAttribute('data-credits') ||
                element.getAttribute('data-reward') ||
                '';

            const parsed = parseInt(
                String(raw).replace(/[^\d]/g, ''),
                10
            );

            if (Number.isFinite(parsed) && parsed > 0) {
                return parsed;
            }
        }

        const badgeCandidates = Array.from(
            scope.querySelectorAll(
                'span.badge, .badge, .label, #mission_help, #mission_general_info'
            )
        );

        for (const element of badgeCandidates) {
            const parsed = parseCreditValueFromText(
                element.innerText ||
                element.textContent ||
                ''
            );

            if (parsed > 0) return parsed;
        }

        const scopeText = (
            scope.innerText ||
            scope.textContent ||
            ''
        ).replace(/\s+/g, ' ').trim();

        const visibleCredits =
            parseCreditValueFromText(scopeText);

        if (visibleCredits > 0) {
            return visibleCredits;
        }

        const markerCredits = Math.max(
            0,
            parseInt(
                getMissionLoggerMissionSnapshot()
                    .advertisedCredits,
                10
            ) || 0
        );

        if (markerCredits > 0) {
            return markerCredits;
        }

        return getCachedMissionAdvertisedCredits();
    }

    function createMissionLoggerId(prefix = 'id') {
        let value = '';

        try {
            if (typeof crypto?.randomUUID === 'function') {
                value = crypto.randomUUID();
            } else if (typeof crypto?.getRandomValues === 'function') {
                const bytes = new Uint8Array(16);
                crypto.getRandomValues(bytes);
                value = Array.from(bytes)
                    .map(byte => byte.toString(16).padStart(2, '0'))
                    .join('');
            }
        } catch (_error) {}

        if (!value) {
            value = `${Date.now().toString(36)}-${Math.random()
                .toString(36)
                .slice(2)}-${Math.random().toString(36).slice(2)}`;
        }

        return `${String(prefix || 'id')}-${value}`;
    }

    function normaliseMissionLoggerEndpoint(value) {
        const raw = String(value || '').trim();
        if (!raw) return '';

        try {
            const url = new URL(raw);
            const validHost =
                url.protocol === 'https:' &&
                url.hostname === 'script.google.com';
            const validPath =
                /^\/macros\/s\/[A-Za-z0-9_-]+\/(?:exec|dev)\/?$/.test(
                    url.pathname
                );

            if (!validHost || !validPath) return '';
            url.search = '';
            url.hash = '';
            return url.href.replace(/\/$/, '');
        } catch (_error) {
            return '';
        }
    }

    mfMissionLoggerEndpoint = normaliseMissionLoggerEndpoint(
        MF_MISSION_LOGGER_FIXED_ENDPOINT
    );
    if (mfMissionLoggerEndpoint) {
        localStorage.setItem(
            MF_MISSION_LOGGER_ENDPOINT_KEY,
            mfMissionLoggerEndpoint
        );
    }

    function normaliseMissionLoggerProfileName(value) {
        return String(value || '')
            .replace(/\u00a0/g, ' ')
            .replace(/[\u0000-\u001f\u007f]/g, ' ')
            .replace(/\s+/g, ' ')
            .trim()
            .slice(0, 120);
    }

    function normaliseMissionLoggerProfileId(value) {
        const candidate = String(value || '').trim();
        return /^\d{1,20}$/.test(candidate) ? candidate : '';
    }

    function readLegacyMissionLoggerIdentity() {
        try {
            const parsed = JSON.parse(
                localStorage.getItem(
                    MF_MISSION_LOGGER_LEGACY_IDENTITY_KEY
                ) || 'null'
            );
            if (!parsed || typeof parsed !== 'object') {
                return null;
            }
            const deviceId = String(parsed.deviceId || '');
            return /^[A-Za-z0-9_-]{8,160}$/.test(deviceId)
                ? { deviceId }
                : null;
        } catch (_error) {
            return null;
        }
    }

    function readMissionLoggerIdentity() {
        let parsed = null;
        try {
            const candidate = JSON.parse(
                localStorage.getItem(
                    MF_MISSION_LOGGER_PROFILE_KEY
                ) || 'null'
            );
            if (candidate && typeof candidate === 'object') {
                parsed = candidate;
            }
        } catch (_error) {}

        const legacy = readLegacyMissionLoggerIdentity();
        const detected = resolveMissionChiefNavbarIdentity();
        const storedName = normaliseMissionLoggerProfileName(
            parsed?.playerName || parsed?.legacyPlayerName
        );
        const playerName = normaliseMissionLoggerProfileName(
            detected?.playerName || storedName
        );
        const playerId = normaliseMissionLoggerProfileId(
            detected?.playerId || parsed?.playerId || parsed?.profileId
        );
        if (!playerName || !playerId) return null;

        const storedDeviceId = String(parsed?.deviceId || '')
            .replace(/[^A-Za-z0-9_-]/g, '')
            .slice(0, 160);
        const deviceId =
            storedDeviceId ||
            legacy?.deviceId ||
            createMissionLoggerId('device');
        const profile = {
            playerId,
            profileId: playerId,
            playerName,
            legacyPlayerName:
                normaliseMissionLoggerProfileName(
                    parsed?.legacyPlayerName || storedName || playerName
                ) || playerName,
            deviceId,
            deviceLabel: String(
                parsed?.deviceLabel || getMissionLoggerDeviceLabel()
            ).slice(0, 120),
            configuredAt: String(
                parsed?.configuredAt || new Date().toISOString()
            )
        };

        const profileChanged =
            !parsed ||
            String(parsed.playerId || parsed.profileId || '') !==
                profile.playerId ||
            String(parsed.playerName || '') !== profile.playerName ||
            String(parsed.legacyPlayerName || '') !==
                profile.legacyPlayerName ||
            String(parsed.deviceId || '') !== profile.deviceId ||
            String(parsed.deviceLabel || '') !== profile.deviceLabel;

        if (profileChanged) {
            writeMissionLoggerIdentity(profile);
        }
        if (legacy) {
            localStorage.removeItem(
                MF_MISSION_LOGGER_LEGACY_IDENTITY_KEY
            );
        }

        return profile;
    }

    function writeMissionLoggerIdentity(identity) {
        localStorage.setItem(
            MF_MISSION_LOGGER_PROFILE_KEY,
            JSON.stringify(identity)
        );
    }

    function clearMissionLoggerProfileScopedData() {
        [
            MF_MISSION_LOGGER_PENDING_BATCH_KEY,
            MF_MISSION_LOGGER_QUEUE_KEY,
            MF_MISSION_ACTIVITY_BACKEND_V2_KEY,
            MF_MISSION_LOGGER_OBSERVED_KEY,
            MF_MISSION_LOGGER_LAST_DISPATCH_KEY,
            MF_MISSION_LOGGER_MISSION_REGISTRY_KEY,
            MF_MISSION_LOGGER_SYNC_LOCK_KEY,
            MF_MISSION_LOGGER_DRAIN_REQUEST_KEY
        ].forEach(key => localStorage.removeItem(key));

        writeMissionLoggerState({
            lastAttemptAt: 0,
            lastSuccessAt: 0,
            lastError: '',
            lastCreditCheckAt: 0,
            lastCreditSuccessAt: 0,
            lastCreditMatchAt: 0,
            lastCreditError: '',
            totalMatchedCreditEvents: 0,
            totalOfflineRecoveredCreditEvents: 0,
            totalUploadedEvents: 0,
            droppedEvents: 0,
            droppedObservationEvents: 0,
            droppedPriorityEvents: 0,
            offlineCreditRecoveryVersion: 0,
            offlineCreditCatchupNextPage: 1,
            offlineCreditCatchupFloorAt: 0,
            offlineCreditCatchupDeferred: false,
            drainRequestedAt: 0,
            drainMessage: ''
        });
    }

    function saveMissionLoggerSetup() {
        const endpoint = normaliseMissionLoggerEndpoint(
            MF_MISSION_LOGGER_FIXED_ENDPOINT
        );
        const profile = readMissionLoggerIdentity();
        if (!endpoint || !profile) {
            throw new Error(
                'The fixed Google logger URL and detected MissionChief profile are required.'
            );
        }

        mfMissionLoggerEndpoint = endpoint;
        localStorage.setItem(
            MF_MISSION_LOGGER_ENDPOINT_KEY,
            endpoint
        );
        mfMissionLoggerEnabled = true;
        localStorage.setItem(
            MF_MISSION_LOGGER_ENABLED_KEY,
            'true'
        );
        writeMissionLoggerState({
            lastError: ''
        });
        startMissionLoggerSyncTimer();
        recordMissionLoggerObservedEvent();
        scheduleMissionLoggerDeferredDrain(
            'fixed sharing and sync setup',
            {
                manual: true,
                delayMs: 100
            }
        );
        return profile;
    }

    function createDefaultMissionLoggerState() {
        return {
            lastAttemptAt: 0,
            lastSuccessAt: 0,
            lastError: '',
            lastCreditCheckAt: 0,
            lastCreditMatchAt: 0,
            lastCreditError: '',
            totalMatchedCreditEvents: 0,
            totalUploadedEvents: 0,
            droppedEvents: 0,
            droppedObservationEvents: 0,
            droppedPriorityEvents: 0,
            drainRequestedAt: 0,
            drainMessage: ''
        };
    }

    function readMissionLoggerState() {
        try {
            const parsed = JSON.parse(
                localStorage.getItem(
                    MF_MISSION_LOGGER_STATE_KEY
                ) || 'null'
            );

            return Object.assign(
                createDefaultMissionLoggerState(),
                parsed && typeof parsed === 'object'
                    ? parsed
                    : {}
            );
        } catch (_error) {
            return createDefaultMissionLoggerState();
        }
    }

    function writeMissionLoggerState(update) {
        const state = Object.assign(
            readMissionLoggerState(),
            update && typeof update === 'object'
                ? update
                : {}
        );

        localStorage.setItem(
            MF_MISSION_LOGGER_STATE_KEY,
            JSON.stringify(state)
        );
        renderMissionLoggerStatus();
        return state;
    }

    function readMissionLoggerQueue() {
        try {
            const parsed = JSON.parse(
                localStorage.getItem(
                    MF_MISSION_LOGGER_QUEUE_KEY
                ) || '[]'
            );

            return Array.isArray(parsed)
                ? parsed.filter(event => {
                    return !!(
                        event &&
                        typeof event === 'object' &&
                        event.eventId
                    );
                })
                : [];
        } catch (_error) {
            return [];
        }
    }

    function getMissionLoggerQueueEventPriority(event) {
        switch (String(event?.eventType || '')) {
            case 'dispatch':
                return 4;
            case 'mission-credit':
                return 3;
            case 'mission-completed':
                return 2;
            case 'mission-observed':
                return 0;
            default:
                return 1;
        }
    }

    function findMissionLoggerQueueDropIndex(queue) {
        if (!Array.isArray(queue) || queue.length === 0) {
            return -1;
        }

        let selectedIndex = 0;
        let selectedPriority =
            getMissionLoggerQueueEventPriority(queue[0]);

        for (let index = 1; index < queue.length; index += 1) {
            const priority =
                getMissionLoggerQueueEventPriority(queue[index]);
            if (priority < selectedPriority) {
                selectedIndex = index;
                selectedPriority = priority;
            }
        }

        return selectedIndex;
    }

    function boundMissionLoggerQueue(
        events,
        limits = {}
    ) {
        const maxEvents = Math.max(
            1,
            Math.trunc(
                Number(limits.maxEvents) ||
                MF_MISSION_LOGGER_MAX_QUEUE_EVENTS
            )
        );
        const maxChars = Math.max(
            1000,
            Math.trunc(
                Number(limits.maxChars) ||
                MF_MISSION_LOGGER_MAX_QUEUE_CHARS
            )
        );
        const queue = Array.isArray(events)
            ? events.slice()
            : [];
        const droppedTypes = {};
        let dropped = 0;

        const dropOne = () => {
            const index =
                findMissionLoggerQueueDropIndex(queue);
            if (index < 0) return false;
            const [removed] = queue.splice(index, 1);
            const eventType = String(
                removed?.eventType || 'unknown'
            );
            droppedTypes[eventType] =
                Math.max(
                    0,
                    Number(droppedTypes[eventType] || 0)
                ) + 1;
            dropped += 1;
            return true;
        };

        while (queue.length > maxEvents) {
            if (!dropOne()) break;
        }

        let encoded = JSON.stringify(queue);
        while (
            encoded.length > maxChars &&
            queue.length > 1
        ) {
            if (!dropOne()) break;
            encoded = JSON.stringify(queue);
        }

        return {
            queue,
            encoded,
            dropped,
            droppedTypes
        };
    }

    function writeMissionLoggerQueue(events) {
        const bounded = boundMissionLoggerQueue(events);

        try {
            localStorage.setItem(
                MF_MISSION_LOGGER_QUEUE_KEY,
                bounded.encoded
            );
        } catch (_error) {
            const fallback = boundMissionLoggerQueue(
                bounded.queue,
                {
                    maxEvents: 80,
                    maxChars: 750000
                }
            );
            localStorage.setItem(
                MF_MISSION_LOGGER_QUEUE_KEY,
                fallback.encoded
            );
            bounded.dropped += Math.max(
                0,
                bounded.queue.length - fallback.queue.length
            );
            bounded.queue = fallback.queue;
        }

        if (bounded.dropped > 0) {
            const state = readMissionLoggerState();
            writeMissionLoggerState({
                droppedEvents:
                    Math.max(
                        0,
                        Number(state.droppedEvents || 0)
                    ) + bounded.dropped,
                droppedObservationEvents:
                    Math.max(
                        0,
                        Number(
                            state.droppedObservationEvents || 0
                        )
                    ) + Math.max(
                        0,
                        Number(
                            bounded.droppedTypes?.[
                                'mission-observed'
                            ] || 0
                        )
                    ),
                droppedPriorityEvents:
                    Math.max(
                        0,
                        Number(
                            state.droppedPriorityEvents || 0
                        )
                    ) + Math.max(
                        0,
                        bounded.dropped -
                            Number(
                                bounded.droppedTypes?.[
                                    'mission-observed'
                                ] || 0
                            )
                    ),
                lastError:
                    `${bounded.dropped} logger event${bounded.dropped === 1 ? '' : 's'} dropped after the local outbox reached its storage safety limit. Mission observations are discarded before dispatch, completion or credit evidence.`
            });
        } else {
            renderMissionLoggerStatus();
        }

        return bounded.queue;
    }

    function scheduleMissionLoggerEagerSync(
        reason = 'queue threshold',
        force = false
    ) {
        if (!MF_IS_TOP_WINDOW) return false;
        if (
            mfMissionLoggerEagerSyncTimer ||
            mfMissionLoggerSyncActive ||
            !mfMissionLoggerEnabled ||
            !mfMissionLoggerEndpoint ||
            !readMissionLoggerIdentity() ||
            navigator.onLine === false
        ) {
            return false;
        }

        const queueCount =
            readMissionLoggerQueue().length;
        if (
            queueCount === 0 ||
            (
                !force &&
                queueCount <
                    MF_MISSION_LOGGER_EAGER_SYNC_THRESHOLD
            )
        ) {
            return false;
        }

        mfMissionLoggerEagerSyncTimer = setTimeout(
            () => {
                mfMissionLoggerEagerSyncTimer = null;
                void syncMissionLoggerNow({
                    backlog: true,
                    skipCreditReconcile: true,
                    reason
                });
            },
            (
                force
                    ? 500
                    : MF_MISSION_LOGGER_EAGER_SYNC_DELAY_MS
            ) + getMissionLoggerDeviceStagger(
                force ? 1000 : 2500
            )
        );
        return true;
    }

    function scheduleMissionLoggerDeferredDrain(
        reason = 'logger backlog',
        options = {}
    ) {
        const manual = options.manual === true;
        const queueCount = readMissionLoggerQueue().length;
        if (
            queueCount === 0 ||
            !mfMissionLoggerEnabled ||
            !mfMissionLoggerEndpoint ||
            !readMissionLoggerIdentity()
        ) {
            return false;
        }

        const requestedAt = Date.now();
        const drainMessage = manual
            ? 'Manual full drain queued; waiting for the active upload or another MissionChief tab to release the logger lock.'
            : 'Logger backlog drain queued.';
        writeMissionLoggerState({
            drainRequestedAt: requestedAt,
            drainMessage
        });

        if (!MF_IS_TOP_WINDOW) {
            try {
                localStorage.setItem(
                    MF_MISSION_LOGGER_DRAIN_REQUEST_KEY,
                    JSON.stringify({
                        requestId:
                            `${requestedAt}-${Math.random()
                                .toString(36)
                                .slice(2, 10)}`,
                        requestedAt,
                        manual,
                        reason: String(reason || '').slice(0, 180)
                    })
                );
            } catch (_error) {}
            return true;
        }

        if (manual) {
            mfMissionLoggerManualDrainRequested = true;
        }

        if (mfMissionLoggerDeferredDrainTimer) {
            return true;
        }

        const delay = Math.max(
            100,
            Math.trunc(
                Number(options.delayMs) ||
                MF_MISSION_LOGGER_DEFERRED_DRAIN_DELAY_MS
            )
        );

        mfMissionLoggerDeferredDrainTimer = setTimeout(
            () => {
                mfMissionLoggerDeferredDrainTimer = null;
                const runManual =
                    mfMissionLoggerManualDrainRequested;
                mfMissionLoggerManualDrainRequested = false;
                void syncMissionLoggerNow({
                    manual: runManual,
                    backlog: true,
                    skipCreditReconcile: true,
                    reason
                });
            },
            delay
        );
        return true;
    }


    let mfMissionActivityRecorderInstalled = false;
    let mfMissionActivityHeartbeatTimer = null;
    const mfMissionActivityDocuments = new WeakSet();
    const mfMissionActivityWindows = new WeakSet();
    const mfMissionActivityFrames = new WeakSet();

    function resolveMissionChiefNavbarIdentity() {
        try {
            const rootDocument = window.top?.document || document;
            const link = rootDocument.querySelector('#navbar_profile_link');
            if (!link) return null;
            const url = new URL(
                link.getAttribute('href') || link.href || '',
                window.location.origin
            );
            if (url.origin !== window.location.origin) return null;
            const match = url.pathname.match(/^\/profile\/(\d+)\/?$/);
            const playerId = normaliseMissionLoggerProfileId(match?.[1]);
            const playerName = normaliseMissionLoggerProfileName(
                link.textContent || ''
            );
            return playerId && playerName
                ? { playerId, playerName }
                : null;
        } catch (_error) {
            return null;
        }
    }

    function isMissionActivityBackendReady() {
        return localStorage.getItem(
            MF_MISSION_ACTIVITY_BACKEND_V2_KEY
        ) === 'true';
    }

    function updateMissionActivityBackendCapability(response) {
        if (!response || typeof response !== 'object') return false;
        const supported =
            Number(response.activitySchemaVersion || 0) >=
                MF_MISSION_ACTIVITY_SCHEMA_VERSION ||
            /activity-recorder/i.test(String(response.backendBuild || ''));
        if (!supported) return false;
        const wasReady = isMissionActivityBackendReady();
        localStorage.setItem(MF_MISSION_ACTIVITY_BACKEND_V2_KEY, 'true');
        if (!wasReady) {
            recordMissionActivity('SYSTEM', 'LIFECYCLE', 'BACKEND_READY', {
                outcome: 'OK',
                payload: {
                    activitySchemaVersion:
                        MF_MISSION_ACTIVITY_SCHEMA_VERSION
                }
            });
            recordMissionActivity('SYSTEM', 'LIFECYCLE', 'SESSION_START', {
                outcome: 'OK',
                payload: getMissionActivitySessionTelemetry()
            });
        }
        return true;
    }

    function getMissionActivitySession() {
        let session = null;
        try {
            session = JSON.parse(
                sessionStorage.getItem(MF_MISSION_ACTIVITY_SESSION_KEY) ||
                    'null'
            );
        } catch (_error) {}
        if (
            session &&
            typeof session === 'object' &&
            /^[A-Za-z0-9_-]{8,180}$/.test(String(session.sessionId || ''))
        ) {
            return session;
        }
        session = {
            sessionId: createMissionLoggerId('session'),
            startedAt: new Date().toISOString()
        };
        try {
            sessionStorage.setItem(
                MF_MISSION_ACTIVITY_SESSION_KEY,
                JSON.stringify(session)
            );
        } catch (_error) {}
        return session;
    }

    function getMissionActivitySessionTelemetry(frameWindow = window) {
        const session = getMissionActivitySession();
        let viewport = '';
        let timezone = '';
        try {
            viewport =
                String(frameWindow.innerWidth || 0) + 'x' +
                String(frameWindow.innerHeight || 0);
            timezone = Intl.DateTimeFormat().resolvedOptions().timeZone || '';
        } catch (_error) {}
        return {
            startedAt: session.startedAt,
            userAgent: String(navigator.userAgent || '').slice(0, 300),
            viewport: viewport.slice(0, 40),
            timezone: String(timezone).slice(0, 80)
        };
    }

    function sanitiseMissionActivityPath(value, frameWindow = window) {
        try {
            const url = new URL(String(value || ''), frameWindow.location.href);
            if (url.origin !== frameWindow.location.origin) return '';
            return String(url.pathname || '/').slice(0, 500);
        } catch (_error) {
            return '';
        }
    }

    function sanitiseMissionActivityPayload(payload) {
        if (!payload || typeof payload !== 'object') return {};
        const result = {};
        const forbidden = /password|passwd|token|cookie|authorization|secret|clipboard|requestbody|body|value|enteredtext/i;
        Object.entries(payload).slice(0, 16).forEach(([key, value]) => {
            const safeKey = String(key || '').replace(/[^A-Za-z0-9_-]/g, '').slice(0, 60);
            if (!safeKey || forbidden.test(safeKey)) return;
            if (typeof value === 'number' && Number.isFinite(value)) {
                result[safeKey] = value;
            } else if (typeof value === 'boolean') {
                result[safeKey] = value;
            } else if (value !== null && value !== undefined) {
                result[safeKey] = String(value).replace(/[\u0000-\u001f\u007f]/g, ' ').slice(0, 300);
            }
        });
        return result;
    }

    function getMissionActivityTarget(target, frameWindow = window) {
        const element = target?.nodeType === 1
            ? target
            : target?.parentElement || null;
        if (!element) return {};
        const tag = String(element.tagName || '').toLowerCase().slice(0, 30);
        const inputType = String(element.type || '').toLowerCase().slice(0, 40);
        const sensitive =
            tag === 'textarea' ||
            tag === 'select' ||
            element.isContentEditable ||
            tag === 'input';
        let label = '';
        if (!sensitive) {
            label = cleanText(
                element.getAttribute?.('aria-label') ||
                element.textContent ||
                element.getAttribute?.('title') ||
                ''
            ).slice(0, 160);
        }
        const href = sanitiseMissionActivityPath(
            element.closest?.('a[href]')?.getAttribute('href') || '',
            frameWindow
        );
        return {
            tag,
            id: String(element.id || '').slice(0, 120),
            label,
            href,
            inputType,
            inputName: sensitive
                ? String(element.getAttribute?.('name') || '').slice(0, 120)
                : '',
            surface:
                element.closest?.(
                    '#mission-finder-wrapper,#vehicle-load-list-box,#patient-transfer-list-box,[id^="mc-namer-"]'
                )
                    ? 'NEXUS'
                    : 'MISSIONCHIEF'
        };
    }

    function getMissionActivityRouteContext(frameWindow, target) {
        const route = sanitiseMissionActivityPath(
            frameWindow?.location?.href || window.location.href,
            frameWindow || window
        );
        const href = String(target?.href || '');
        const source = href || route;
        const idFor = pattern => String(source.match(pattern)?.[1] || '').slice(0, 80);
        return {
            route,
            missionId: idFor(/\/missions\/(\d+)/),
            vehicleId: idFor(/\/vehicles\/(\d+)/),
            patientId: idFor(/\/patient\/(\d+)/),
            stationId: idFor(/\/buildings\/(\d+)/)
        };
    }

    function recordMissionActivity(source, category, action, details = {}) {
        if (
            !MF_IS_TOP_WINDOW ||
            !mfMissionLoggerEnabled ||
            !mfMissionLoggerEndpoint ||
            !isMissionActivityBackendReady()
        ) return false;
        const activityCategory = String(
            category || ''
        ).toUpperCase();
        const activityOutcome = String(
            details.outcome || ''
        ).toUpperCase();
        if (
            activityCategory === 'NETWORK' &&
            !isMissionLoggerPassiveObserverOwner() &&
            !/FAILED|ERROR/.test(activityOutcome)
        ) {
            return false;
        }
        const identity = readMissionLoggerIdentity();
        if (!identity?.playerName || !identity?.deviceId) return false;
        const frameWindow = details.frameWindow || window;
        const target = details.target || {};
        const context = getMissionActivityRouteContext(frameWindow, target);
        const session = getMissionActivitySession();
        return queueMissionLoggerEvent({
            eventId: createMissionLoggerId('activity'),
            eventType: 'activity',
            capturedAt: new Date().toISOString(),
            missionId: details.missionId || context.missionId || '',
            metadata: {
                activity: {
                    sessionId: session.sessionId,
                    source: String(source || 'SYSTEM').slice(0, 40),
                    category: String(category || 'GENERAL').slice(0, 60),
                    action: String(action || 'UNKNOWN').slice(0, 100),
                    phase: String(details.phase || '').slice(0, 40),
                    outcome: String(details.outcome || 'OBSERVED').slice(0, 40),
                    route: details.route || context.route,
                    missionId: details.missionId || context.missionId || '',
                    vehicleId: details.vehicleId || context.vehicleId || '',
                    patientId: details.patientId || context.patientId || '',
                    stationId: details.stationId || context.stationId || '',
                    dispatchCentreId: String(details.dispatchCentreId || '').slice(0, 80),
                    targetTag: target.tag || '',
                    targetId: target.id || '',
                    targetLabel: target.label || '',
                    targetHref: target.href || '',
                    inputType: target.inputType || '',
                    correlationId: String(details.correlationId || '').slice(0, 180),
                    durationMs:
                        Number.isFinite(Number(details.durationMs))
                            ? Math.max(0, Math.round(Number(details.durationMs)))
                            : '',
                    attempt:
                        Number.isFinite(Number(details.attempt))
                            ? Math.max(0, Math.round(Number(details.attempt)))
                            : '',
                    message: String(details.message || '').replace(/[\u0000-\u001f\u007f]/g, ' ').slice(0, 300),
                    payload: sanitiseMissionActivityPayload(details.payload),
                    schemaVersion: MF_MISSION_ACTIVITY_SCHEMA_VERSION,
                    privacyClass: details.privacyClass || 'SAFE_METADATA'
                }
            }
        });
    }

    function missionActivitySourceForEvent(event, target) {
        if (event?.isTrusted) return 'USER';
        return target?.surface === 'NEXUS' ? 'NEXUS' : 'MISSIONCHIEF';
    }

    function recordMissionActivityDomEvent(event, frameWindow) {
        const target = getMissionActivityTarget(event?.target, frameWindow);
        const type = String(event?.type || '').toUpperCase();
        if (!type) return;
        if (type === 'KEYDOWN') {
            const key = String(event.key || '');
            const safeKeys = new Set([
                'Enter','Escape','Tab','Backspace','Delete','ArrowUp','ArrowDown',
                'ArrowLeft','ArrowRight','PageUp','PageDown','Home','End',' '
            ]);
            if (!safeKeys.has(key) && !event.ctrlKey && !event.metaKey && !event.altKey) {
                return;
            }
            recordMissionActivity('USER', 'INTERACTION', 'KEYDOWN', {
                frameWindow,
                target,
                payload: {
                    key: safeKeys.has(key) ? key : 'MODIFIER_SHORTCUT',
                    ctrl: !!event.ctrlKey,
                    meta: !!event.metaKey,
                    alt: !!event.altKey,
                    shift: !!event.shiftKey
                }
            });
            return;
        }
        recordMissionActivity(
            missionActivitySourceForEvent(event, target),
            'INTERACTION',
            type,
            { frameWindow, target }
        );
    }

    function patchMissionActivityWindow(frameWindow) {
        if (!frameWindow || mfMissionActivityWindows.has(frameWindow)) return;
        let sameOrigin = false;
        try {
            sameOrigin = frameWindow.location.origin === window.location.origin;
        } catch (_error) {}
        if (!sameOrigin) return;
        mfMissionActivityWindows.add(frameWindow);

        try {
            const originalFetch = frameWindow.fetch;
            if (typeof originalFetch === 'function') {
                frameWindow.fetch = function(input, init) {
                    const rawUrl = input?.url || input;
                    const route = sanitiseMissionActivityPath(rawUrl, frameWindow);
                    if (!route) return originalFetch.apply(this, arguments);
                    const method = String(
                        init?.method || input?.method || 'GET'
                    ).toUpperCase().slice(0, 12);
                    const correlationId = createMissionLoggerId('net');
                    const started = Date.now();
                    return originalFetch.apply(this, arguments).then(response => {
                        recordMissionActivity('MISSIONCHIEF', 'NETWORK', 'FETCH', {
                            frameWindow, route, phase: 'END',
                            outcome: response.ok ? 'OK' : 'FAILED',
                            correlationId, durationMs: Date.now() - started,
                            payload: { method, status: Number(response.status || 0) }
                        });
                        return response;
                    }).catch(error => {
                        recordMissionActivity('MISSIONCHIEF', 'NETWORK', 'FETCH', {
                            frameWindow, route, phase: 'END', outcome: 'ERROR',
                            correlationId, durationMs: Date.now() - started,
                            message: error?.message || 'Fetch failed', payload: { method }
                        });
                        throw error;
                    });
                };
            }
        } catch (_error) {}

        try {
            const XHR = frameWindow.XMLHttpRequest;
            if (XHR?.prototype) {
                const originalOpen = XHR.prototype.open;
                const originalSend = XHR.prototype.send;
                XHR.prototype.open = function(method, url) {
                    this.__mfActivityRequest = {
                        method: String(method || 'GET').toUpperCase().slice(0, 12),
                        route: sanitiseMissionActivityPath(url, frameWindow)
                    };
                    return originalOpen.apply(this, arguments);
                };
                XHR.prototype.send = function() {
                    const request = this.__mfActivityRequest;
                    if (!request?.route) return originalSend.apply(this, arguments);
                    const correlationId = createMissionLoggerId('xhr');
                    const started = Date.now();
                    this.addEventListener('loadend', () => {
                        const status = Number(this.status || 0);
                        recordMissionActivity('MISSIONCHIEF', 'NETWORK', 'XHR', {
                            frameWindow, route: request.route, phase: 'END',
                            outcome: status >= 200 && status < 400 ? 'OK' : 'FAILED',
                            correlationId, durationMs: Date.now() - started,
                            payload: { method: request.method, status }
                        });
                    }, { once: true });
                    return originalSend.apply(this, arguments);
                };
            }
        } catch (_error) {}

        try {
            ['pushState', 'replaceState'].forEach(method => {
                const original = frameWindow.history?.[method];
                if (typeof original !== 'function') return;
                frameWindow.history[method] = function() {
                    const result = original.apply(this, arguments);
                    recordMissionActivity('MISSIONCHIEF', 'NAVIGATION', method.toUpperCase(), {
                        frameWindow,
                        route: sanitiseMissionActivityPath(frameWindow.location.href, frameWindow)
                    });
                    return result;
                };
            });
        } catch (_error) {}

        frameWindow.addEventListener?.('popstate', () => {
            recordMissionActivity('USER', 'NAVIGATION', 'POPSTATE', { frameWindow });
        });
        frameWindow.addEventListener?.('hashchange', () => {
            recordMissionActivity('USER', 'NAVIGATION', 'HASHCHANGE', { frameWindow });
        });
        frameWindow.addEventListener?.('error', event => {
            recordMissionActivity('SYSTEM', 'ERROR', 'WINDOW_ERROR', {
                frameWindow,
                outcome: 'ERROR',
                message: event?.message || 'Window error'
            });
        });
        frameWindow.addEventListener?.('unhandledrejection', event => {
            recordMissionActivity('SYSTEM', 'ERROR', 'UNHANDLED_REJECTION', {
                frameWindow,
                outcome: 'ERROR',
                message: event?.reason?.message || String(event?.reason || 'Unhandled rejection')
            });
        });
    }

    function attachMissionActivityDocument(frameDocument, frameWindow) {
        if (!frameDocument || mfMissionActivityDocuments.has(frameDocument)) return;
        mfMissionActivityDocuments.add(frameDocument);
        patchMissionActivityWindow(frameWindow);
        ['click','dblclick','contextmenu','change','submit','focusin','focusout','dragstart','drop','keydown']
            .forEach(type => {
                frameDocument.addEventListener(
                    type,
                    event => recordMissionActivityDomEvent(event, frameWindow),
                    true
                );
            });
        frameDocument.addEventListener('visibilitychange', () => {
            recordMissionActivity('SYSTEM', 'LIFECYCLE', 'VISIBILITY_' +
                String(frameDocument.visibilityState || 'unknown').toUpperCase(), {
                frameWindow,
                payload: { state: frameDocument.visibilityState || 'unknown' }
            });
            if (frameDocument.visibilityState === 'hidden') {
                flushMissionActivityBuffer('visibility hidden');
            }
        });
    }

    function installMissionActivityFrame(frame) {
        if (!frame || mfMissionActivityFrames.has(frame)) return;
        mfMissionActivityFrames.add(frame);
        const attach = () => {
            try {
                if (frame.contentWindow?.location?.origin !== window.location.origin) return;
                attachMissionActivityDocument(
                    frame.contentDocument,
                    frame.contentWindow
                );
            } catch (_error) {}
        };
        frame.addEventListener('load', attach, true);
        attach();
    }

    function installMissionActivityRecorder() {
        if (!MF_IS_TOP_WINDOW || mfMissionActivityRecorderInstalled) return;
        mfMissionActivityRecorderInstalled = true;
        attachMissionActivityDocument(document, window);
        document.querySelectorAll('iframe').forEach(installMissionActivityFrame);
        new MutationObserver(records => {
            records.forEach(record => {
                Array.from(record.addedNodes || []).forEach(node => {
                    if (node?.nodeType !== 1) return;
                    if (node.tagName === 'IFRAME') installMissionActivityFrame(node);
                    node.querySelectorAll?.('iframe').forEach(installMissionActivityFrame);
                });
            });
        }).observe(document.documentElement, { childList: true, subtree: true });
        if (isMissionActivityBackendReady()) {
            recordMissionActivity('SYSTEM', 'LIFECYCLE', 'PAGE_LOAD', {
                outcome: 'OK',
                payload: getMissionActivitySessionTelemetry()
            });
        }
        window.addEventListener('pagehide', () => {
            recordMissionActivity('SYSTEM', 'LIFECYCLE', 'PAGEHIDE', {
                outcome: 'OK'
            });
            flushMissionActivityBuffer('pagehide');
        });
        mfMissionActivityHeartbeatTimer = setInterval(() => {
            recordMissionActivity('SYSTEM', 'LIFECYCLE', 'HEARTBEAT', {
                outcome: 'OK'
            });
        }, 60 * 1000);
    }

    function appendMissionActivityBufferToQueue(queue) {
        if (
            !Array.isArray(queue) ||
            mfMissionLoggerActivityBuffer.length === 0
        ) {
            return 0;
        }
        const existingIds = new Set(
            queue.map(event => String(event?.eventId || ''))
        );
        const buffered = mfMissionLoggerActivityBuffer.splice(
            0,
            mfMissionLoggerActivityBuffer.length
        );
        let accepted = 0;
        buffered.forEach(event => {
            const eventId = String(event?.eventId || '');
            if (!eventId || existingIds.has(eventId)) return;
            existingIds.add(eventId);
            queue.push(event);
            accepted += 1;
        });
        return accepted;
    }

    function scheduleMissionActivityBufferFlush(
        delayMs = MF_MISSION_LOGGER_ACTIVITY_FLUSH_MS
    ) {
        if (mfMissionLoggerActivityFlushTimer) return true;
        mfMissionLoggerActivityFlushTimer = setTimeout(
            () => {
                mfMissionLoggerActivityFlushTimer = null;
                const flush = () => {
                    flushMissionActivityBuffer(
                        'scheduled activity flush'
                    );
                };
                if (
                    typeof window.requestIdleCallback ===
                    'function'
                ) {
                    window.requestIdleCallback(flush, {
                        timeout: 750
                    });
                } else {
                    flush();
                }
            },
            Math.max(100, Math.trunc(Number(delayMs) || 0))
        );
        return true;
    }

    function flushMissionActivityBuffer(
        reason = 'activity buffer flush'
    ) {
        if (mfMissionLoggerActivityFlushTimer) {
            clearTimeout(mfMissionLoggerActivityFlushTimer);
            mfMissionLoggerActivityFlushTimer = null;
        }
        if (mfMissionLoggerActivityBuffer.length === 0) {
            return false;
        }

        const queue = readMissionLoggerQueue();
        const accepted = appendMissionActivityBufferToQueue(queue);
        if (accepted === 0) return false;
        writeMissionLoggerQueue(queue);
        scheduleMissionLoggerEagerSync(
            `${reason}: ${accepted} activity events`
        );
        return true;
    }

    function queueMissionLoggerEvent(event) {
        if (
            !mfMissionLoggerEnabled ||
            !readMissionLoggerIdentity() ||
            !event ||
            typeof event !== 'object'
        ) {
            return false;
        }

        if (String(event.eventType || '') === 'activity') {
            if (
                mfMissionLoggerActivityBuffer.some(existing => {
                    return existing.eventId === event.eventId;
                })
            ) {
                return false;
            }
            mfMissionLoggerActivityBuffer.push(event);
            if (
                mfMissionLoggerActivityBuffer.length >=
                MF_MISSION_LOGGER_ACTIVITY_BUFFER_MAX
            ) {
                flushMissionActivityBuffer(
                    'activity buffer safety limit'
                );
            } else {
                scheduleMissionActivityBufferFlush();
            }
            return true;
        }

        const queue = readMissionLoggerQueue();
        const bufferedActivityCount =
            appendMissionActivityBufferToQueue(queue);

        if (
            queue.some(existing => {
                return existing.eventId === event.eventId;
            })
        ) {
            if (bufferedActivityCount > 0) {
                writeMissionLoggerQueue(queue);
            }
            return false;
        }

        queue.push(event);
        writeMissionLoggerQueue(queue);
        rememberMissionLoggerEvent(event);
        scheduleMissionLoggerEagerSync(
            `queued ${String(event.eventType || 'event')}`
        );
        return true;
    }

    function readMissionLoggerPendingBatch() {
        try {
            const parsed = JSON.parse(
                localStorage.getItem(
                    MF_MISSION_LOGGER_PENDING_BATCH_KEY
                ) || 'null'
            );

            if (
                !parsed ||
                typeof parsed !== 'object' ||
                !parsed.batchId ||
                !Array.isArray(parsed.eventIds)
            ) {
                return null;
            }

            return parsed;
        } catch (_error) {
            return null;
        }
    }

    function writeMissionLoggerPendingBatch(batch) {
        if (!batch) {
            localStorage.removeItem(
                MF_MISSION_LOGGER_PENDING_BATCH_KEY
            );
            return;
        }

        localStorage.setItem(
            MF_MISSION_LOGGER_PENDING_BATCH_KEY,
            JSON.stringify(batch)
        );
    }

    function isTrustedMissionLoggerResponseOrigin(origin) {
        try {
            const url = new URL(String(origin || ''));
            return url.protocol === 'https:' && (
                url.hostname === 'script.google.com' ||
                url.hostname === 'script.googleusercontent.com' ||
                url.hostname.endsWith('.googleusercontent.com')
            );
        } catch (_error) {
            return false;
        }
    }

    function isMissionLoggerResponseWindow(source, frame) {
        const expectedWindow = frame?.contentWindow;
        if (!source || !expectedWindow) return false;

        let currentWindow = source;

        // Apps Script can serve HtmlService output inside one or more Google
        // sandbox frames. The postMessage source is then a child of the form's
        // target iframe instead of the target iframe itself. Walk only the
        // browser-exposed parent chain and require it to reach that exact
        // request iframe; the nonce and trusted Google-origin checks still
        // apply independently.
        for (let depth = 0; depth < 6; depth += 1) {
            if (currentWindow === expectedWindow) return true;

            try {
                const parentWindow = currentWindow.parent;
                if (
                    !parentWindow ||
                    parentWindow === currentWindow
                ) {
                    break;
                }
                currentWindow = parentWindow;
            } catch (_error) {
                return false;
            }
        }

        return false;
    }

    function cleanupMissionLoggerRequest(requestId) {
        const pending =
            mfMissionLoggerPendingRequests.get(requestId);
        if (!pending) return;

        clearTimeout(pending.timeoutId);
        pending.form?.remove();
        pending.frame?.remove();
        mfMissionLoggerPendingRequests.delete(requestId);
    }

    function installMissionLoggerMessageHandler() {
        if (mfMissionLoggerMessageHandler) return;

        mfMissionLoggerMessageHandler = event => {
            const data = event?.data;

            if (
                !data ||
                typeof data !== 'object' ||
                data.source !==
                    MF_MISSION_LOGGER_MESSAGE_SOURCE ||
                !data.requestId
            ) {
                return;
            }

            const requestId = String(data.requestId);
            const pending =
                mfMissionLoggerPendingRequests.get(requestId);

            if (
                !pending ||
                !isMissionLoggerResponseWindow(
                    event.source,
                    pending.frame
                ) ||
                !isTrustedMissionLoggerResponseOrigin(
                    event.origin
                )
            ) {
                return;
            }

            cleanupMissionLoggerRequest(requestId);

            if (data.ok === true) {
                pending.resolve(data);
                return;
            }

            const error = new Error(
                String(
                    data.error ||
                    'Google logger rejected the request.'
                )
            );
            error.code = String(data.code || 'LOGGER_REJECTED');
            pending.reject(error);
        };

        window.addEventListener(
            'message',
            mfMissionLoggerMessageHandler
        );

        try {
            if (
                window.top !== window &&
                window.top.location.origin ===
                    window.location.origin
            ) {
                window.top.addEventListener(
                    'message',
                    mfMissionLoggerMessageHandler
                );
            }
        } catch (_error) {}
    }

    function submitMissionLoggerRequest(action, payload) {
        const endpoint = normaliseMissionLoggerEndpoint(
            mfMissionLoggerEndpoint
        );

        if (!endpoint) {
            return Promise.reject(
                new Error(
                    'A valid Google Apps Script logger endpoint is required.'
                )
            );
        }

        installMissionLoggerMessageHandler();

        const requestId = createMissionLoggerId('request');
        const frameName =
            `mf-mission-logger-${requestId}`;
        const frame = document.createElement('iframe');
        frame.name = frameName;
        frame.hidden = true;
        frame.setAttribute('aria-hidden', 'true');
        frame.style.display = 'none';

        const form = document.createElement('form');
        form.method = 'POST';
        form.action = endpoint;
        form.target = frameName;
        form.enctype =
            'application/x-www-form-urlencoded';
        form.style.display = 'none';

        const requestPayload = Object.assign(
            {},
            payload && typeof payload === 'object'
                ? payload
                : {},
            {
                action: String(action || ''),
                requestId,
                replyOrigin: window.location.origin,
                schemaVersion:
                    MF_MISSION_LOGGER_SCHEMA_VERSION,
                clientVersion:
                    MF_MISSION_LOGGER_CLIENT_VERSION
            }
        );

        const fields = {
            payload: JSON.stringify(requestPayload),
            request_id: requestId,
            reply_origin: window.location.origin
        };

        Object.entries(fields).forEach(([name, value]) => {
            const input = document.createElement('input');
            input.type = 'hidden';
            input.name = name;
            input.value = String(value);
            form.appendChild(input);
        });

        document.body.appendChild(frame);
        document.body.appendChild(form);

        return new Promise((resolve, reject) => {
            const timeoutId = setTimeout(() => {
                cleanupMissionLoggerRequest(requestId);
                const error = new Error(
                    'Google logger request timed out. The batch remains queued.'
                );
                error.code = 'LOGGER_TIMEOUT';
                reject(error);
            }, MF_MISSION_LOGGER_REQUEST_TIMEOUT_MS);

            mfMissionLoggerPendingRequests.set(
                requestId,
                {
                    resolve,
                    reject,
                    timeoutId,
                    frame,
                    form
                }
            );

            try {
                form.submit();
            } catch (error) {
                cleanupMissionLoggerRequest(requestId);
                reject(error);
            }
        });
    }

    function getMissionLoggerDeviceStagger(
        maxMs = MF_MISSION_LOGGER_DEVICE_STAGGER_MAX_MS,
        identity = readMissionLoggerIdentity()
    ) {
        const limit = Math.max(
            1,
            Math.trunc(Number(maxMs) || 1)
        );
        const value = String(
            identity?.deviceId || MF_INSTANCE_TOKEN || ''
        );
        let hash = 2166136261;
        for (let index = 0; index < value.length; index += 1) {
            hash ^= value.charCodeAt(index);
            hash = Math.imul(hash, 16777619);
        }
        return (hash >>> 0) % limit;
    }

    function isMissionLoggerPassiveObserverOwner() {
        if (!mfMissionLoggerEnabled) return false;
        if (mfMissionLoggerObserverLeaseSupported === false) {
            return true;
        }
        return !!(
            mfMissionLoggerObserverLeaseOwner &&
            Date.now() < mfMissionLoggerObserverLeaseExpiresAt
        );
    }

    function clearMissionLoggerObserverLeaseTimer() {
        if (!mfMissionLoggerObserverLeaseTimer) return;
        clearTimeout(mfMissionLoggerObserverLeaseTimer);
        mfMissionLoggerObserverLeaseTimer = null;
    }

    function stopMissionLoggerObserverLease() {
        clearMissionLoggerObserverLeaseTimer();
        mfMissionLoggerObserverLeaseOwner = false;
        mfMissionLoggerObserverLeaseExpiresAt = 0;
        if (mfMissionLoggerGenerationArmTimer) {
            clearTimeout(mfMissionLoggerGenerationArmTimer);
            mfMissionLoggerGenerationArmTimer = null;
        }
        mfMissionLoggerGenerationArmed = false;
    }

    function scheduleMissionLoggerObserverLeaseRefresh(
        delayMs = MF_MISSION_LOGGER_OBSERVER_RETRY_MS
    ) {
        clearMissionLoggerObserverLeaseTimer();
        if (
            !MF_IS_TOP_WINDOW ||
            !mfMissionLoggerEnabled ||
            !mfMissionLoggerEndpoint ||
            !readMissionLoggerIdentity() ||
            mfMissionLoggerObserverLeaseSupported === false
        ) {
            return false;
        }

        mfMissionLoggerObserverLeaseTimer = setTimeout(
            () => {
                mfMissionLoggerObserverLeaseTimer = null;
                void refreshMissionLoggerObserverLease(
                    'scheduled observer lease refresh'
                );
            },
            Math.max(250, Math.trunc(Number(delayMs) || 0))
        );
        return true;
    }

    function activateMissionLoggerPassiveObserver() {
        mfMissionLoggerGenerationArmed = false;
        installMissionLoggerMissionGenerationCapture();
        scanMissionLoggerMissionList(document, true);
        scheduleMissionLoggerGenerationArm();
        recordMissionLoggerObservedEvent();
    }

    async function refreshMissionLoggerObserverLease(
        reason = 'observer lease refresh'
    ) {
        if (
            !MF_IS_TOP_WINDOW ||
            !mfMissionLoggerEnabled ||
            !mfMissionLoggerEndpoint
        ) {
            stopMissionLoggerObserverLease();
            return false;
        }
        if (mfMissionLoggerObserverLeaseSupported === false) {
            return true;
        }
        if (mfMissionLoggerObserverLeaseRequest) {
            return mfMissionLoggerObserverLeaseRequest;
        }

        const identity = readMissionLoggerIdentity();
        if (!identity) return false;

        const request = (async () => {
            try {
                const response = await submitMissionLoggerRequest(
                    'observer-lease',
                    {
                        profileId: identity.playerId,
                        username: identity.playerName,
                        deviceId: identity.deviceId,
                        deviceLabel: identity.deviceLabel,
                        leaseMs:
                            MF_MISSION_LOGGER_OBSERVER_LEASE_MS,
                        reason: String(reason || '').slice(0, 120)
                    }
                );
                updateMissionActivityBackendCapability(response);
                mfMissionLoggerObserverLeaseSupported = true;
                mfMissionLoggerObserverLeaseOwner =
                    response.granted === true;
                const parsedExpiry = Date.parse(
                    String(response.expiresAt || '')
                );
                mfMissionLoggerObserverLeaseExpiresAt =
                    Number.isFinite(parsedExpiry)
                        ? parsedExpiry
                        : Date.now() + Math.max(
                            5000,
                            Number(response.leaseMs || 0) ||
                                MF_MISSION_LOGGER_OBSERVER_LEASE_MS
                        );

                if (mfMissionLoggerObserverLeaseOwner) {
                    activateMissionLoggerPassiveObserver();
                } else {
                    if (mfMissionLoggerGenerationArmTimer) {
                        clearTimeout(
                            mfMissionLoggerGenerationArmTimer
                        );
                        mfMissionLoggerGenerationArmTimer = null;
                    }
                    mfMissionLoggerGenerationArmed = false;
                }

                const remaining = Math.max(
                    1000,
                    mfMissionLoggerObserverLeaseExpiresAt - Date.now()
                );
                const nextDelay =
                    mfMissionLoggerObserverLeaseOwner
                        ? Math.max(
                            5000,
                            Math.min(
                                MF_MISSION_LOGGER_OBSERVER_RENEW_MS,
                                remaining - 10000
                            )
                        )
                        : Math.max(
                            1000,
                            Number(response.retryAfterMs || 0) ||
                                MF_MISSION_LOGGER_OBSERVER_RETRY_MS
                        ) + getMissionLoggerDeviceStagger(5000, identity);
                scheduleMissionLoggerObserverLeaseRefresh(nextDelay);
                return mfMissionLoggerObserverLeaseOwner;
            } catch (error) {
                if (
                    String(error?.code || '') ===
                    'UNKNOWN_ACTION'
                ) {
                    // The v1.1.12 userscript is safe against the previous
                    // private backend. Until Code.gs is deployed, each device
                    // keeps the old passive-observer behaviour rather than
                    // silently losing mission observations.
                    mfMissionLoggerObserverLeaseSupported = false;
                    mfMissionLoggerObserverLeaseOwner = true;
                    mfMissionLoggerObserverLeaseExpiresAt =
                        Number.MAX_SAFE_INTEGER;
                    activateMissionLoggerPassiveObserver();
                    return true;
                }

                if (
                    Date.now() >=
                    mfMissionLoggerObserverLeaseExpiresAt
                ) {
                    mfMissionLoggerObserverLeaseOwner = false;
                }
                scheduleMissionLoggerObserverLeaseRefresh(
                    MF_MISSION_LOGGER_OBSERVER_RETRY_MS +
                        getMissionLoggerDeviceStagger(5000, identity)
                );
                return isMissionLoggerPassiveObserverOwner();
            }
        })();

        mfMissionLoggerObserverLeaseRequest = request;
        try {
            return await request;
        } finally {
            if (mfMissionLoggerObserverLeaseRequest === request) {
                mfMissionLoggerObserverLeaseRequest = null;
            }
        }
    }

    function getMissionLoggerDeviceLabel() {
        const platform = String(
            navigator.userAgentData?.platform ||
            navigator.platform ||
            ''
        ).trim();
        const browser = /Edg\//i.test(navigator.userAgent)
            ? 'Edge'
            : /Chrome\//i.test(navigator.userAgent)
                ? 'Chrome'
                : /Safari\//i.test(navigator.userAgent)
                    ? 'Safari'
                    : /Firefox\//i.test(navigator.userAgent)
                        ? 'Firefox'
                        : 'Browser';

        return [platform, browser]
            .filter(Boolean)
            .join(' · ')
            .slice(0, 120) ||
            'MissionChief browser';
    }

    function acquireMissionLoggerSyncLock() {
        const now = Date.now();
        const owner = `${MF_INSTANCE_TOKEN}:${createMissionLoggerId('sync')}`;

        try {
            const existing = JSON.parse(
                localStorage.getItem(
                    MF_MISSION_LOGGER_SYNC_LOCK_KEY
                ) || 'null'
            );

            if (
                existing &&
                Number(existing.expiresAt || 0) > now
            ) {
                return '';
            }

            localStorage.setItem(
                MF_MISSION_LOGGER_SYNC_LOCK_KEY,
                JSON.stringify({
                    owner,
                    expiresAt:
                        now +
                        MF_MISSION_LOGGER_SYNC_LOCK_LEASE_MS
                })
            );

            const confirmed = JSON.parse(
                localStorage.getItem(
                    MF_MISSION_LOGGER_SYNC_LOCK_KEY
                ) || 'null'
            );

            return confirmed?.owner === owner
                ? owner
                : '';
        } catch (_error) {
            return '';
        }
    }

    function releaseMissionLoggerSyncLock(owner) {
        if (!owner) return;

        try {
            const existing = JSON.parse(
                localStorage.getItem(
                    MF_MISSION_LOGGER_SYNC_LOCK_KEY
                ) || 'null'
            );

            if (existing?.owner === owner) {
                localStorage.removeItem(
                    MF_MISSION_LOGGER_SYNC_LOCK_KEY
                );
            }
        } catch (_error) {}
    }

    function refreshMissionLoggerSyncLock(owner) {
        if (!owner) return false;

        try {
            const existing = JSON.parse(
                localStorage.getItem(
                    MF_MISSION_LOGGER_SYNC_LOCK_KEY
                ) || 'null'
            );
            if (existing?.owner !== owner) return false;

            localStorage.setItem(
                MF_MISSION_LOGGER_SYNC_LOCK_KEY,
                JSON.stringify({
                    owner,
                    expiresAt:
                        Date.now() +
                        MF_MISSION_LOGGER_SYNC_LOCK_LEASE_MS
                })
            );
            return true;
        } catch (_error) {
            return false;
        }
    }

    async function submitMissionLoggerUploadBatch(
        identity,
        pending,
        batchEvents,
        lockOwner
    ) {
        let lastError = null;

        for (
            let busyAttempt = 0;
            busyAttempt <=
                MF_MISSION_LOGGER_BUSY_RETRY_DELAYS_MS.length;
            busyAttempt += 1
        ) {
            try {
                for (
                    let attempt = 0;
                    attempt < 2;
                    attempt += 1
                ) {
                    if (!refreshMissionLoggerSyncLock(lockOwner)) {
                        const error = new Error(
                            'The shared logger upload lock was lost before the batch could be confirmed.'
                        );
                        error.code = 'LOGGER_LOCK_LOST';
                        throw error;
                    }

                    try {
                        return await submitMissionLoggerRequest(
                            'upload',
                            {
                                profileName:
                                    identity.legacyPlayerName ||
                                    identity.playerName,
                                profileId: identity.playerId,
                                username: identity.playerName,
                                deviceId: identity.deviceId,
                                deviceLabel: identity.deviceLabel,
                                batchId: pending.batchId,
                                events: batchEvents
                            }
                        );
                    } catch (error) {
                        lastError = error;
                        if (
                            String(error?.code || '') !==
                                'LOGGER_TIMEOUT' ||
                            attempt > 0
                        ) {
                            throw error;
                        }

                        writeMissionLoggerState({
                            drainMessage:
                                'Google is still processing the batch; confirming the same batch ID once more.'
                        });
                        await wait(
                            MF_MISSION_LOGGER_BATCH_CONFIRM_RETRY_DELAY_MS
                        );
                    }
                }
            } catch (error) {
                lastError = error;
                if (
                    String(error?.code || '') !==
                        'LOGGER_BUSY' ||
                    busyAttempt >=
                        MF_MISSION_LOGGER_BUSY_RETRY_DELAYS_MS.length
                ) {
                    throw error;
                }

                const retryDelay =
                    MF_MISSION_LOGGER_BUSY_RETRY_DELAYS_MS[
                        busyAttempt
                    ] +
                    getMissionLoggerDeviceStagger(1500, identity) +
                    Math.floor(Math.random() * 750);
                writeMissionLoggerState({
                    lastError: '',
                    drainMessage:
                        `Google logger is busy; retrying the same batch ID in ${Math.ceil(retryDelay / 1000)}s.`
                });
                await wait(retryDelay);
            }
        }

        throw lastError || new Error(
            'Google logger upload could not be confirmed.'
        );
    }

    async function syncMissionLoggerNow(options = {}) {
        if (mfMissionLoggerSyncActive) {
            if (
                options.manual === true ||
                options.reconnected === true ||
                options.backlog === true
            ) {
                scheduleMissionLoggerDeferredDrain(
                    options.reason ||
                    'sync requested during active upload',
                    {
                        manual:
                            options.manual === true ||
                            mfMissionLoggerManualDrainRequested
                    }
                );
                return true;
            }
            return false;
        }
        if (!mfMissionLoggerEnabled) return false;

        flushMissionActivityBuffer('before sync');
        const identity = readMissionLoggerIdentity();
        if (!identity || !mfMissionLoggerEndpoint) {
            renderMissionLoggerStatus();
            return false;
        }

        if (options.skipCreditReconcile !== true) {
            await reconcileMissionLoggerCreditTransactions({
                force:
                    options.manual === true ||
                    options.reconnected === true,
                includeOlder:
                    options.manual === true ||
                    options.reconnected === true,
                maxPages:
                    options.manual === true ||
                    options.reconnected === true
                        ? MF_MISSION_LOGGER_CREDIT_CATCHUP_PAGES_PER_RUN
                        : undefined,
                allowOfflineRecovery: true
            });
        }

        if (isMissionPage()) {
            try {
                const currentMissionId = String(
                    getCurrentMissionIdForQueueRestart() || ''
                );
                const needsDefinitionEnrichment =
                    readMissionLoggerQueue().some(event => {
                        return (
                            String(event?.missionId || '') ===
                                currentMissionId &&
                            (
                                Number(
                                    event?.advertisedCredits || 0
                                ) <= 0 ||
                                !Array.isArray(
                                    event?.requirements
                                ) ||
                                event.requirements.length === 0 ||
                                !event?.generatorStationName
                            )
                        );
                    });

                if (needsDefinitionEnrichment) {
                    await preloadMissionRequiredPersonnel();
                }
            } catch (_error) {}

            enrichMissionLoggerQueuedEventsFromCurrentMission();
        }

        if (readMissionLoggerQueue().length === 0) {
            if (options.manual === true) {
                writeMissionLoggerState({
                    lastError: '',
                    drainRequestedAt: 0,
                    drainMessage: ''
                });
            }
            renderMissionLoggerStatus();
            return true;
        }

        const lockOwner = acquireMissionLoggerSyncLock();
        if (!lockOwner) {
            if (
                options.manual === true ||
                options.reconnected === true ||
                options.backlog === true
            ) {
                scheduleMissionLoggerDeferredDrain(
                    options.reason ||
                    'waiting for another MissionChief tab',
                    {
                        manual:
                            options.manual === true ||
                            mfMissionLoggerManualDrainRequested
                    }
                );
                return true;
            }
            return false;
        }

        const manualDrain =
            options.manual === true ||
            options.reconnected === true ||
            mfMissionLoggerManualDrainRequested;
        mfMissionLoggerManualDrainRequested = false;
        const maxBatches = manualDrain
            ? MF_MISSION_LOGGER_MANUAL_DRAIN_MAX_BATCHES
            : MF_MISSION_LOGGER_AUTO_DRAIN_MAX_BATCHES;
        const drainStartedAt = Date.now();
        let uploadedAny = false;
        let needsFollowupDrain = false;

        mfMissionLoggerSyncActive = true;
        writeMissionLoggerState({
            lastAttemptAt: Date.now(),
            lastError: '',
            drainRequestedAt: 0,
            drainMessage: ''
        });

        try {
            for (
                let batchNumber = 0;
                batchNumber < maxBatches;
                batchNumber += 1
            ) {
                if (
                    Date.now() - drainStartedAt >=
                    MF_MISSION_LOGGER_DRAIN_MAX_MS
                ) {
                    needsFollowupDrain =
                        readMissionLoggerQueue().length > 0;
                    break;
                }

                const queue = readMissionLoggerQueue();
                if (queue.length === 0) break;

                let pending = readMissionLoggerPendingBatch();
                const queueById = new Map(
                    queue.map(event => [event.eventId, event])
                );

                if (pending) {
                    pending.eventIds = pending.eventIds.filter(
                        eventId => queueById.has(eventId)
                    );

                    if (pending.eventIds.length === 0) {
                        pending = null;
                        writeMissionLoggerPendingBatch(null);
                    } else {
                        writeMissionLoggerPendingBatch(pending);
                    }
                }

                if (!pending) {
                    const events = queue.slice(
                        0,
                        MF_MISSION_LOGGER_BATCH_SIZE
                    );
                    pending = {
                        batchId: createMissionLoggerId('batch'),
                        eventIds: events.map(
                            event => event.eventId
                        ),
                        createdAt: new Date().toISOString()
                    };
                    writeMissionLoggerPendingBatch(pending);
                }

                const batchEvents = pending.eventIds
                    .map(eventId => queueById.get(eventId))
                    .filter(Boolean);

                if (batchEvents.length === 0) {
                    writeMissionLoggerPendingBatch(null);
                    continue;
                }

                writeMissionLoggerState({
                    lastAttemptAt: Date.now(),
                    lastError: ''
                });

                const response =
                    await submitMissionLoggerUploadBatch(
                        identity,
                        pending,
                        batchEvents,
                        lockOwner
                    );

                updateMissionActivityBackendCapability(response);

                if (
                    response.batchId &&
                    String(response.batchId) !==
                        String(pending.batchId)
                ) {
                    throw new Error(
                        'Google logger acknowledged a different batch.'
                    );
                }

                const acknowledged = new Set(
                    pending.eventIds
                );
                const remaining = readMissionLoggerQueue()
                    .filter(event => {
                        return !acknowledged.has(event.eventId);
                    });

                writeMissionLoggerQueue(remaining);
                writeMissionLoggerPendingBatch(null);

                const state = readMissionLoggerState();
                writeMissionLoggerState({
                    lastSuccessAt: Date.now(),
                    lastError: '',
                    drainMessage:
                        `Uploaded ${batchEvents.length} event${batchEvents.length === 1 ? '' : 's'}; ${remaining.length} queued.`,
                    totalUploadedEvents:
                        Math.max(
                            0,
                            Number(
                                state.totalUploadedEvents || 0
                            )
                        ) + batchEvents.length
                });
                uploadedAny = true;

                if (remaining.length === 0) break;

                needsFollowupDrain = true;
                await wait(
                    MF_MISSION_LOGGER_DRAIN_GAP_MS
                );
            }

            needsFollowupDrain =
                readMissionLoggerQueue().length > 0;
            return uploadedAny;
        } catch (error) {
            writeMissionLoggerState({
                lastError: String(
                    error?.message ||
                    'Google logger upload failed.'
                ).slice(0, 500)
            });
            needsFollowupDrain = false;
            return false;
        } finally {
            mfMissionLoggerSyncActive = false;
            releaseMissionLoggerSyncLock(lockOwner);
            renderMissionLoggerStatus();

            if (mfMissionLoggerManualDrainRequested) {
                scheduleMissionLoggerDeferredDrain(
                    'manual sync requested during active drain',
                    {
                        manual: true,
                        delayMs:
                            MF_MISSION_LOGGER_DRAIN_GAP_MS
                    }
                );
            } else if (needsFollowupDrain) {
                scheduleMissionLoggerEagerSync(
                    'backlog remains after bounded drain',
                    true
                );
            }
        }
    }

    function stopMissionLoggerSyncTimer() {
        flushMissionActivityBuffer('sync timer stopped');
        stopMissionLoggerObserverLease();
        if (mfMissionLoggerDeferredDrainTimer) {
            clearTimeout(mfMissionLoggerDeferredDrainTimer);
            mfMissionLoggerDeferredDrainTimer = null;
        }
        mfMissionLoggerManualDrainRequested = false;
        if (mfMissionLoggerEagerSyncTimer) {
            clearTimeout(mfMissionLoggerEagerSyncTimer);
            mfMissionLoggerEagerSyncTimer = null;
        }
        if (mfMissionLoggerInitialSyncTimer) {
            clearTimeout(mfMissionLoggerInitialSyncTimer);
            mfMissionLoggerInitialSyncTimer = null;
        }
        if (mfMissionLoggerSyncTimer) {
            clearInterval(mfMissionLoggerSyncTimer);
            mfMissionLoggerSyncTimer = null;
        }
    }

    function startMissionLoggerSyncTimer() {
        if (!MF_IS_TOP_WINDOW) return;

        installMissionLoggerConnectivityListener();

        if (
            !mfMissionLoggerEnabled ||
            !mfMissionLoggerEndpoint ||
            !readMissionLoggerIdentity()
        ) {
            stopMissionLoggerSyncTimer();
            stopMissionLoggerCreditReconciliation();
            return;
        }

        scheduleMissionLoggerObserverLeaseRefresh(
            250 + getMissionLoggerDeviceStagger(1000)
        );
        startMissionLoggerCreditReconciliation();

        if (!mfMissionLoggerStartupDrainChecked) {
            mfMissionLoggerStartupDrainChecked = true;
            if (readMissionLoggerQueue().length > 0) {
                scheduleMissionLoggerDeferredDrain(
                    'existing sharing and sync backlog',
                    {
                        manual: true,
                        delayMs:
                            500 +
                            getMissionLoggerDeviceStagger(2000)
                    }
                );
            }
        }

        if (
            mfMissionLoggerInitialSyncTimer ||
            mfMissionLoggerSyncTimer
        ) {
            return;
        }

        const state = readMissionLoggerState();
        const elapsed = Math.max(
            0,
            Date.now() - Number(state.lastAttemptAt || 0)
        );
        const initialDelay = state.lastAttemptAt
            ? Math.max(
                1000,
                MF_MISSION_LOGGER_SYNC_INTERVAL_MS - elapsed
            )
            : 5000;
        const staggeredInitialDelay = Math.min(
            MF_MISSION_LOGGER_SYNC_INTERVAL_MS,
            initialDelay + getMissionLoggerDeviceStagger()
        );

        mfMissionLoggerInitialSyncTimer = setTimeout(
            async () => {
                mfMissionLoggerInitialSyncTimer = null;
                await syncMissionLoggerNow();

                if (
                    !mfMissionLoggerEnabled ||
                    mfMissionLoggerSyncTimer
                ) {
                    return;
                }

                mfMissionLoggerSyncTimer = setInterval(
                    () => {
                        void syncMissionLoggerNow();
                    },
                    MF_MISSION_LOGGER_SYNC_INTERVAL_MS
                );
            },
            staggeredInitialDelay
        );
    }

    function installMissionLoggerStorageListener() {
        if (mfMissionLoggerStorageHandler) return;

        mfMissionLoggerStorageHandler = event => {
            if (
                !event ||
                ![
                    MF_MISSION_LOGGER_ENABLED_KEY,
                    MF_MISSION_LOGGER_ENDPOINT_KEY,
                    MF_MISSION_LOGGER_PROFILE_KEY,
                    MF_MISSION_LOGGER_LEGACY_IDENTITY_KEY,
                    MF_MISSION_LOGGER_QUEUE_KEY,
                    MF_MISSION_LOGGER_STATE_KEY,
                    MF_MISSION_LOGGER_DRAIN_REQUEST_KEY
                ].includes(event.key)
            ) {
                return;
            }

            mfMissionLoggerEnabled =
                localStorage.getItem(
                    MF_MISSION_LOGGER_ENABLED_KEY
                ) === 'true';
            mfMissionLoggerEndpoint =
                normaliseMissionLoggerEndpoint(
                    MF_MISSION_LOGGER_FIXED_ENDPOINT
                );
            if (
                mfMissionLoggerEndpoint &&
                localStorage.getItem(
                    MF_MISSION_LOGGER_ENDPOINT_KEY
                ) !== mfMissionLoggerEndpoint
            ) {
                localStorage.setItem(
                    MF_MISSION_LOGGER_ENDPOINT_KEY,
                    mfMissionLoggerEndpoint
                );
            }

            if (MF_IS_TOP_WINDOW) {
                startMissionLoggerSyncTimer();
                if (
                    event.key ===
                    MF_MISSION_LOGGER_QUEUE_KEY
                ) {
                    scheduleMissionLoggerEagerSync(
                        'cross-window queue update'
                    );
                }
                if (
                    event.key ===
                    MF_MISSION_LOGGER_DRAIN_REQUEST_KEY
                ) {
                    let request = null;
                    try {
                        request = JSON.parse(
                            String(event.newValue || 'null')
                        );
                    } catch (_error) {}
                    scheduleMissionLoggerDeferredDrain(
                        request?.reason ||
                            'cross-window manual drain request',
                        {
                            manual:
                                request?.manual === true,
                            delayMs: 100
                        }
                    );
                }
            }
            renderMissionLoggerStatus();
        };

        window.addEventListener(
            'storage',
            mfMissionLoggerStorageHandler
        );
    }

    function installMissionLoggerConnectivityListener() {
        if (!MF_IS_TOP_WINDOW || mfMissionLoggerOnlineHandler) {
            return;
        }

        mfMissionLoggerOnlineHandler = () => {
            if (
                !mfMissionLoggerEnabled ||
                !mfMissionLoggerEndpoint ||
                !readMissionLoggerIdentity()
            ) {
                return;
            }

            void syncMissionLoggerNow({
                reconnected: true
            });
        };

        window.addEventListener(
            'online',
            mfMissionLoggerOnlineHandler
        );
    }

    async function forgetMissionLoggerSetup() {
        clearMissionLoggerProfileScopedData();
        localStorage.removeItem(
            MF_MISSION_LOGGER_PROFILE_KEY
        );
        localStorage.removeItem(
            MF_MISSION_LOGGER_LEGACY_IDENTITY_KEY
        );
        localStorage.removeItem(
            MF_MISSION_LOGGER_ENDPOINT_KEY
        );
        mfMissionLoggerEndpoint = '';
        mfMissionLoggerEnabled = false;
        localStorage.setItem(
            MF_MISSION_LOGGER_ENABLED_KEY,
            'false'
        );
        stopMissionLoggerSyncTimer();
        stopMissionLoggerCreditReconciliation();
        renderMissionLoggerStatus();
    }

    function trimMissionLoggerText(value, maxLength = 300) {
        const text = String(value || '')
            .replace(/\u00a0/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();

        return text.slice(0, Math.max(1, maxLength));
    }

    function getMissionLoggerDefinitionId() {
        const missionInfo =
            getActiveVisibleMissionInfo?.() ||
            document.querySelector('#mission_general_info');
        const attributes = [
            'data-mission-type-id',
            'data-mission-definition-id',
            'data-einsatz-id',
            'mission_type_id'
        ];

        for (const attribute of attributes) {
            const value = String(
                missionInfo?.getAttribute?.(attribute) || ''
            ).trim();
            if (/^\d+$/.test(value)) return value;
        }

        const helpLink = getActiveMissionHelpLink?.();
        const href = String(
            helpLink?.href ||
            helpLink?.getAttribute?.('href') ||
            ''
        );
        const match = href.match(
            /\/(?:einsaetze|missions\/help)\/(\d+)/i
        );
        return match ? match[1] : '';
    }

    function getMissionLoggerSameOriginWindows() {
        const windows = [];
        const addWindow = candidate => {
            if (!candidate || windows.includes(candidate)) return;

            try {
                if (
                    candidate.location.origin !==
                    window.location.origin
                ) {
                    return;
                }
                windows.push(candidate);
            } catch (_error) {}
        };

        addWindow(window);
        try { addWindow(window.parent); } catch (_error) {}
        try { addWindow(window.top); } catch (_error) {}

        windows.slice().forEach(candidate => {
            try {
                Array.from(
                    candidate.document.querySelectorAll('iframe')
                ).slice(0, 20).forEach(frame => {
                    addWindow(frame.contentWindow);
                });
            } catch (_error) {}
        });

        return windows;
    }

    function getMissionLoggerCacheRecord(cache, id) {
        if (!cache || !id) return null;

        const numericId = Number(id);
        const keys = [
            id,
            Number.isFinite(numericId) ? numericId : id
        ];

        if (typeof cache.get === 'function') {
            for (const key of keys) {
                try {
                    const value = cache.get(key);
                    if (value) return value;
                } catch (_error) {}
            }
        }

        if (Array.isArray(cache)) {
            return cache.find(item => {
                return String(
                    item?.id ??
                    item?.mission_id ??
                    item?.building_id ??
                    ''
                ) === id;
            }) || null;
        }

        if (typeof cache === 'object') {
            for (const key of keys) {
                try {
                    if (cache[key]) return cache[key];
                } catch (_error) {}
            }
        }

        return null;
    }

    function getMissionLoggerBuildingName(buildingId) {
        const id = String(buildingId || '').trim();
        if (!/^\d+$/.test(id)) return '';

        for (const candidate of getMissionLoggerSameOriginWindows()) {
            const cacheNames = [
                'building_markers_params_cache_per_id',
                'buildings_data'
            ];

            for (const cacheName of cacheNames) {
                try {
                    const building = getMissionLoggerCacheRecord(
                        candidate[cacheName],
                        id
                    );
                    const name = trimMissionLoggerText(
                        building?.name ||
                        building?.caption ||
                        '',
                        160
                    );
                    if (name) return name;
                } catch (_error) {}
            }

            try {
                const row = candidate.document.querySelector(
                    `#building_list_${id}, [data-building_id="${id}"]`
                );
                const name = trimMissionLoggerText(
                    row?.querySelector(
                        '.map_position_mover, .building_list_caption a:not(.btn)'
                    )?.textContent ||
                    '',
                    160
                );
                if (name) return name;
            } catch (_error) {}
        }

        return '';
    }

    function getMissionLoggerMissionSnapshot() {
        const missionId = String(
            getCurrentMissionIdForQueueRestart() || ''
        ).trim();
        const snapshot = {
            missionId,
            missionDefinitionId: '',
            advertisedCredits: 0,
            patientCount: 0,
            possiblePatientCount: 0,
            prisonerCount: null,
            possiblePrisonerCount: null,
            generatorStationId: '',
            generatorStationName: '',
            generatorSource: '',
            source: ''
        };

        if (!/^\d+$/.test(missionId)) return snapshot;

        const numberOrNull = value => {
            const parsed = Number(value);
            return Number.isFinite(parsed) && parsed >= 0
                ? parsed
                : null;
        };
        const applyCountPair = (value, currentKey, possibleKey) => {
            const pair = Array.isArray(value)
                ? value
                : [value, null];
            const current = numberOrNull(pair[0]);
            const possible = numberOrNull(pair[1]);

            if (current !== null) {
                snapshot[currentKey] = Math.max(
                    Number(snapshot[currentKey] || 0),
                    current
                );
            }
            if (possible !== null) {
                const existing = snapshot[possibleKey];
                snapshot[possibleKey] = existing === null
                    ? possible
                    : Math.max(Number(existing || 0), possible);
            }
        };

        for (const candidate of getMissionLoggerSameOriginWindows()) {
            let mission = null;
            try {
                mission = getMissionLoggerCacheRecord(
                    candidate.missions_data,
                    missionId
                );
            } catch (_error) {}

            if (mission) {
                snapshot.source = snapshot.source || 'mission-marker';
                snapshot.missionDefinitionId = String(
                    mission.mtid ||
                    mission.mission_type_id ||
                    snapshot.missionDefinitionId ||
                    ''
                );
                snapshot.advertisedCredits = Math.max(
                    snapshot.advertisedCredits,
                    numberOrNull(
                        mission.average_credits ??
                        mission.advertised_credits
                    ) || 0
                );
                applyCountPair(
                    [
                        mission.patients_count,
                        mission.possible_patients_count
                    ],
                    'patientCount',
                    'possiblePatientCount'
                );
                applyCountPair(
                    [
                        mission.prisoners_count,
                        mission.possible_prisoners_count
                    ],
                    'prisonerCount',
                    'possiblePrisonerCount'
                );

                const generatorId = String(
                    mission.generator_building_id ??
                    mission.generated_by_building_id ??
                    mission.building_id ??
                    ''
                ).trim();
                if (/^\d+$/.test(generatorId)) {
                    snapshot.generatorStationId = generatorId;
                    snapshot.generatorSource = 'mission-marker';
                }

                const generatorName = trimMissionLoggerText(
                    mission.generator_building_name ??
                    mission.generated_by_name ??
                    mission.generated_by ??
                    '',
                    160
                );
                if (generatorName) {
                    snapshot.generatorStationName = generatorName;
                    snapshot.generatorSource =
                        snapshot.generatorSource ||
                        'mission-marker';
                }
            }

            let row = null;
            try {
                row = candidate.document.getElementById(
                    `mission_${missionId}`
                );
            } catch (_error) {}
            if (!row) continue;

            snapshot.source = snapshot.source || 'mission-list';
            snapshot.missionDefinitionId = String(
                row.getAttribute('mission_type_id') ||
                row.getAttribute('data-mission-type-id') ||
                snapshot.missionDefinitionId ||
                ''
            );

            try {
                const sortable = JSON.parse(
                    row.getAttribute('data-sortable-by') ||
                    row.getAttribute('data-sortable_by') ||
                    '{}'
                );
                snapshot.advertisedCredits = Math.max(
                    snapshot.advertisedCredits,
                    numberOrNull(sortable.average_credits) || 0
                );
                applyCountPair(
                    sortable.patients_count,
                    'patientCount',
                    'possiblePatientCount'
                );
                applyCountPair(
                    sortable.prisoners_count,
                    'prisonerCount',
                    'possiblePrisonerCount'
                );
            } catch (_error) {}
        }

        if (
            snapshot.generatorStationId &&
            !snapshot.generatorStationName
        ) {
            snapshot.generatorStationName =
                getMissionLoggerBuildingName(
                    snapshot.generatorStationId
                );
        }

        return snapshot;
    }

    function getMissionLoggerGenerator() {
        const snapshot = getMissionLoggerMissionSnapshot();
        const roots = [];
        const addRoot = root => {
            if (root && !roots.includes(root)) roots.push(root);
        };

        addRoot(getActiveVisibleMissionInfo?.());
        addRoot(document.querySelector('#mission_general_info'));
        try {
            getActiveMissionRequirementContexts()
                .forEach(context => addRoot(context.root));
        } catch (_error) {}

        for (const candidate of getMissionLoggerSameOriginWindows()) {
            try {
                addRoot(
                    candidate.document.querySelector(
                        '#mission_general_info'
                    )
                );
            } catch (_error) {}
        }

        for (const scope of roots) {
            const explicitGenerator =
                scope.querySelector?.(
                    '[data-generator-building-id], [data-generator-building-name]'
                );
            const labelledGeneratorRow = Array.from(
                scope.querySelectorAll?.(
                    'table tbody tr, table tr'
                ) || []
            ).find(row => {
                const label = trimMissionLoggerText(
                    row.querySelector?.('th, td')?.textContent || '',
                    120
                ).replace(/\s*:\s*$/, '');
                return /^(?:generated\s+by|generating\s+(?:station|building)|generator)$/i
                    .test(label);
            });
            const labelledCells = Array.from(
                labelledGeneratorRow?.querySelectorAll?.(
                    'td, th'
                ) || []
            );
            const genericScopeBuildingId =
                scope.id === 'mission_general_info'
                    ? (
                        scope.getAttribute?.('data-building-id') ||
                        scope.getAttribute?.('building_id')
                    )
                    : '';
            const stationId = [
                explicitGenerator?.getAttribute?.(
                    'data-generator-building-id'
                ),
                scope.getAttribute?.('data-generator-building-id'),
                labelledGeneratorRow?.getAttribute?.(
                    'data-generator-building-id'
                ),
                genericScopeBuildingId
            ].map(value => String(value || '').trim())
                .find(value => /^\d+$/.test(value)) || '';
            const stationLink =
                explicitGenerator?.closest?.('a[href*="/buildings/"]') ||
                explicitGenerator?.querySelector?.(
                    'a[href*="/buildings/"]'
                ) ||
                labelledGeneratorRow?.querySelector?.(
                    'a[href*="/buildings/"]'
                );
            const linkMatch = String(
                stationLink?.getAttribute?.('href') || ''
            ).match(/\/buildings\/(\d+)/i);
            const resolvedId = stationId || linkMatch?.[1] || '';
            const resolvedName = trimMissionLoggerText(
                explicitGenerator?.getAttribute?.(
                    'data-generator-building-name'
                ) ||
                explicitGenerator?.textContent ||
                stationLink?.textContent ||
                labelledCells.slice(1)
                    .map(cell => cell.textContent || '')
                    .join(' ') ||
                '',
                160
            );

            if (resolvedId || resolvedName) {
                return {
                    stationId: resolvedId,
                    stationName:
                        resolvedName ||
                        getMissionLoggerBuildingName(resolvedId),
                    source: 'mission-page'
                };
            }
        }

        if (
            snapshot.generatorStationId ||
            snapshot.generatorStationName
        ) {
            return {
                stationId: snapshot.generatorStationId,
                stationName: snapshot.generatorStationName,
                source:
                    snapshot.generatorSource ||
                    snapshot.source ||
                    'mission-marker'
            };
        }

        const cached = getCachedMissionGenerator();
        return {
            stationId: cached.stationId,
            stationName: cached.stationName,
            source: cached.source
        };
    }

    function getMissionLoggerOwnership() {
        const scope = getCurrentMissionValueScope();
        const text = trimMissionLoggerText(
            scope?.querySelector?.(
                '.mission_owner, .mission-owner, [data-mission-owner], [class*="alliance"]'
            )?.textContent ||
            '',
            240
        ).toLowerCase();

        if (/alliance|shared|association/.test(text)) {
            return 'alliance';
        }
        return 'own';
    }

    function getMissionLoggerRequirements() {
        const rows = [];
        const seen = new Set();
        const add = (kind, name, required, stillNeeded, source) => {
            const cleanName = trimMissionLoggerText(name, 240);
            if (!cleanName) return;

            const item = {
                kind: trimMissionLoggerText(kind, 40),
                name: cleanName,
                required: Math.max(
                    0,
                    parseInt(required, 10) || 0
                ),
                stillNeeded: Math.max(
                    0,
                    parseInt(stillNeeded, 10) || 0
                ),
                source: trimMissionLoggerText(source, 80)
            };
            const key = [
                item.kind,
                item.name,
                item.required,
                item.stillNeeded,
                item.source
            ].join('|');

            if (seen.has(key)) return;
            seen.add(key);
            rows.push(item);
        };

        try {
            vehicleLoadState.rows.forEach(row => {
                add(
                    'vehicle',
                    row.originalName || row.mappedName,
                    row.required,
                    Math.max(
                        0,
                        Number(row.required || 0) -
                            Number(row.selected || 0)
                    ),
                    'nexus-selection'
                );
            });
        } catch (_error) {}

        try {
            readMissionUpdateRows({ silent: true })
                .slice(0, 200)
                .forEach(row => {
                    add(
                        row.personnelRequirementType
                            ? 'personnel'
                            : row.patientRequirementType
                                ? 'patient'
                                : 'vehicle',
                        row.unitName ||
                            row.originalName ||
                            row.name,
                        row.required || row.stillNeeded,
                        row.stillNeeded,
                        row.source || 'mission-update'
                    );
                });
        } catch (_error) {}

        try {
            getPreloadedMissionTrainedPersonnelRequirements()
                .slice(0, 100)
                .forEach(row => {
                    add(
                        'personnel',
                        row.label || row.code,
                        row.required,
                        row.required,
                        'mission-definition'
                    );
                });
        } catch (_error) {}

        return rows.slice(0, 250);
    }

    function readMissionLoggerUnitJourneyMetrics(source) {
        const parseNumber = value => {
            const raw = String(value ?? '')
                .replace(/\u00a0/g, ' ')
                .trim();
            if (!raw) return null;

            const normalised = raw.includes('.')
                ? raw.replace(/,/g, '')
                : raw.replace(',', '.');
            const number = Number(normalised);
            return Number.isFinite(number) && number >= 0
                ? number
                : null;
        };

        const parseDistance = (
            value,
            allowBareNumber = true
        ) => {
            const direct = allowBareNumber
                ? parseNumber(value)
                : null;
            if (direct !== null) return direct;

            const raw = String(value ?? '')
                .replace(/\u00a0/g, ' ')
                .trim();
            const match = raw.match(
                /(\d+(?:[.,]\d+)?)\s*(km|kilomet(?:er|re)s?|m|met(?:er|re)s?)\b/i
            );
            if (!match) return null;

            const number = parseNumber(match[1]);
            if (number === null) return null;
            return /^k/i.test(match[2])
                ? number
                : number / 1000;
        };

        const parseEta = (
            value,
            allowBareNumber = true
        ) => {
            const direct = allowBareNumber
                ? parseNumber(value)
                : null;
            if (direct !== null) return direct;

            const raw = String(value ?? '')
                .replace(/\u00a0/g, ' ')
                .trim()
                .toLowerCase();
            if (!raw) return null;

            const clock = raw.match(
                /(?:^|\D)(\d{1,3}):([0-5]\d)(?::([0-5]\d))?(?:\D|$)/
            );
            if (clock) {
                if (clock[3] !== undefined) {
                    return (
                        Number(clock[1]) * 3600 +
                        Number(clock[2]) * 60 +
                        Number(clock[3])
                    );
                }
                return Number(clock[1]) * 60 + Number(clock[2]);
            }

            let total = 0;
            let matched = false;
            for (const part of raw.matchAll(
                /(\d+(?:[.,]\d+)?)\s*(hours?|hrs?|hr|h|minutes?|mins?|min|seconds?|secs?|sec|s)\b/g
            )) {
                const number = parseNumber(part[1]);
                if (number === null) continue;
                matched = true;
                const unit = part[2];
                if (/^h/.test(unit)) total += number * 3600;
                else if (/^m/.test(unit)) total += number * 60;
                else total += number;
            }
            return matched ? total : null;
        };

        const row = source?.closest?.('tr') ||
            (source?.matches?.('tr') ? source : null);
        const distanceNodes = [];
        const etaNodes = [];
        const textNodes = [];
        const addNode = (collection, node) => {
            if (node && !collection.includes(node)) {
                collection.push(node);
            }
        };

        [source, row].forEach(node => {
            addNode(distanceNodes, node);
            addNode(etaNodes, node);
            addNode(textNodes, node);
        });

        const collect = (root, selectors, collection) => {
            if (!root?.querySelectorAll) return;
            selectors.forEach(selector => {
                try {
                    Array.from(root.querySelectorAll(selector))
                        .slice(0, 30)
                        .forEach(node => addNode(collection, node));
                } catch (_error) {}
            });
        };

        [source, row].forEach(root => {
            collect(
                root,
                [
                    '[data-distance-km]',
                    '[data-route-distance-km]',
                    '[data-route-distance]',
                    '[data-distance]',
                    '[distance]'
                ],
                distanceNodes
            );
            collect(
                root,
                [
                    '[data-eta-seconds]',
                    '[data-arrival-seconds]',
                    '[data-duration-seconds]',
                    '[data-timevalue]',
                    '[timevalue]',
                    '[data-sortvalue]',
                    '[data-eta]'
                ],
                etaNodes
            );
            collect(
                root,
                [
                    '.vehicle_distance',
                    '.vehicle-distance',
                    '[class*="distance"]',
                    '.vehicle_arrival_time',
                    '.vehicle-arrival-time',
                    '.vehicle_eta',
                    '.vehicle-eta',
                    '[class*="arrival"]',
                    '[class*="eta"]',
                    'td'
                ],
                textNodes
            );
        });

        const readAttribute = (nodes, names, parser) => {
            for (const node of nodes) {
                for (const name of names) {
                    const value = node?.getAttribute?.(name);
                    if (value === null || value === undefined || value === '') {
                        continue;
                    }
                    const parsed = parser(value);
                    if (parsed !== null) return parsed;
                }
            }
            return null;
        };

        let distanceKm = readAttribute(
            distanceNodes,
            [
                'data-distance-km',
                'data-route-distance-km',
                'data-route-distance',
                'data-distance',
                'distance'
            ],
            parseDistance
        );
        let etaSeconds = readAttribute(
            etaNodes,
            [
                'data-eta-seconds',
                'data-arrival-seconds',
                'data-duration-seconds',
                'data-timevalue',
                'timevalue',
                'data-sortvalue',
                'data-eta'
            ],
            parseEta
        );

        const readText = (
            parser,
            semanticSelector
        ) => {
            for (const node of textNodes) {
                const allowBareNumber =
                    !!semanticSelector &&
                    node?.matches?.(semanticSelector) === true;
                for (const value of [
                    node?.getAttribute?.('aria-label'),
                    node?.getAttribute?.('title'),
                    node?.getAttribute?.('data-content'),
                    node?.textContent
                ]) {
                    const parsed = parser(
                        value,
                        allowBareNumber
                    );
                    if (parsed !== null) return parsed;
                }
            }
            return null;
        };

        if (distanceKm === null) {
            distanceKm = readText(
                parseDistance,
                '.vehicle_distance, .vehicle-distance, [class*="distance"]'
            );
        }
        if (etaSeconds === null) {
            etaSeconds = readText(
                parseEta,
                '.vehicle_arrival_time, .vehicle-arrival-time, .vehicle_eta, .vehicle-eta, [class*="arrival"], [class*="eta"]'
            );
        }

        if (distanceKm !== null && distanceKm > 100000) {
            distanceKm = null;
        }
        if (etaSeconds !== null && etaSeconds > 604800) {
            etaSeconds = null;
        }

        return {
            estimatedDistanceKm:
                distanceKm === null
                    ? null
                    : Math.round(distanceKm * 1000) / 1000,
            estimatedEtaSeconds:
                etaSeconds === null
                    ? null
                    : Math.round(etaSeconds)
        };
    }

    function getMissionLoggerSelectedUnits() {
        let selected = [];

        try {
            selected = getVehicleCheckboxSnapshot(true)
                .filter(checkbox => checkbox.checked)
                .slice(0, 500);
        } catch (_error) {}

        return selected.map(checkbox => {
            const row = checkbox.closest?.('tr');
            const journeyMetrics =
                readMissionLoggerUnitJourneyMetrics(checkbox);
            const stationLink = row?.querySelector?.(
                'a[href*="/buildings/"]'
            );
            const stationMatch = String(
                stationLink?.getAttribute?.('href') || ''
            ).match(/\/buildings\/(\d+)/i);
            const typeIds = getVehicleTypeIdentifiers(
                checkbox
            );
            const typeName = trimMissionLoggerText(
                checkbox.getAttribute?.(
                    'vehicle_type_caption'
                ) ||
                row?.getAttribute?.(
                    'vehicle_type_caption'
                ) ||
                row?.querySelector?.(
                    'td[vehicle_type_id], td[data-vehicle-type-id]'
                )?.textContent ||
                '',
                160
            );

            return {
                vehicleId: getMissionVehicleId(checkbox),
                vehicleTypeId: typeIds[0] || '',
                vehicleName: trimMissionLoggerText(
                    getVehicleDebugName(checkbox),
                    180
                ),
                vehicleTypeName: typeName,
                stationId: stationMatch?.[1] || '',
                stationName: trimMissionLoggerText(
                    stationLink?.textContent || '',
                    180
                ),
                status: trimMissionLoggerText(
                    checkbox.getAttribute?.('status') ||
                    row?.getAttribute?.('status') ||
                    row?.querySelector?.(
                        '.vehicle_status, [data-status]'
                    )?.textContent ||
                    '',
                    80
                ),
                estimatedDistanceKm:
                    journeyMetrics.estimatedDistanceKm,
                estimatedEtaSeconds:
                    journeyMetrics.estimatedEtaSeconds
            };
        });
    }

    function createMissionLoggerEvent(
        eventType,
        options = {}
    ) {
        const identity = readMissionLoggerIdentity();
        if (!identity) return null;

        const missionSnapshot =
            getMissionLoggerMissionSnapshot();
        const generator = getMissionLoggerGenerator();
        const livePatientCount = (() => {
            try {
                return Math.max(0, findPatientCount(true));
            } catch (_error) {
                return 0;
            }
        })();
        const patientCount = Math.max(
            livePatientCount,
            Number(missionSnapshot.patientCount || 0)
        );
        const missionId =
            getCurrentMissionIdForQueueRestart();
        const missionName = getCurrentMissionName();
        const capturedAt = new Date().toISOString();
        const normalisedEventType = trimMissionLoggerText(
            eventType,
            60
        );
        const eventUnits = options.includeUnits === false
            ? []
            : Array.isArray(options.units)
                ? options.units
                : getMissionLoggerSelectedUnits();
        const missionRegistry =
            readMissionLoggerMissionRegistry();
        const previousMission = missionRegistry[
            createMissionLoggerRegistryKey(
                identity.playerId,
                missionId
            )
        ] || {};
        const eventFirstObservedAt =
            normalisedEventType === 'mission-observed'
                ? earlierMissionLoggerIso(
                    previousMission.firstObservedAt,
                    capturedAt
                )
                : previousMission.firstObservedAt || '';
        const eventFirstUnitSentAt =
            normalisedEventType === 'dispatch'
                ? earlierMissionLoggerIso(
                    previousMission.firstUnitSentAt,
                    capturedAt
                )
                : previousMission.firstUnitSentAt || '';
        const eventDispatchCount = Math.max(
            0,
            Number(previousMission.dispatchCount || 0) +
                (normalisedEventType === 'dispatch' ? 1 : 0)
        );
        const eventUnitCount = Math.max(
            0,
            Number(previousMission.unitCount || 0) +
                (normalisedEventType === 'dispatch'
                    ? eventUnits.length
                    : 0)
        );

        return {
            schemaVersion:
                MF_MISSION_LOGGER_SCHEMA_VERSION,
            eventId: createMissionLoggerId('event'),
            eventType: normalisedEventType,
            capturedAt,
            playerId: identity.playerId,
            deviceId: identity.deviceId,
            missionId: String(missionId || ''),
            missionDefinitionId:
                getMissionLoggerDefinitionId() ||
                missionSnapshot.missionDefinitionId,
            missionName: trimMissionLoggerText(
                missionName,
                240
            ),
            missionUrl: missionId
                ? `${window.location.origin}/missions/${missionId}`
                : '',
            ownership: getMissionLoggerOwnership(),
            generatorStationId: generator.stationId,
            generatorStationName: generator.stationName,
            dispatchMode: trimMissionLoggerText(
                options.dispatchMode || '',
                80
            ),
            shared: options.shared === true,
            advertisedCredits: Math.max(
                0,
                Number.isFinite(Number(options.credits))
                    ? Number(options.credits)
                    : getMissionCredits()
            ),
            actualCredits:
                options.actualCredits !== null &&
                options.actualCredits !== undefined &&
                options.actualCredits !== '' &&
                Number.isFinite(Number(options.actualCredits)) &&
                Number(options.actualCredits) >= 0
                    ? Number(options.actualCredits)
                    : null,
            patientCount,
            prisonerCount:
                missionSnapshot.prisonerCount,
            transportCount: null,
            requirements: getMissionLoggerRequirements(),
            units: eventUnits,
            metadata: {
                ...(
                    options.metadata &&
                    typeof options.metadata === 'object'
                        ? options.metadata
                        : {}
                ),
                source: 'missionchief-command-nexus',
                ready:
                    options.ready === undefined
                        ? vehicleLoadState.ready === true
                        : options.ready === true,
                reason: trimMissionLoggerText(
                    options.reason || '',
                    300
                ),
                autoMode:
                    options.autoMode === true,
                dispatchFingerprint:
                    trimMissionLoggerText(
                        options.dispatchFingerprint || '',
                        4000
                    ),
                generatorSource:
                    generator.source || '',
                missionSnapshotSource:
                    missionSnapshot.source || '',
                possiblePatientCount: Math.max(
                    0,
                    Number(
                        missionSnapshot.possiblePatientCount || 0
                    )
                ),
                possiblePrisonerCount:
                    missionSnapshot.possiblePrisonerCount,
                firstObservedAt:
                    eventFirstObservedAt,
                firstUnitSentAt:
                    eventFirstUnitSentAt,
                dispatchCount:
                    eventDispatchCount,
                unitCount:
                    eventUnitCount,
                missionFinderVersion:
                    MF_MISSION_LOGGER_MISSION_FINDER_VERSION
            }
        };
    }

    function createMissionLoggerRegistryKey(
        playerId,
        missionId
    ) {
        const player = String(playerId || '').trim();
        const mission = String(missionId || '').trim();
        return player && mission
            ? `${player}|${mission}`
            : '';
    }

    function readMissionLoggerMissionRegistry() {
        try {
            const parsed = JSON.parse(
                localStorage.getItem(
                    MF_MISSION_LOGGER_MISSION_REGISTRY_KEY
                ) || '{}'
            );
            return parsed && typeof parsed === 'object'
                ? parsed
                : {};
        } catch (_error) {
            return {};
        }
    }

    function writeMissionLoggerMissionRegistry(registry) {
        const cutoff =
            Date.now() -
            MF_MISSION_LOGGER_MISSION_REGISTRY_DAYS *
                24 * 60 * 60 * 1000;
        const entries = Object.entries(
            registry && typeof registry === 'object'
                ? registry
                : {}
        ).filter(([, record]) => {
            return !!(
                record &&
                typeof record === 'object' &&
                Number(record.lastSeenAt || 0) >= cutoff
            );
        }).sort((left, right) => {
            return Number(right[1].lastSeenAt || 0) -
                Number(left[1].lastSeenAt || 0);
        }).slice(0, MF_MISSION_LOGGER_MAX_MISSION_REGISTRY);

        const bounded = Object.fromEntries(entries);
        try {
            localStorage.setItem(
                MF_MISSION_LOGGER_MISSION_REGISTRY_KEY,
                JSON.stringify(bounded)
            );
        } catch (_error) {
            try {
                localStorage.setItem(
                    MF_MISSION_LOGGER_MISSION_REGISTRY_KEY,
                    JSON.stringify(
                        Object.fromEntries(entries.slice(0, 500))
                    )
                );
            } catch (_ignored) {}
        }
    }

    function earlierMissionLoggerIso(left, right) {
        const leftTime = Date.parse(String(left || ''));
        const rightTime = Date.parse(String(right || ''));
        if (!Number.isFinite(leftTime)) {
            return Number.isFinite(rightTime)
                ? new Date(rightTime).toISOString()
                : '';
        }
        if (!Number.isFinite(rightTime)) {
            return new Date(leftTime).toISOString();
        }
        return new Date(Math.min(leftTime, rightTime))
            .toISOString();
    }

    function rememberMissionLoggerEvent(event) {
        const playerId = String(event?.playerId || '').trim();
        const missionId = String(event?.missionId || '').trim();
        const key = createMissionLoggerRegistryKey(
            playerId,
            missionId
        );
        if (!key) return;

        const registry = readMissionLoggerMissionRegistry();
        const previous =
            registry[key] && typeof registry[key] === 'object'
                ? registry[key]
                : {};
        const capturedAt = Number.isFinite(
            Date.parse(String(event.capturedAt || ''))
        )
            ? new Date(event.capturedAt).toISOString()
            : new Date().toISOString();
        const metadata =
            event.metadata && typeof event.metadata === 'object'
                ? event.metadata
                : {};
        const eventType = String(
            event.eventType || ''
        ).toLowerCase();
        const units = Array.isArray(event.units)
            ? event.units
            : [];
        const next = {
            ...previous,
            playerId,
            missionId,
            missionDefinitionId: String(
                event.missionDefinitionId ||
                previous.missionDefinitionId ||
                ''
            ),
            missionName: trimMissionLoggerText(
                event.missionName || previous.missionName || '',
                240
            ),
            missionUrl: trimMissionLoggerText(
                event.missionUrl || previous.missionUrl || '',
                500
            ),
            ownership: trimMissionLoggerText(
                event.ownership || previous.ownership || '',
                40
            ),
            generatorStationId: String(
                event.generatorStationId ||
                previous.generatorStationId ||
                ''
            ),
            generatorStationName: trimMissionLoggerText(
                event.generatorStationName ||
                previous.generatorStationName ||
                '',
                160
            ),
            advertisedCredits: Math.max(
                0,
                Number(previous.advertisedCredits || 0),
                Number(event.advertisedCredits || 0)
            ),
            patientCount: Math.max(
                0,
                Number(previous.patientCount || 0),
                Number(event.patientCount || 0)
            ),
            prisonerCount:
                event.prisonerCount === null ||
                event.prisonerCount === undefined
                    ? previous.prisonerCount ?? null
                    : Math.max(
                        0,
                        Number(previous.prisonerCount || 0),
                        Number(event.prisonerCount || 0)
                    ),
            firstObservedAt: earlierMissionLoggerIso(
                previous.firstObservedAt,
                metadata.firstObservedAt ||
                    (eventType === 'mission-observed'
                        ? capturedAt
                        : '')
            ),
            firstUnitSentAt: earlierMissionLoggerIso(
                previous.firstUnitSentAt,
                metadata.firstUnitSentAt ||
                    (eventType === 'dispatch'
                        ? capturedAt
                        : '')
            ),
            completedAt: earlierMissionLoggerIso(
                previous.completedAt,
                metadata.completedAt ||
                    (eventType === 'mission-completed'
                        ? capturedAt
                        : '')
            ),
            dispatchCount: Number(previous.dispatchCount || 0),
            unitCount: Number(previous.unitCount || 0),
            firstDispatchMode:
                previous.firstDispatchMode ||
                (eventType === 'dispatch'
                    ? trimMissionLoggerText(
                        event.dispatchMode || '',
                        80
                    )
                    : ''),
            lastSeenAt: Date.now()
        };

        if (eventType === 'dispatch') {
            next.dispatchCount = Math.max(
                next.dispatchCount + 1,
                Number(metadata.dispatchCount || 0)
            );
            next.unitCount = Math.max(
                next.unitCount + units.length,
                Number(metadata.unitCount || 0)
            );
        } else {
            next.dispatchCount = Math.max(
                next.dispatchCount,
                Number(metadata.dispatchCount || 0)
            );
            next.unitCount = Math.max(
                next.unitCount,
                Number(metadata.unitCount || 0)
            );
        }

        if (
            event.actualCredits !== null &&
            event.actualCredits !== undefined &&
            event.actualCredits !== '' &&
            Number.isFinite(Number(event.actualCredits))
        ) {
            next.actualCredits = Math.max(
                0,
                Number(previous.actualCredits || 0),
                Number(event.actualCredits)
            );
            next.actualCreditsSource = trimMissionLoggerText(
                metadata.actualCreditsSource ||
                previous.actualCreditsSource ||
                '',
                80
            );

            const transactionId = trimMissionLoggerText(
                metadata.creditTransactionId || '',
                180
            );
            if (transactionId) {
                next.actualCreditsTransactionId = transactionId;
                next.actualCreditsCapturedAt =
                    metadata.creditTransactionAt ||
                    capturedAt;
            }
        }

        registry[key] = next;
        writeMissionLoggerMissionRegistry(registry);
    }

    function parseMissionLoggerCreditAmount(value) {
        const text = String(value || '')
            .replace(/\u00a0/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();
        if (!text) return null;

        const match = text.match(/\d[\d\s,.]*/);
        if (!match) return null;

        const digits = match[0].replace(/[^\d]/g, '');
        const amount = Number(digits);
        if (!digits || !Number.isFinite(amount)) return null;

        const negative =
            /[-−–]\s*\d/.test(text) ||
            /^\s*\([^)]*\d[^)]*\)\s*$/.test(text);
        return negative ? -amount : amount;
    }

    function parseMissionLoggerCreditTimestamp(value) {
        const raw = String(value || '').trim();
        if (!raw) return '';

        if (/^\d{9,17}(?:\.\d+)?$/.test(raw)) {
            let timestamp = Number(raw);
            while (timestamp > 100000000000000) {
                timestamp /= 1000;
            }
            if (timestamp < 100000000000) {
                timestamp *= 1000;
            }
            const numericDate = new Date(timestamp);
            if (Number.isFinite(numericDate.getTime())) {
                return numericDate.toISOString();
            }
        }

        const parsed = Date.parse(raw);
        return Number.isFinite(parsed)
            ? new Date(parsed).toISOString()
            : '';
    }

    function hashMissionLoggerCreditValue(value) {
        const text = String(value || '');
        let hash = 2166136261;

        for (let index = 0; index < text.length; index += 1) {
            hash ^= text.charCodeAt(index);
            hash = Math.imul(hash, 16777619);
        }

        return (hash >>> 0).toString(36);
    }

    function normaliseMissionLoggerCreditDescription(value) {
        return String(value || '')
            .normalize('NFKC')
            .replace(/^\s*\[\s*alliance\s*\]\s*/i, '')
            .replace(/\s*\(\s*fire alarm system\s*\)\s*/gi, ' ')
            .replace(/\s*-\s*false alarm\s*$/i, '')
            .replace(/[’‘]/g, "'")
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();
    }

    function parseMissionLoggerCreditTransactionsFromDocument(doc) {
        if (!doc) return [];

        // MissionChief's native Credits list exposes one transaction per row:
        // signed amount, description and a machine-readable data-logged-at
        // timestamp. Keep the parser local to the signed-in page and return
        // only bounded fields needed for mission reconciliation.
        const rows = Array.from(
            doc.querySelectorAll?.('table tbody tr') || []
        );

        return rows.map(row => {
            const cells = Array.from(
                row.querySelectorAll?.('td, th') || []
            );
            if (cells.length < 3) return null;

            const amount = parseMissionLoggerCreditAmount(
                cells[0]?.textContent || ''
            );
            const description = trimMissionLoggerText(
                cells[1]?.textContent || '',
                240
            );
            const missionName = trimMissionLoggerText(
                description
                    .replace(
                        /^\s*\[\s*alliance\s*\]\s*/i,
                        ''
                    )
                    .replace(
                        /\s*\(\s*fire alarm system\s*\)\s*/gi,
                        ' '
                    )
                    .replace(
                        /\s*-\s*false alarm\s*$/i,
                        ''
                    ),
                240
            );
            const loggedElement =
                cells[2]?.querySelector?.(
                    '[data-logged-at], time[datetime]'
                ) ||
                row.querySelector?.(
                    '[data-logged-at], time[datetime]'
                );
            const loggedAtRaw = [
                row.getAttribute?.('data-logged-at'),
                cells[2]?.getAttribute?.('data-logged-at'),
                loggedElement?.getAttribute?.('data-logged-at'),
                loggedElement?.getAttribute?.('datetime'),
                cells[2]?.textContent
            ].map(value => String(value || '').trim())
                .find(Boolean) || '';
            const transactionAt =
                parseMissionLoggerCreditTimestamp(loggedAtRaw);
            const missionElement =
                row.querySelector?.(
                    '[data-mission-id], a[href*="/missions/"], a[href*="/mission/"]'
                );
            const missionId = [
                row.getAttribute?.('data-mission-id'),
                cells[1]?.getAttribute?.('data-mission-id'),
                missionElement?.getAttribute?.('data-mission-id'),
                String(
                    missionElement?.getAttribute?.('href') || ''
                ).match(/\/missions?\/(\d+)/i)?.[1]
            ].map(value => String(value || '').trim())
                .find(value => /^\d+$/.test(value)) || '';
            const explicitTransactionId = [
                row.getAttribute?.('data-transaction-id'),
                row.getAttribute?.('data-credit-id'),
                row.getAttribute?.('data-entry-id'),
                cells[0]?.getAttribute?.('data-transaction-id')
            ].map(value => trimMissionLoggerText(value, 180))
                .find(Boolean) || '';

            if (
                amount === null ||
                !description ||
                !transactionAt
            ) {
                return null;
            }

            const transactionId =
                explicitTransactionId ||
                `credit-${hashMissionLoggerCreditValue([
                    transactionAt,
                    amount,
                    description,
                    missionId
                ].join('|'))}`;

            return {
                transactionId,
                amount,
                description,
                missionName,
                normalisedDescription:
                    normaliseMissionLoggerCreditDescription(
                        description
                    ),
                transactionAt,
                missionId,
                sourcePath: '/credits'
            };
        }).filter(Boolean);
    }

    function missionLoggerRecordHasActualCredits(record) {
        return !!(
            record &&
            Number.isFinite(Number(record.actualCredits)) &&
            Number(record.actualCredits) > 0
        );
    }

    function getMissionLoggerOfflineCreditCandidates(
        registry = readMissionLoggerMissionRegistry(),
        identity = readMissionLoggerIdentity(),
        maxAgeMs = Number.POSITIVE_INFINITY
    ) {
        if (!identity) return [];

        return Object.entries(
            registry && typeof registry === 'object'
                ? registry
                : {}
        ).filter(([, record]) => {
            const firstUnitSentAt = Date.parse(
                String(record?.firstUnitSentAt || '')
            );
            const withinAge =
                !Number.isFinite(maxAgeMs) ||
                (
                    Number.isFinite(firstUnitSentAt) &&
                    Date.now() - firstUnitSentAt <= maxAgeMs
                );

            return !!(
                record &&
                String(record.playerId || '') ===
                    String(identity.playerId || '') &&
                Number.isFinite(firstUnitSentAt) &&
                !record.completedAt &&
                withinAge &&
                !missionLoggerRecordHasActualCredits(record)
            );
        });
    }

    function countPendingMissionLoggerCredits(
        registry = readMissionLoggerMissionRegistry(),
        identity = readMissionLoggerIdentity(),
        maxAgeMs = Number.POSITIVE_INFINITY
    ) {
        if (!identity) return 0;

        return Object.values(
            registry && typeof registry === 'object'
                ? registry
                : {}
        ).filter(record => {
            const completedAt = Date.parse(
                String(record?.completedAt || '')
            );
            const withinAge =
                !Number.isFinite(maxAgeMs) ||
                (
                    Number.isFinite(completedAt) &&
                    Date.now() - completedAt <= maxAgeMs
                );
            return !!(
                record &&
                String(record.playerId || '') ===
                    String(identity.playerId || '') &&
                record.firstUnitSentAt &&
                record.completedAt &&
                withinAge &&
                !missionLoggerRecordHasActualCredits(record)
            );
        }).length;
    }

    function findMissionLoggerCreditMatch(
        transaction,
        registry = readMissionLoggerMissionRegistry(),
        identity = readMissionLoggerIdentity(),
        options = {}
    ) {
        if (
            !transaction ||
            !identity ||
            !Number.isFinite(Number(transaction.amount)) ||
            Number(transaction.amount) <= 0
        ) {
            return null;
        }

        const records = Object.entries(
            registry && typeof registry === 'object'
                ? registry
                : {}
        );
        const transactionId = String(
            transaction.transactionId || ''
        );

        if (
            transactionId &&
            records.some(([, record]) => {
                return String(
                    record?.actualCreditsTransactionId || ''
                ) === transactionId;
            })
        ) {
            return null;
        }

        const completed = records.filter(([, record]) => {
            return !!(
                record &&
                String(record.playerId || '') ===
                    String(identity.playerId || '') &&
                record.firstUnitSentAt &&
                record.completedAt
            );
        });
        const pending = completed.filter(([, record]) => {
            return !missionLoggerRecordHasActualCredits(record);
        });

        const description =
            transaction.normalisedDescription ||
            normaliseMissionLoggerCreditDescription(
                transaction.description
            );

        const transactionTime = Date.parse(
            String(transaction.transactionAt || '')
        );

        const explicitMissionId = String(
            transaction.missionId || ''
        );
        if (explicitMissionId) {
            const exact = pending.find(([, record]) => {
                // A mission can also have patient/prisoner transactions. An
                // exposed mission ID is therefore authoritative only together
                // with the normalized mission-award title.
                return (
                    String(record.missionId || '') ===
                        explicitMissionId &&
                    description &&
                    normaliseMissionLoggerCreditDescription(
                        record.missionName
                    ) === description
                );
            });
            if (exact) {
                return {
                    key: exact[0],
                    record: exact[1],
                    strategy: 'mission-id',
                    distanceMs: 0
                };
            }

            if (
                options.allowOfflineRecovery === true &&
                Number.isFinite(transactionTime)
            ) {
                const offlineMatches =
                    getMissionLoggerOfflineCreditCandidates(
                        registry,
                        identity
                    ).filter(([, record]) => {
                        const firstUnitSentAt = Date.parse(
                            String(
                                record.firstUnitSentAt || ''
                            )
                        );

                        return (
                            String(record.missionId || '') ===
                                explicitMissionId &&
                            description &&
                            normaliseMissionLoggerCreditDescription(
                                record.missionName
                            ) === description &&
                            Number.isFinite(firstUnitSentAt) &&
                            transactionTime >=
                                firstUnitSentAt -
                                    MF_MISSION_LOGGER_CREDIT_MATCH_WINDOW_MS
                        );
                    });

                if (offlineMatches.length === 1) {
                    const firstUnitSentAt = Date.parse(
                        String(
                            offlineMatches[0][1]
                                .firstUnitSentAt || ''
                        )
                    );

                    return {
                        key: offlineMatches[0][0],
                        record: offlineMatches[0][1],
                        strategy: 'offline-mission-id',
                        distanceMs: Math.max(
                            0,
                            transactionTime - firstUnitSentAt
                        )
                    };
                }
            }
        }

        if (!Number.isFinite(transactionTime) || !description) {
            return null;
        }

        const titleAndTimeMatches = completed.map(([key, record]) => {
            const completedTime = Date.parse(
                String(record.completedAt || '')
            );
            const distanceMs = Number.isFinite(completedTime)
                ? Math.abs(transactionTime - completedTime)
                : Number.POSITIVE_INFINITY;

            return {
                key,
                record,
                distanceMs,
                title:
                    normaliseMissionLoggerCreditDescription(
                        record.missionName
                    )
            };
        }).filter(candidate => {
            return (
                candidate.title === description &&
                candidate.distanceMs <=
                    MF_MISSION_LOGGER_CREDIT_MATCH_WINDOW_MS
            );
        });

        if (titleAndTimeMatches.length !== 1) return null;
        if (
            missionLoggerRecordHasActualCredits(
                titleAndTimeMatches[0].record
            )
        ) {
            return null;
        }

        return {
            ...titleAndTimeMatches[0],
            strategy: 'unique-title-time'
        };
    }

    function recordMissionLoggerCreditTransaction(
        transaction,
        match
    ) {
        const identity = readMissionLoggerIdentity();
        const record = match?.record;
        if (!identity || !record || !transaction) return false;

        const amount = Number(transaction.amount);
        if (!Number.isFinite(amount) || amount <= 0) return false;

        const recoveredOffline =
            match.strategy === 'offline-mission-id' &&
            !record.completedAt;
        const completedAt =
            record.completedAt ||
            transaction.transactionAt ||
            new Date().toISOString();

        const event = {
            schemaVersion:
                MF_MISSION_LOGGER_SCHEMA_VERSION,
            eventId: createMissionLoggerId('event'),
            eventType: 'mission-credit',
            capturedAt:
                transaction.transactionAt ||
                new Date().toISOString(),
            playerId: identity.playerId,
            deviceId: identity.deviceId,
            missionId: String(record.missionId || ''),
            missionDefinitionId: String(
                record.missionDefinitionId || ''
            ),
            missionName: trimMissionLoggerText(
                transaction.missionName ||
                record.missionName ||
                transaction.description ||
                '',
                240
            ),
            missionUrl: trimMissionLoggerText(
                record.missionUrl ||
                `${window.location.origin}/missions/${record.missionId}`,
                500
            ),
            ownership: /^\s*\[\s*alliance\s*\]/i.test(
                transaction.description || ''
            )
                ? 'alliance'
                : trimMissionLoggerText(
                    record.ownership || 'own',
                    40
                ),
            generatorStationId: String(
                record.generatorStationId || ''
            ),
            generatorStationName: trimMissionLoggerText(
                record.generatorStationName || '',
                160
            ),
            dispatchMode: trimMissionLoggerText(
                record.firstDispatchMode || '',
                80
            ),
            shared: false,
            advertisedCredits: Math.max(
                0,
                Number(record.advertisedCredits || 0)
            ),
            actualCredits: amount,
            patientCount: Math.max(
                0,
                Number(record.patientCount || 0)
            ),
            prisonerCount:
                record.prisonerCount ?? null,
            transportCount: null,
            requirements: [],
            units: [],
            metadata: {
                source: 'missionchief-command-nexus',
                completionSource:
                    recoveredOffline
                        ? 'credit-ledger-offline-recovery'
                        : 'native-mission-finish',
                completionVerified: true,
                firstObservedAt:
                    record.firstObservedAt || '',
                firstUnitSentAt:
                    record.firstUnitSentAt || '',
                completedAt:
                    completedAt,
                dispatchCount: Math.max(
                    0,
                    Number(record.dispatchCount || 0)
                ),
                unitCount: Math.max(
                    0,
                    Number(record.unitCount || 0)
                ),
                actualCreditsSource:
                    'missionchief-credit-ledger',
                creditTransactionId: trimMissionLoggerText(
                    transaction.transactionId,
                    180
                ),
                creditTransactionAt:
                    transaction.transactionAt || '',
                creditTransactionDescription:
                    trimMissionLoggerText(
                        transaction.description,
                        240
                    ),
                creditTransactionSourcePath:
                    transaction.sourcePath || '/credits',
                creditMatchStrategy: match.strategy,
                creditMatchDistanceMs: Math.max(
                    0,
                    Number(match.distanceMs || 0)
                ),
                offlineRecovered: recoveredOffline,
                missionFinderVersion:
                    MF_MISSION_LOGGER_MISSION_FINDER_VERSION
            }
        };

        return queueMissionLoggerEvent(event);
    }

    async function fetchMissionLoggerCreditLedgerPage(page = 1) {
        const pageNumber = Math.max(
            1,
            parseInt(page, 10) || 1
        );
        const url = new URL(
            '/credits',
            window.location.origin
        );
        url.searchParams.set('page', String(pageNumber));

        const response = await window.fetch(url.href, {
            method: 'GET',
            credentials: 'same-origin',
            cache: 'no-store',
            headers: {
                Accept: 'text/html'
            }
        });

        if (!response.ok) {
            throw new Error(
                `MissionChief Credits returned HTTP ${response.status}.`
            );
        }

        const html = await response.text();
        const doc = new DOMParser().parseFromString(
            html,
            'text/html'
        );
        return parseMissionLoggerCreditTransactionsFromDocument(
            doc
        );
    }

    async function reconcileMissionLoggerCreditTransactions(
        options = {}
    ) {
        if (
            !MF_IS_TOP_WINDOW ||
            !mfMissionLoggerEnabled ||
            !readMissionLoggerIdentity() ||
            mfMissionLoggerCreditReconcileActive
        ) {
            return 0;
        }

        const now = Date.now();
        const identity = readMissionLoggerIdentity();
        const registry = readMissionLoggerMissionRegistry();
        const stateBefore = readMissionLoggerState();
        const lastCreditSuccessAt = Math.max(
            0,
            Number(
                stateBefore.lastCreditSuccessAt ||
                (
                    !stateBefore.lastCreditError
                        ? stateBefore.lastCreditCheckAt
                        : 0
                ) ||
                0
            )
        );
        const storedCatchupPage = Math.max(
            1,
            parseInt(
                stateBefore.offlineCreditCatchupNextPage,
                10
            ) || 1
        );
        const recoveryVersionCurrent =
            Number(
                stateBefore.offlineCreditRecoveryVersion || 0
            ) >= MF_MISSION_LOGGER_CREDIT_CATCHUP_VERSION;
        const recoveryStale =
            !lastCreditSuccessAt ||
            now - lastCreditSuccessAt >
                MF_MISSION_LOGGER_CREDIT_RECONCILE_INTERVAL_MS * 2;
        const allowOfflineRecovery =
            options.allowOfflineRecovery !== false;
        const recoveryRequired =
            allowOfflineRecovery &&
            (
                options.includeOlder === true ||
                !recoveryVersionCurrent ||
                recoveryStale ||
                storedCatchupPage > 1
            );
        const maxAgeMs = recoveryRequired
            ? Number.POSITIVE_INFINITY
            : MF_MISSION_LOGGER_CREDIT_AUTO_LOOKBACK_MS;
        const pendingCreditCount =
            countPendingMissionLoggerCredits(
                registry,
                identity,
                maxAgeMs
            );
        const offlineCandidates = allowOfflineRecovery
            ? getMissionLoggerOfflineCreditCandidates(
                registry,
                identity,
                maxAgeMs
            )
            : [];

        if (
            pendingCreditCount <= 0 &&
            offlineCandidates.length <= 0
        ) {
            if (
                !recoveryVersionCurrent ||
                storedCatchupPage > 1 ||
                recoveryRequired
            ) {
                writeMissionLoggerState({
                    lastCreditCheckAt: now,
                    lastCreditSuccessAt: now,
                    lastCreditError: '',
                    offlineCreditRecoveryVersion:
                        MF_MISSION_LOGGER_CREDIT_CATCHUP_VERSION,
                    offlineCreditCatchupNextPage: 1,
                    offlineCreditCatchupFloorAt: 0,
                    offlineCreditCatchupDeferred: false
                });
            }
            return 0;
        }

        if (
            options.force !== true &&
            now - mfMissionLoggerCreditLastFetchAt <
                MF_MISSION_LOGGER_CREDIT_MIN_FETCH_GAP_MS
        ) {
            return 0;
        }

        mfMissionLoggerCreditReconcileActive = true;
        mfMissionLoggerCreditLastFetchAt = now;
        let matched = 0;
        let recoveredOffline = 0;
        let nextPage = recoveryRequired
            ? storedCatchupPage
            : 1;
        let recoveryFloorAt = Math.max(
            0,
            Number(
                stateBefore.offlineCreditCatchupFloorAt || 0
            )
        );
        let recoveryComplete = !recoveryRequired;
        let scanDeferredForQueue = false;

        try {
            if (recoveryRequired && recoveryFloorAt <= 0) {
                const candidateTimes = Object.values(registry)
                    .filter(record => {
                        return !!(
                            record &&
                            String(record.playerId || '') ===
                                String(identity.playerId || '') &&
                            record.firstUnitSentAt &&
                            !missionLoggerRecordHasActualCredits(
                                record
                            )
                        );
                    })
                    .map(record => {
                        return Date.parse(
                            String(
                                record.completedAt ||
                                record.firstUnitSentAt ||
                                ''
                            )
                        );
                    })
                    .filter(Number.isFinite);
                const oldestCandidateAt = candidateTimes.length
                    ? Math.min(...candidateTimes)
                    : now;

                recoveryFloorAt = Math.max(
                    0,
                    (
                        recoveryVersionCurrent &&
                        lastCreditSuccessAt
                            ? lastCreditSuccessAt
                            : oldestCandidateAt
                    ) - MF_MISSION_LOGGER_CREDIT_MATCH_WINDOW_MS
                );
            }

            const requestedPages = parseInt(
                options.maxPages,
                10
            );
            const pageLimit = recoveryRequired
                ? MF_MISSION_LOGGER_CREDIT_CATCHUP_PAGES_PER_RUN
                : MF_MISSION_LOGGER_CREDIT_MAX_PAGES;
            const maxPages = Math.min(
                pageLimit,
                Math.max(
                    1,
                    Number.isFinite(requestedPages)
                        ? requestedPages
                        : recoveryRequired
                            ? pageLimit
                            : 1
                )
            );

            for (
                let pageOffset = 0;
                pageOffset < maxPages;
                pageOffset += 1
            ) {
                const page = nextPage;
                if (
                    readMissionLoggerQueue().length >
                        MF_MISSION_LOGGER_MAX_QUEUE_EVENTS -
                            MF_MISSION_LOGGER_CREDIT_PAGE_SIZE
                ) {
                    scanDeferredForQueue = true;
                    recoveryComplete = false;
                    break;
                }

                const transactions =
                    await fetchMissionLoggerCreditLedgerPage(page);
                const ordered = transactions.slice().sort(
                    (left, right) => {
                        return Date.parse(left.transactionAt) -
                            Date.parse(right.transactionAt);
                    }
                );

                for (const transaction of ordered) {
                    if (
                        readMissionLoggerQueue().length >=
                            MF_MISSION_LOGGER_MAX_QUEUE_EVENTS
                    ) {
                        scanDeferredForQueue = true;
                        recoveryComplete = false;
                        nextPage = page;
                        break;
                    }

                    const registry =
                        readMissionLoggerMissionRegistry();
                    const match = findMissionLoggerCreditMatch(
                        transaction,
                        registry,
                        readMissionLoggerIdentity(),
                        {
                            allowOfflineRecovery
                        }
                    );
                    if (
                        match &&
                        recordMissionLoggerCreditTransaction(
                            transaction,
                            match
                        )
                    ) {
                        matched += 1;
                        if (
                            match.strategy ===
                                'offline-mission-id'
                        ) {
                            recoveredOffline += 1;
                        }
                    }
                }

                if (scanDeferredForQueue) break;

                nextPage = page + 1;

                const transactionTimes = transactions
                    .map(transaction => {
                        return Date.parse(
                            String(
                                transaction.transactionAt || ''
                            )
                        );
                    })
                    .filter(Number.isFinite);
                const reachedRecoveryFloor =
                    recoveryRequired &&
                    recoveryFloorAt > 0 &&
                    transactionTimes.length > 0 &&
                    Math.min(...transactionTimes) <=
                        recoveryFloorAt;

                if (
                    transactions.length <
                        MF_MISSION_LOGGER_CREDIT_PAGE_SIZE ||
                    reachedRecoveryFloor
                ) {
                    recoveryComplete = true;
                    break;
                }
            }

            const state = readMissionLoggerState();
            const completedAt = Date.now();
            writeMissionLoggerState({
                lastCreditCheckAt: completedAt,
                lastCreditSuccessAt:
                    recoveryComplete
                        ? completedAt
                        : state.lastCreditSuccessAt,
                lastCreditMatchAt:
                    matched > 0
                        ? completedAt
                        : state.lastCreditMatchAt,
                lastCreditError: '',
                totalMatchedCreditEvents:
                    Math.max(
                        0,
                        Number(
                            state.totalMatchedCreditEvents || 0
                        )
                    ) + matched,
                lastOfflineCreditRecoveryAt:
                    recoveredOffline > 0
                        ? completedAt
                        : state.lastOfflineCreditRecoveryAt,
                totalOfflineRecoveredCreditEvents:
                    Math.max(
                        0,
                        Number(
                            state.totalOfflineRecoveredCreditEvents ||
                            0
                        )
                    ) + recoveredOffline,
                offlineCreditRecoveryVersion:
                    recoveryComplete
                        ? MF_MISSION_LOGGER_CREDIT_CATCHUP_VERSION
                        : state.offlineCreditRecoveryVersion,
                offlineCreditCatchupNextPage:
                    recoveryComplete ? 1 : nextPage,
                offlineCreditCatchupFloorAt:
                    recoveryComplete ? 0 : recoveryFloorAt,
                offlineCreditCatchupDeferred:
                    scanDeferredForQueue
            });
            return matched;
        } catch (error) {
            writeMissionLoggerState({
                lastCreditCheckAt: Date.now(),
                offlineCreditCatchupNextPage:
                    recoveryRequired ? nextPage : 1,
                offlineCreditCatchupFloorAt:
                    recoveryRequired ? recoveryFloorAt : 0,
                offlineCreditCatchupDeferred: false,
                lastCreditError: String(
                    error?.message ||
                    'MissionChief Credits could not be checked.'
                ).slice(0, 300)
            });
            return 0;
        } finally {
            mfMissionLoggerCreditReconcileActive = false;
        }
    }

    function scheduleMissionLoggerCreditReconciliation() {
        if (
            !MF_IS_TOP_WINDOW ||
            !mfMissionLoggerEnabled ||
            !readMissionLoggerIdentity()
        ) {
            return;
        }

        MF_MISSION_LOGGER_CREDIT_RETRY_DELAYS_MS
            .forEach(delay => {
                const timer = setTimeout(() => {
                    mfMissionLoggerCreditRetryTimers.delete(
                        timer
                    );
                    void reconcileMissionLoggerCreditTransactions();
                }, delay);
                mfMissionLoggerCreditRetryTimers.add(timer);
            });
    }

    function stopMissionLoggerCreditReconciliation() {
        if (mfMissionLoggerCreditInitialTimer) {
            clearTimeout(mfMissionLoggerCreditInitialTimer);
            mfMissionLoggerCreditInitialTimer = null;
        }
        if (mfMissionLoggerCreditTimer) {
            clearInterval(mfMissionLoggerCreditTimer);
            mfMissionLoggerCreditTimer = null;
        }
        mfMissionLoggerCreditRetryTimers.forEach(timer => {
            clearTimeout(timer);
        });
        mfMissionLoggerCreditRetryTimers.clear();
    }

    function startMissionLoggerCreditReconciliation() {
        if (!MF_IS_TOP_WINDOW) return;

        if (
            !mfMissionLoggerEnabled ||
            !readMissionLoggerIdentity()
        ) {
            stopMissionLoggerCreditReconciliation();
            return;
        }

        if (
            mfMissionLoggerCreditInitialTimer ||
            mfMissionLoggerCreditTimer
        ) {
            return;
        }

        mfMissionLoggerCreditInitialTimer = setTimeout(() => {
            mfMissionLoggerCreditInitialTimer = null;
            void reconcileMissionLoggerCreditTransactions({
                allowOfflineRecovery: true
            });

            if (
                !mfMissionLoggerEnabled ||
                mfMissionLoggerCreditTimer
            ) {
                return;
            }

            mfMissionLoggerCreditTimer = setInterval(() => {
                void reconcileMissionLoggerCreditTransactions({
                    allowOfflineRecovery: true
                });
            }, MF_MISSION_LOGGER_CREDIT_RECONCILE_INTERVAL_MS);
        }, 7000);
    }

    function getMissionLoggerNativeCompletionSnapshot(args) {
        const identity = readMissionLoggerIdentity();
        if (!identity) return null;

        const registry = readMissionLoggerMissionRegistry();
        const candidates = Array.from(args || []);
        const objects = [];
        const missionIds = [];
        const seen = new Set();
        const addMissionId = value => {
            const id = String(value ?? '').trim();
            if (/^\d+$/.test(id) && !missionIds.includes(id)) {
                missionIds.push(id);
            }
        };
        const addObject = value => {
            if (
                !value ||
                typeof value !== 'object' ||
                seen.has(value) ||
                objects.length >= 24
            ) {
                return;
            }
            seen.add(value);
            objects.push(value);
        };

        candidates.forEach((candidate, index) => {
            if (candidate && typeof candidate === 'object') {
                addObject(candidate);
            } else if (index === 0) {
                addMissionId(candidate);
            }
        });

        for (let index = 0; index < objects.length; index += 1) {
            const object = objects[index];
            [
                object.id,
                object.mission_id,
                object.missionId
            ].forEach(addMissionId);
            [
                object.mission,
                object.mission_data,
                object.missionData,
                object.data,
                object.detail
            ].forEach(addObject);
        }

        const missionId = missionIds.find(id => {
            return !!registry[
                createMissionLoggerRegistryKey(
                    identity.playerId,
                    id
                )
            ];
        });
        if (!missionId) return null;

        const key = createMissionLoggerRegistryKey(
            identity.playerId,
            missionId
        );
        const record = registry[key];
        if (!record?.firstUnitSentAt || record.completedAt) {
            return null;
        }

        const missionObject = objects.find(object => {
            return [
                object.id,
                object.mission_id,
                object.missionId
            ].some(value => String(value ?? '') === missionId);
        }) || objects[0] || {};
        const firstFiniteNumber = keys => {
            for (const object of objects) {
                for (const keyName of keys) {
                    const value = object?.[keyName];
                    if (
                        value !== null &&
                        value !== undefined &&
                        value !== '' &&
                        Number.isFinite(Number(value)) &&
                        Number(value) >= 0
                    ) {
                        return Number(value);
                    }
                }
            }
            return null;
        };
        const actualCredits = firstFiniteNumber([
            'actual_credits',
            'actualCredits',
            'earned_credits',
            'earnedCredits',
            'credited_amount',
            'creditedAmount'
        ]);
        const advertisedCredits = Math.max(
            0,
            Number(record.advertisedCredits || 0),
            Number(
                firstFiniteNumber([
                    'average_credits',
                    'advertised_credits',
                    'advertisedCredits'
                ]) || 0
            )
        );
        const nativeCompletedAt = [
            missionObject.completed_at,
            missionObject.completedAt,
            missionObject.finished_at,
            missionObject.finishedAt
        ].map(value => Date.parse(String(value || '')))
            .find(Number.isFinite);
        const completedAt = nativeCompletedAt
            ? new Date(nativeCompletedAt).toISOString()
            : new Date().toISOString();

        return {
            identity,
            record,
            missionId,
            missionObject,
            actualCredits,
            advertisedCredits,
            completedAt
        };
    }

    function recordMissionLoggerNativeCompletion(args) {
        if (!mfMissionLoggerEnabled) return false;
        const snapshot =
            getMissionLoggerNativeCompletionSnapshot(args);
        if (!snapshot) return false;

        const { identity, record } = snapshot;
        const event = {
            schemaVersion:
                MF_MISSION_LOGGER_SCHEMA_VERSION,
            eventId: createMissionLoggerId('event'),
            eventType: 'mission-completed',
            capturedAt: snapshot.completedAt,
            playerId: identity.playerId,
            deviceId: identity.deviceId,
            missionId: snapshot.missionId,
            missionDefinitionId: String(
                record.missionDefinitionId || ''
            ),
            missionName: trimMissionLoggerText(
                snapshot.missionObject.caption ||
                snapshot.missionObject.name ||
                record.missionName ||
                '',
                240
            ),
            missionUrl: trimMissionLoggerText(
                record.missionUrl ||
                `${window.location.origin}/missions/${snapshot.missionId}`,
                500
            ),
            ownership: trimMissionLoggerText(
                record.ownership || 'own',
                40
            ),
            generatorStationId: String(
                record.generatorStationId || ''
            ),
            generatorStationName: trimMissionLoggerText(
                record.generatorStationName || '',
                160
            ),
            dispatchMode: trimMissionLoggerText(
                record.firstDispatchMode || '',
                80
            ),
            shared: false,
            advertisedCredits:
                snapshot.advertisedCredits,
            actualCredits: snapshot.actualCredits,
            patientCount: Math.max(
                0,
                Number(record.patientCount || 0)
            ),
            prisonerCount:
                record.prisonerCount ?? null,
            transportCount: null,
            requirements: [],
            units: [],
            metadata: {
                source: 'missionchief-command-nexus',
                completionSource: 'native-mission-finish',
                completionVerified: true,
                firstObservedAt:
                    record.firstObservedAt || '',
                firstUnitSentAt:
                    record.firstUnitSentAt,
                completedAt: snapshot.completedAt,
                dispatchCount: Math.max(
                    0,
                    Number(record.dispatchCount || 0)
                ),
                unitCount: Math.max(
                    0,
                    Number(record.unitCount || 0)
                ),
                actualCreditsSource:
                    snapshot.actualCredits === null
                        ? 'pending-transaction-match'
                        : 'native-completion-payload',
                missionFinderVersion:
                    MF_MISSION_LOGGER_MISSION_FINDER_VERSION
            }
        };

        return queueMissionLoggerEvent(event);
    }

    function installMissionLoggerCompletionCapture() {
        if (!MF_IS_TOP_WINDOW) return false;
        if (
            mfMissionLoggerCompletionHook &&
            window.missionFinish ===
                mfMissionLoggerCompletionHook.wrapper
        ) {
            return true;
        }

        const original = window.missionFinish;
        if (typeof original !== 'function') return false;

        const wrapper = function (...args) {
            let captured = false;
            try {
                captured =
                    recordMissionLoggerNativeCompletion(args);
            } catch (_error) {}
            try {
                return original.apply(this, args);
            } finally {
                if (captured) {
                    scheduleMissionLoggerCreditReconciliation();
                }
            }
        };

        try {
            window.missionFinish = wrapper;
        } catch (_error) {
            return false;
        }
        if (window.missionFinish !== wrapper) return false;

        mfMissionLoggerCompletionHook = {
            original,
            wrapper
        };
        return true;
    }

    function removeMissionLoggerCompletionCapture() {
        const hook = mfMissionLoggerCompletionHook;
        if (!hook) return;
        try {
            if (window.missionFinish === hook.wrapper) {
                window.missionFinish = hook.original;
            }
        } catch (_error) {}
        mfMissionLoggerCompletionHook = null;
    }

    function recordMissionLoggerDispatchEvent(snapshot) {
        if (!snapshot) return false;
        return queueMissionLoggerEvent(snapshot);
    }

    function enrichMissionLoggerQueuedEventsFromCurrentMission() {
        const missionSnapshot =
            getMissionLoggerMissionSnapshot();
        const advertisedCredits = Math.max(
            0,
            parseInt(getMissionCredits(), 10) || 0,
            parseInt(
                missionSnapshot.advertisedCredits,
                10
            ) || 0
        );
        const missionId = String(
            getCurrentMissionIdForQueueRestart() || ''
        );

        if (!missionId) return false;

        const generator = getMissionLoggerGenerator();
        const requirements = getMissionLoggerRequirements();
        const missionDefinitionId =
            getMissionLoggerDefinitionId() ||
            missionSnapshot.missionDefinitionId;
        const missionName = trimMissionLoggerText(
            getCurrentMissionName(),
            240
        );
        const missionUrl =
            `${window.location.origin}/missions/${missionId}`;
        let livePatientCount = 0;
        try {
            livePatientCount = Math.max(
                0,
                findPatientCount(true)
            );
        } catch (_error) {}
        const patientCount = Math.max(
            livePatientCount,
            Number(missionSnapshot.patientCount || 0)
        );

        const queue = readMissionLoggerQueue();
        let changed = false;

        const enriched = queue.map(event => {
            if (
                String(event?.missionId || '') !== missionId
            ) {
                return event;
            }

            const next = { ...event };
            let eventChanged = false;
            const setIfMissing = (key, value) => {
                if (
                    next[key] ||
                    value === null ||
                    value === undefined ||
                    value === ''
                ) {
                    return;
                }
                next[key] = value;
                eventChanged = true;
            };

            if (
                advertisedCredits > 0 &&
                Number(next.advertisedCredits || 0) <= 0
            ) {
                next.advertisedCredits = advertisedCredits;
                eventChanged = true;
            }

            if (
                patientCount >
                Number(next.patientCount || 0)
            ) {
                next.patientCount = patientCount;
                eventChanged = true;
            }

            if (
                missionSnapshot.prisonerCount !== null &&
                Number(missionSnapshot.prisonerCount) >
                    Number(next.prisonerCount ?? -1)
            ) {
                next.prisonerCount =
                    Number(missionSnapshot.prisonerCount);
                eventChanged = true;
            }

            if (
                (!Array.isArray(next.requirements) ||
                    next.requirements.length === 0) &&
                requirements.length > 0
            ) {
                next.requirements = requirements;
                eventChanged = true;
            }

            setIfMissing('missionUrl', missionUrl);
            setIfMissing(
                'missionDefinitionId',
                missionDefinitionId
            );
            setIfMissing('missionName', missionName);
            setIfMissing(
                'generatorStationId',
                generator.stationId
            );
            setIfMissing(
                'generatorStationName',
                generator.stationName
            );

            const metadata = {
                ...(next.metadata &&
                typeof next.metadata === 'object'
                    ? next.metadata
                    : {})
            };
            const metadataUpdates = {
                generatorSource:
                    generator.source || '',
                missionSnapshotSource:
                    missionSnapshot.source || '',
                possiblePatientCount: Math.max(
                    0,
                    Number(
                        missionSnapshot.possiblePatientCount || 0
                    )
                ),
                possiblePrisonerCount:
                    missionSnapshot.possiblePrisonerCount
            };

            Object.entries(metadataUpdates)
                .forEach(([key, value]) => {
                    if (
                        metadata[key] ||
                        value === null ||
                        value === undefined ||
                        value === '' ||
                        value === 0
                    ) {
                        return;
                    }
                    metadata[key] = value;
                    eventChanged = true;
                });

            if (eventChanged) {
                metadata.enrichedAt =
                    new Date().toISOString();
                next.metadata = metadata;
                changed = true;
                return next;
            }

            return event;
        });

        if (changed) {
            writeMissionLoggerQueue(enriched);
        }

        return changed;
    }

    function readMissionLoggerObservedRegistry() {
        try {
            const parsed = JSON.parse(
                localStorage.getItem(
                    MF_MISSION_LOGGER_OBSERVED_KEY
                ) || '{}'
            );
            return parsed && typeof parsed === 'object'
                ? parsed
                : {};
        } catch (_error) {
            return {};
        }
    }

    function writeMissionLoggerObservedRegistry(registry) {
        const now = Date.now();
        const entries = Object.entries(
            registry && typeof registry === 'object'
                ? registry
                : {}
        )
            .filter(([, timestamp]) => {
                const value = Number(timestamp || 0);
                return (
                    value > 0 &&
                    now - value <=
                        MF_MISSION_LOGGER_OBSERVED_RETENTION_MS
                );
            })
            .sort((left, right) => {
                return Number(right[1]) - Number(left[1]);
            })
            .slice(0, MF_MISSION_LOGGER_OBSERVED_MAX_ENTRIES);

        localStorage.setItem(
            MF_MISSION_LOGGER_OBSERVED_KEY,
            JSON.stringify(Object.fromEntries(entries))
        );
    }

    function getMissionLoggerCurrentUserId() {
        for (const candidate of getMissionLoggerSameOriginWindows()) {
            for (const value of [
                candidate?.user_id,
                candidate?.current_user_id,
                candidate?.currentUser?.id,
                candidate?.user?.id
            ]) {
                const id = String(value ?? '').trim();
                if (/^\d+$/.test(id)) return id;
            }
        }

        try {
            const userLink = document.querySelector(
                '#navbar-main-user a[href*="/profile/"], ' +
                'a.navbar-user[href*="/profile/"]'
            );
            const match = String(
                userLink?.getAttribute?.('href') || ''
            ).match(/\/profile\/(\d+)/i);
            if (match) return match[1];
        } catch (_error) {}

        return '';
    }

    function getMissionLoggerMissionListRows(root) {
        const rows = [];
        const selector = [
            '#mission_list .missionSideBarEntry[id^="mission_"]',
            '#mission_list .missionSideBarEntry[mission_id]',
            '.missionSideBarEntry[id^="mission_"]',
            '.missionSideBarEntry[mission_id]'
        ].join(',');
        const add = row => {
            if (row && !rows.includes(row)) rows.push(row);
        };

        try {
            if (root?.matches?.(selector)) add(root);
        } catch (_error) {}
        try {
            Array.from(root?.querySelectorAll?.(selector) || [])
                .forEach(add);
        } catch (_error) {}

        return rows;
    }

    function getMissionLoggerMissionListRecord(
        suppliedMission,
        row
    ) {
        const missionId = (() => {
            for (const value of [
                suppliedMission?.id,
                suppliedMission?.mission_id,
                row?.getAttribute?.('mission_id'),
                row?.getAttribute?.('data-mission-id'),
                String(row?.id || '').match(/^mission_(\d+)$/)?.[1]
            ]) {
                const id = String(value ?? '').trim();
                if (/^\d+$/.test(id)) return id;
            }
            return '';
        })();
        if (!missionId) return null;

        let mission = suppliedMission &&
            typeof suppliedMission === 'object'
                ? suppliedMission
                : null;
        if (!mission) {
            for (const candidate of getMissionLoggerSameOriginWindows()) {
                try {
                    mission = getMissionLoggerCacheRecord(
                        candidate.missions_data,
                        missionId
                    );
                } catch (_error) {}
                if (mission) break;
            }
        }

        const currentUserId = getMissionLoggerCurrentUserId();
        const ownerId = (() => {
            for (const value of [
                mission?.user_id,
                mission?.userId,
                mission?.owner_id,
                mission?.ownerId,
                row?.getAttribute?.('user_id'),
                row?.getAttribute?.('data-user-id'),
                row?.getAttribute?.('owner_id'),
                row?.getAttribute?.('data-owner-id')
            ]) {
                const id = String(value ?? '').trim();
                if (/^\d+$/.test(id)) return id;
            }
            return '';
        })();

        if (
            !currentUserId ||
            !ownerId ||
            ownerId !== currentUserId
        ) {
            return null;
        }

        const numberOrNull = value => {
            if (value === null || value === undefined || value === '') {
                return null;
            }
            const number = Number(value);
            return Number.isFinite(number) && number >= 0
                ? number
                : null;
        };
        let sortable = {};
        try {
            sortable = JSON.parse(
                row?.getAttribute?.('data-sortable-by') ||
                row?.getAttribute?.('data-sortable_by') ||
                '{}'
            );
        } catch (_error) {}

        const missionName = trimMissionLoggerText(
            mission?.caption ||
            mission?.name ||
            mission?.title ||
            row?.querySelector?.(
                '.missionSideBarEntrySearchHelper, ' +
                '.mission_caption, a[href*="/missions/"]'
            )?.textContent ||
            '',
            240
        );
        const missionDefinitionId = (() => {
            for (const value of [
                mission?.mtid,
                mission?.mission_type_id,
                mission?.missionTypeId,
                row?.getAttribute?.('mission_type_id'),
                row?.getAttribute?.('data-mission-type-id')
            ]) {
                const id = String(value ?? '').trim();
                if (/^\d+$/.test(id)) return id;
            }
            return '';
        })();
        const generatorStationId = (() => {
            for (const value of [
                mission?.generator_building_id,
                mission?.generated_by_building_id,
                mission?.building_id
            ]) {
                const id = String(value ?? '').trim();
                if (/^\d+$/.test(id)) return id;
            }
            return '';
        })();
        const generatorStationName = trimMissionLoggerText(
            mission?.generator_building_name ||
            mission?.generated_by_name ||
            mission?.generated_by ||
            (
                generatorStationId
                    ? getMissionLoggerBuildingName(
                        generatorStationId
                    )
                    : ''
            ),
            180
        );
        const allianceId = String(
            mission?.alliance_id ??
            mission?.allianceId ??
            row?.getAttribute?.('alliance_id') ??
            row?.getAttribute?.('data-alliance-id') ??
            ''
        ).trim();

        return {
            missionId,
            missionDefinitionId,
            missionName,
            missionUrl:
                `${window.location.origin}/missions/${missionId}`,
            ownership: 'own',
            shared:
                allianceId !== '' &&
                allianceId !== '0' &&
                allianceId !== 'null',
            advertisedCredits: Math.max(
                0,
                numberOrNull(
                    mission?.average_credits ??
                    mission?.advertised_credits ??
                    sortable.average_credits
                ) || 0
            ),
            patientCount: Math.max(
                0,
                numberOrNull(
                    mission?.patients_count ??
                    sortable.patients_count?.[0] ??
                    sortable.patients_count
                ) || 0
            ),
            possiblePatientCount: Math.max(
                0,
                numberOrNull(
                    mission?.possible_patients_count ??
                    sortable.patients_count?.[1]
                ) || 0
            ),
            prisonerCount: numberOrNull(
                mission?.prisoners_count ??
                sortable.prisoners_count?.[0] ??
                sortable.prisoners_count
            ),
            possiblePrisonerCount: numberOrNull(
                mission?.possible_prisoners_count ??
                sortable.prisoners_count?.[1]
            ),
            generatorStationId,
            generatorStationName,
            generatorSource:
                generatorStationId || generatorStationName
                    ? 'mission-marker'
                    : ''
        };
    }

    function createMissionLoggerGeneratedEvent(record) {
        const identity = readMissionLoggerIdentity();
        if (!identity || !record?.missionId) return null;

        const capturedAt = new Date().toISOString();
        const missionRegistry = readMissionLoggerMissionRegistry();
        const previousMission = missionRegistry[
            createMissionLoggerRegistryKey(
                identity.playerId,
                record.missionId
            )
        ] || {};

        return {
            schemaVersion:
                MF_MISSION_LOGGER_SCHEMA_VERSION,
            eventId: createMissionLoggerId('event'),
            eventType: 'mission-observed',
            capturedAt,
            playerId: identity.playerId,
            deviceId: identity.deviceId,
            missionId: record.missionId,
            missionDefinitionId:
                record.missionDefinitionId || '',
            missionName: record.missionName || '',
            missionUrl: record.missionUrl || '',
            ownership: 'own',
            generatorStationId:
                record.generatorStationId || '',
            generatorStationName:
                record.generatorStationName || '',
            dispatchMode: '',
            shared: record.shared === true,
            advertisedCredits: Math.max(
                0,
                Number(record.advertisedCredits || 0)
            ),
            actualCredits: null,
            patientCount: Math.max(
                0,
                Number(record.patientCount || 0)
            ),
            prisonerCount:
                record.prisonerCount,
            transportCount: null,
            requirements: [],
            units: [],
            metadata: {
                source: 'missionchief-command-nexus',
                observationSource:
                    'mission-list-generated',
                ready: false,
                reason: '',
                autoMode: false,
                dispatchFingerprint: '',
                generatorSource:
                    record.generatorSource || '',
                missionSnapshotSource:
                    'mission-list-generated',
                possiblePatientCount: Math.max(
                    0,
                    Number(
                        record.possiblePatientCount || 0
                    )
                ),
                possiblePrisonerCount:
                    record.possiblePrisonerCount,
                firstObservedAt: earlierMissionLoggerIso(
                    previousMission.firstObservedAt,
                    capturedAt
                ),
                firstUnitSentAt:
                    previousMission.firstUnitSentAt || '',
                dispatchCount: Math.max(
                    0,
                    Number(previousMission.dispatchCount || 0)
                ),
                unitCount: Math.max(
                    0,
                    Number(previousMission.unitCount || 0)
                ),
                missionFinderVersion:
                    MF_MISSION_LOGGER_MISSION_FINDER_VERSION
            }
        };
    }

    function recordMissionLoggerGeneratedMission(
        suppliedMission,
        row,
        options = {}
    ) {
        if (
            !MF_IS_TOP_WINDOW ||
            !isMissionLoggerPassiveObserverOwner()
        ) return false;

        const record = getMissionLoggerMissionListRecord(
            suppliedMission,
            row
        );
        if (!record) return false;

        const now = Date.now();
        const registry = readMissionLoggerObservedRegistry();
        const existingAt = Number(
            registry[record.missionId] || 0
        );
        if (
            existingAt > 0 &&
            now - existingAt <=
                MF_MISSION_LOGGER_OBSERVED_RETENTION_MS
        ) {
            return false;
        }

        if (
            options.baselineOnly === true ||
            !mfMissionLoggerGenerationArmed ||
            !mfMissionLoggerEnabled ||
            !readMissionLoggerIdentity()
        ) {
            registry[record.missionId] = now;
            writeMissionLoggerObservedRegistry(registry);
            return false;
        }

        const queued = queueMissionLoggerEvent(
            createMissionLoggerGeneratedEvent(record)
        );
        if (!queued) return false;

        registry[record.missionId] = now;
        writeMissionLoggerObservedRegistry(registry);
        return true;
    }

    function scanMissionLoggerMissionList(
        root,
        baselineOnly
    ) {
        if (!isMissionLoggerPassiveObserverOwner()) {
            return 0;
        }
        let count = 0;
        getMissionLoggerMissionListRows(root).forEach(row => {
            if (
                recordMissionLoggerGeneratedMission(
                    null,
                    row,
                    { baselineOnly: baselineOnly === true }
                )
            ) {
                count += 1;
            }
        });
        return count;
    }

    function scheduleMissionLoggerGenerationArm() {
        if (!isMissionLoggerPassiveObserverOwner()) return;
        if (mfMissionLoggerGenerationArmed) return;
        if (mfMissionLoggerGenerationArmTimer) {
            clearTimeout(mfMissionLoggerGenerationArmTimer);
        }

        mfMissionLoggerGenerationArmTimer = setTimeout(
            () => {
                mfMissionLoggerGenerationArmTimer = null;
                scanMissionLoggerMissionList(
                    document,
                    true
                );
                mfMissionLoggerGenerationArmed = true;
            },
            MF_MISSION_LOGGER_GENERATION_ARM_DELAY_MS
        );
    }

    function installMissionLoggerMissionGenerationCapture() {
        if (
            !MF_IS_TOP_WINDOW ||
            !isMissionLoggerPassiveObserverOwner()
        ) return;

        if (!mfMissionLoggerGenerationInstalled) {
            mfMissionLoggerGenerationInstalled = true;
            scanMissionLoggerMissionList(document, true);
            scheduleMissionLoggerGenerationArm();
        }

        const nativeMissionMarkerAdd =
            window.missionMarkerAdd;
        if (
            typeof nativeMissionMarkerAdd !== 'function' ||
            nativeMissionMarkerAdd ===
                mfMissionLoggerMissionMarkerWrapper ||
            nativeMissionMarkerAdd
                .__mfMissionLoggerGenerationWrapper === true
        ) {
            return;
        }

        const wrapper = function(...args) {
            const result = nativeMissionMarkerAdd.apply(
                this,
                args
            );
            try {
                recordMissionLoggerGeneratedMission(
                    args[0],
                    null,
                    {
                        baselineOnly:
                            !mfMissionLoggerGenerationArmed
                    }
                );
            } catch (_error) {}
            return result;
        };
        try {
            Object.defineProperty(
                wrapper,
                '__mfMissionLoggerGenerationWrapper',
                { value: true }
            );
        } catch (_error) {}

        mfMissionLoggerMissionMarkerWrapper = wrapper;
        window.missionMarkerAdd = wrapper;
    }

    function observeMissionLoggerMissionListMutations(records) {
        if (
            !MF_IS_TOP_WINDOW ||
            !isMissionLoggerPassiveObserverOwner()
        ) return;

        installMissionLoggerMissionGenerationCapture();
        let sawMissionRows = false;
        (records || []).forEach(record => {
            Array.from(record?.addedNodes || [])
                .forEach(node => {
                    const rows =
                        getMissionLoggerMissionListRows(node);
                    if (rows.length === 0) return;
                    sawMissionRows = true;
                    rows.forEach(row => {
                        recordMissionLoggerGeneratedMission(
                            null,
                            row,
                            {
                                baselineOnly:
                                    !mfMissionLoggerGenerationArmed
                            }
                        );
                    });
                });
        });

        if (
            sawMissionRows &&
            !mfMissionLoggerGenerationArmed
        ) {
            scheduleMissionLoggerGenerationArm();
        }
    }

    function recordMissionLoggerObservedEvent() {
        if (
            !mfMissionLoggerEnabled ||
            !isMissionLoggerPassiveObserverOwner() ||
            !readMissionLoggerIdentity() ||
            !isMissionPage()
        ) {
            return false;
        }

        const missionId =
            getCurrentMissionIdForQueueRestart();
        if (!missionId) return false;

        const now = Date.now();
        const registry = readMissionLoggerObservedRegistry();
        const key = String(missionId);

        if (
            now - Number(registry[key] || 0) <=
            MF_MISSION_LOGGER_OBSERVED_RETENTION_MS
        ) {
            return false;
        }

        const queued = queueMissionLoggerEvent(
            createMissionLoggerEvent(
                'mission-observed',
                { includeUnits: false }
            )
        );
        if (!queued) return false;

        registry[key] = now;
        writeMissionLoggerObservedRegistry(registry);
        return true;
    }

    function getMissionLoggerDispatchControl(target) {
        const element = target?.closest?.(
            'a.alert_next, a.alert_next_alliance, a#mission_alarm_btn, button#mission_alarm_btn'
        );

        if (!element || !isMissionPage()) return null;
        if (element.id === 'mission_next_mission_btn') {
            return null;
        }
        if (
            element.hasAttribute('disabled') ||
            element.getAttribute('aria-disabled') === 'true' ||
            element.classList.contains('disabled')
        ) {
            return null;
        }

        const text = trimMissionLoggerText(
            `${element.textContent || ''} ${element.getAttribute('title') || ''}`,
            180
        ).toLowerCase();

        if (
            element.classList.contains('alert_next') ||
            element.classList.contains('alert_next_alliance') ||
            /dispatch|alarm/.test(text)
        ) {
            return element;
        }

        return null;
    }

    function createMissionLoggerDispatchFingerprint(
        missionId,
        dispatchMode,
        units
    ) {
        const selectedIds = (
            Array.isArray(units) ? units : []
        ).map(unit => {
            return trimMissionLoggerText(
                unit?.vehicleId ||
                unit?.vehicleName ||
                '',
                180
            );
        }).filter(Boolean).sort();

        return JSON.stringify([
            String(missionId || ''),
            trimMissionLoggerText(dispatchMode, 80),
            selectedIds
        ]);
    }

    function isDuplicateMissionLoggerDispatch(
        fingerprint,
        timestamp = Date.now()
    ) {
        let storedFingerprint =
            mfMissionLoggerLastDispatchFingerprint;
        let storedAt =
            mfMissionLoggerLastDispatchAt;

        try {
            const stored = JSON.parse(
                localStorage.getItem(
                    MF_MISSION_LOGGER_LAST_DISPATCH_KEY
                ) || 'null'
            );
            if (
                stored &&
                typeof stored === 'object' &&
                Number(stored.timestamp || 0) > storedAt
            ) {
                storedFingerprint = String(
                    stored.fingerprint || ''
                );
                storedAt = Number(stored.timestamp || 0);
            }
        } catch (_error) {}

        const duplicate =
            fingerprint === storedFingerprint &&
            timestamp - storedAt <
                MF_MISSION_LOGGER_DISPATCH_DEDUPE_MS;

        mfMissionLoggerLastDispatchFingerprint =
            fingerprint;
        mfMissionLoggerLastDispatchAt = timestamp;
        try {
            localStorage.setItem(
                MF_MISSION_LOGGER_LAST_DISPATCH_KEY,
                JSON.stringify({
                    fingerprint,
                    timestamp
                })
            );
        } catch (_error) {}

        return duplicate;
    }

    function resolveMissionLoggerDispatchOptions(
        control,
        options = {}
    ) {
        const shared = options.shared === undefined
            ? (
                control.classList.contains(
                    'alert_next_alliance'
                ) ||
                /share/i.test(
                    `${control.textContent || ''} ${control.getAttribute('title') || ''}`
                )
            )
            : options.shared === true;
        const allySteal = options.allySteal === true ||
            (
                !options.dispatchMode &&
                !!readAllyStealPendingState()
            );
        const autoMode = options.autoMode === undefined
            ? (
                autoModeRunning === true ||
                sessionStorage.getItem(
                    'mf_auto_mode_running'
                ) === 'true'
            )
            : options.autoMode === true;
        const ready = options.ready === undefined
            ? vehicleLoadState.ready === true
            : options.ready === true;
        const dispatchMode = trimMissionLoggerText(
            options.dispatchMode || (
                allySteal
                    ? 'ally-steal'
                    : autoMode
                        ? ready
                            ? (shared ? 'auto-share' : 'auto')
                            : 'auto-not-ready'
                        : (shared ? 'manual-share' : 'manual')
            ),
            80
        );

        return {
            shared,
            autoMode,
            ready,
            dispatchMode,
            reason: trimMissionLoggerText(
                options.reason ||
                'Native MissionChief dispatch control clicked',
                300
            ),
            metadata:
                options.metadata &&
                typeof options.metadata === 'object'
                    ? { ...options.metadata }
                    : {}
        };
    }

    function prepareMissionLoggerDispatchSnapshot(
        control,
        options = {}
    ) {
        const validControl =
            getMissionLoggerDispatchControl(control);
        if (
            !validControl ||
            !mfMissionLoggerEnabled ||
            !readMissionLoggerIdentity()
        ) {
            return null;
        }

        const selectedUnits =
            getMissionLoggerSelectedUnits();
        if (selectedUnits.length === 0) {
            return null;
        }

        const missionId =
            getCurrentMissionIdForQueueRestart();
        if (!missionId) return null;

        const resolved =
            resolveMissionLoggerDispatchOptions(
                validControl,
                options
            );
        const fingerprint =
            createMissionLoggerDispatchFingerprint(
                missionId,
                resolved.dispatchMode,
                selectedUnits
            );
        const snapshot = createMissionLoggerEvent(
            'dispatch',
            {
                dispatchMode:
                    resolved.dispatchMode,
                shared: resolved.shared,
                units: selectedUnits,
                ready: resolved.ready,
                autoMode: resolved.autoMode,
                dispatchFingerprint:
                    fingerprint,
                reason: resolved.reason,
                metadata: {
                    ...resolved.metadata,
                    dispatchCaptureSource:
                        resolved.metadata
                            .dispatchCaptureSource ||
                        'native-control-click',
                    dispatchControlId:
                        trimMissionLoggerText(
                            validControl.id || '',
                            120
                        ),
                    selectedUnitCount:
                        selectedUnits.length
                }
            }
        );

        if (!snapshot) return null;
        return {
            fingerprint,
            snapshot,
            timestamp: Date.now()
        };
    }

    function recordPreparedMissionLoggerDispatch(
        prepared
    ) {
        if (!prepared?.snapshot) return false;
        if (
            isDuplicateMissionLoggerDispatch(
                prepared.fingerprint,
                prepared.timestamp
            )
        ) {
            return false;
        }
        return recordMissionLoggerDispatchEvent(
            prepared.snapshot
        );
    }

    function recordMissionLoggerDispatchFromControl(
        control,
        options = {}
    ) {
        return recordPreparedMissionLoggerDispatch(
            prepareMissionLoggerDispatchSnapshot(
                control,
                options
            )
        );
    }

    function clickMissionLoggerDispatchControl(
        control,
        options = {},
        fallbackClick = null
    ) {
        const programmaticOptions = {
            ...options,
            metadata: {
                ...(
                    options.metadata &&
                    typeof options.metadata === 'object'
                        ? options.metadata
                        : {}
                ),
                dispatchCaptureSource:
                    'nexus-programmatic-dispatch'
            }
        };
        const prepared =
            prepareMissionLoggerDispatchSnapshot(
                control,
                programmaticOptions
            );
        const previousPending =
            mfMissionLoggerPendingProgrammaticDispatch;
        mfMissionLoggerPendingProgrammaticDispatch = {
            control,
            options: programmaticOptions
        };

        let clicked = false;
        try {
            control.click();
            clicked = true;
        } catch (_error) {
            if (typeof fallbackClick === 'function') {
                try {
                    clicked = fallbackClick() === true;
                } catch (_fallbackError) {
                    clicked = false;
                }
            }
        } finally {
            mfMissionLoggerPendingProgrammaticDispatch =
                previousPending;
        }

        if (!clicked) return false;

        // The capture-phase listener normally records synchronously. This
        // direct fallback covers programmatic dispatches occurring in a
        // mission runtime where that listener was not installed. Shared
        // fingerprint dedupe makes the second attempt harmless.
        recordPreparedMissionLoggerDispatch(prepared);
        return true;
    }

    function installMissionLoggerDispatchCapture() {
        if (mfMissionLoggerDispatchClickHandler) return;

        mfMissionLoggerDispatchClickHandler = event => {
            if (
                !mfMissionLoggerEnabled ||
                !readMissionLoggerIdentity()
            ) {
                return;
            }

            const control =
                getMissionLoggerDispatchControl(event.target);
            if (!control) return;

            const pending =
                mfMissionLoggerPendingProgrammaticDispatch;
            const pendingOptions =
                pending?.control === control
                    ? pending.options
                    : null;

            recordMissionLoggerDispatchFromControl(
                control,
                pendingOptions || {
                    metadata: {
                        dispatchCaptureSource:
                            event.isTrusted
                                ? 'trusted-native-control-click'
                                : 'synthetic-native-control-click'
                    }
                }
            );
        };

        document.addEventListener(
            'click',
            mfMissionLoggerDispatchClickHandler,
            true
        );
    }

    function removeMissionLoggerDispatchCapture() {
        if (!mfMissionLoggerDispatchClickHandler) return;
        document.removeEventListener(
            'click',
            mfMissionLoggerDispatchClickHandler,
            true
        );
        mfMissionLoggerDispatchClickHandler = null;
    }

    function suspendMissionLoggerRuntime() {
        stopMissionLoggerSyncTimer();
        stopMissionLoggerCreditReconciliation();
        removeMissionLoggerDispatchCapture();
        removeMissionLoggerCompletionCapture();
    }

    function cleanupMissionLoggerRuntime() {
        suspendMissionLoggerRuntime();

        if (mfMissionLoggerStorageHandler) {
            window.removeEventListener(
                'storage',
                mfMissionLoggerStorageHandler
            );
            mfMissionLoggerStorageHandler = null;
        }

        if (mfMissionLoggerOnlineHandler) {
            window.removeEventListener(
                'online',
                mfMissionLoggerOnlineHandler
            );
            mfMissionLoggerOnlineHandler = null;
        }

        if (mfMissionLoggerMessageHandler) {
            window.removeEventListener(
                'message',
                mfMissionLoggerMessageHandler
            );
            try {
                if (
                    window.top !== window &&
                    window.top.location.origin ===
                        window.location.origin
                ) {
                    window.top.removeEventListener(
                        'message',
                        mfMissionLoggerMessageHandler
                    );
                }
            } catch (_error) {}
            mfMissionLoggerMessageHandler = null;
        }

        Array.from(
            mfMissionLoggerPendingRequests.keys()
        ).forEach(cleanupMissionLoggerRequest);
        mfMissionLoggerSyncActive = false;
    }

    function formatMissionLoggerTimestamp(timestamp) {
        const value = Number(timestamp || 0);
        if (!value) return 'Never';

        try {
            return new Date(value).toLocaleString([], {
                day: '2-digit',
                month: '2-digit',
                hour: '2-digit',
                minute: '2-digit'
            });
        } catch (_error) {
            return 'Unknown';
        }
    }

    function renderMissionLoggerStatus() {
        const toggle = document.getElementById(
            'mf-mission-logger-toggle'
        );
        const endpointInput = document.getElementById(
            'mf-mission-logger-endpoint'
        );
        const profile = document.getElementById(
            'mf-mission-logger-profile'
        );
        const status = document.getElementById(
            'mf-mission-logger-state'
        );
        const queue = document.getElementById(
            'mf-mission-logger-queue'
        );
        const lastSync = document.getElementById(
            'mf-mission-logger-last-sync'
        );
        const creditStatus = document.getElementById(
            'mf-mission-logger-credit-status'
        );
        const error = document.getElementById(
            'mf-mission-logger-error'
        );
        const playerSelect = document.getElementById(
            'mf-mission-logger-player'
        );
        const saveButton = document.getElementById(
            'mf-mission-logger-save'
        );
        const syncButton = document.getElementById(
            'mf-mission-logger-sync'
        );
        const forgetButton = document.getElementById(
            'mf-mission-logger-forget'
        );

        if (
            !toggle &&
            !profile &&
            !status
        ) return;

        const identity = readMissionLoggerIdentity();
        const state = readMissionLoggerState();
        const queueCount = readMissionLoggerQueue().length;
        const pendingCreditCount =
            countPendingMissionLoggerCredits();
        const catchupNextPage = Math.max(
            1,
            parseInt(
                state.offlineCreditCatchupNextPage,
                10
            ) || 1
        );
        const offlineRecoveredCount = Math.max(
            0,
            Number(
                state.totalOfflineRecoveredCreditEvents || 0
            )
        );
        const catchupDeferredForQueue =
            state.offlineCreditCatchupDeferred === true;
        const endpointReady =
            !!normaliseMissionLoggerEndpoint(
                mfMissionLoggerEndpoint
            );

        if (toggle) {
            toggle.checked = mfMissionLoggerEnabled;
        }
        if (
            endpointInput &&
            document.activeElement !== endpointInput
        ) {
            endpointInput.value =
                mfMissionLoggerEndpoint;
        }
        if (endpointInput) {
            endpointInput.disabled = mfMissionLoggerSyncActive;
        }
        if (
            playerSelect &&
            document.activeElement !== playerSelect
        ) {
            playerSelect.value = identity?.playerName || '';
        }
        if (playerSelect) {
            playerSelect.disabled = mfMissionLoggerSyncActive;
        }
        if (profile) {
            profile.textContent = identity
                ? `Logger user: ${identity.playerName}`
                : 'Logger user: not configured';
        }
        if (status) {
            status.textContent = !mfMissionLoggerEnabled
                ? 'Logger is off.'
                : !endpointReady
                    ? 'Setup required: enter the Google logger endpoint.'
                    : !identity
                        ? 'Setup required: choose a user and save the logger setup.'
                        : mfMissionLoggerSyncActive
                            ? 'Draining queued logger events...'
                            : queueCount > 0 &&
                                Number(state.drainRequestedAt || 0) > 0
                                ? String(
                                    state.drainMessage ||
                                    'Full queue drain queued.'
                                )
                                : 'Automatic logging is active.';
            status.classList.toggle(
                'mf2026-good',
                !!(
                    mfMissionLoggerEnabled &&
                    endpointReady &&
                    identity &&
                    !state.lastError
                )
            );
            status.classList.toggle(
                'mf2026-warn',
                !!state.lastError ||
                (mfMissionLoggerEnabled &&
                    (!endpointReady || !identity))
            );
        }
        if (queue) {
            const queuePercent = Math.round(
                queueCount /
                MF_MISSION_LOGGER_MAX_QUEUE_EVENTS * 100
            );
            queue.textContent =
                `Queued events: ${queueCount}` +
                (
                    queueCount > 0
                        ? ` · ${queuePercent}% of local limit` +
                            (
                                mfMissionLoggerSyncActive
                                    ? ' · draining now'
                                    : ''
                            )
                        : ''
                );
            queue.classList.toggle(
                'mf2026-warn',
                queuePercent >= 75
            );
        }
        if (lastSync) {
            const progress = String(
                state.drainMessage || ''
            ).trim();
            lastSync.textContent =
                `Last upload: ${formatMissionLoggerTimestamp(state.lastSuccessAt)}` +
                (progress ? ` · ${progress}` : '');
        }
        if (creditStatus) {
            creditStatus.textContent = !mfMissionLoggerEnabled
                ? 'Actual credits: logger is off.'
                : !identity
                ? 'Actual credits: available after logger setup.'
                : state.lastCreditError
                    ? `Actual credits: transaction check delayed — ${state.lastCreditError}`
                    : catchupDeferredForQueue
                        ? 'Actual credits: offline catch-up is paused while queued events upload.'
                    : catchupNextPage > 1
                        ? `Actual credits: offline catch-up is continuing from Credits page ${catchupNextPage}.`
                    : pendingCreditCount > 0
                        ? `Actual credits: ${pendingCreditCount} completed mission${pendingCreditCount === 1 ? '' : 's'} awaiting an exact transaction match.`
                        : offlineRecoveredCount > 0
                            ? `Actual credits: exact transaction matching active — ${offlineRecoveredCount} offline completion${offlineRecoveredCount === 1 ? '' : 's'} recovered.`
                            : 'Actual credits: exact transaction matching active.';
            creditStatus.classList.toggle(
                'mf2026-warn',
                !!state.lastCreditError
            );
            creditStatus.classList.toggle(
                'mf2026-good',
                !!identity &&
                !state.lastCreditError &&
                pendingCreditCount === 0
            );
        }
        if (error) {
            error.textContent = state.lastError
                ? `Last error: ${state.lastError}`
                : '';
            error.hidden = !state.lastError;
        }
        if (saveButton) {
            saveButton.disabled = mfMissionLoggerSyncActive;
        }
        if (syncButton) {
            syncButton.disabled =
                !mfMissionLoggerEnabled ||
                !endpointReady ||
                !identity;
        }
        if (forgetButton) {
            forgetButton.disabled =
                !identity && !endpointReady;
        }
    }

    function formatRuntime(ms) {
        const totalSeconds = Math.max(0, Math.floor(ms / 1000));
        const hours = Math.floor(totalSeconds / 3600);
        const minutes = Math.floor((totalSeconds % 3600) / 60);
        const seconds = totalSeconds % 60;

        return [hours, minutes, seconds]
            .map(value => String(value).padStart(2, '0'))
            .join(':');
    }

    function formatMoney(value) {
        const number = Number(value || 0);
        return `£${number.toLocaleString('en-GB')}`;
    }

    function addMissionLogEntry(type, missionName, detail, credits) {
        const stats = loadSessionStats();
        const safeCredits = Number.isFinite(Number(credits)) ? Number(credits) : 0;

        if (type === 'completed') {
            stats.completed += 1;
            stats.credits += safeCredits;
        }

        if (type === 'skipped') {
            stats.skipped += 1;
        }

        if (type === 'update') {
            stats.updates += 1;
        }

        stats.entries.unshift({
            type,
            missionName: missionName || 'Mission',
            detail: detail || '',
            credits: safeCredits,
            hasCredits: Number.isFinite(Number(credits)) && Number(credits) > 0,
            timestamp: Date.now()
        });

        stats.entries = stats.entries.slice(0, 25);
        saveSessionStats(stats);
        renderSessionPanel();
    }

    function renderSessionPanel() {
        const container = document.getElementById('session-panel-content');
        if (!container) return;

        const stats = loadSessionStats();
        const runtimeMs = Date.now() - Number(stats.startedAt || Date.now());
        const completed = Number(stats.completed || 0);
        const skipped = Number(stats.skipped || 0);
        const updates = Number(stats.updates || 0);
        const credits = Number(stats.credits || 0);
        const hours = Math.max(runtimeMs / 3600000, 0.001);
        const average = completed > 0 ? Math.round(credits / completed) : 0;
        const creditsPerHour = Math.round(credits / hours);
        const missionsPerHour = Math.round(completed / hours);

        const successRate = (completed + skipped) > 0
            ? (((completed / (completed + skipped)) * 100).toFixed(1) + '%')
            : '----';

        container.innerHTML = `
            <div class="mf2026-stat-grid">
                <span>Runtime</span><strong>${formatRuntime(runtimeMs)}</strong>
                <span>Completed</span><strong>${completed}</strong>
                <span>Skipped</span><strong>${skipped}</strong>
                <span>Updates</span><strong>${updates}</strong>
                <span>Credits</span><strong>${formatMoney(credits)}</strong>
                <span>Average</span><strong>${completed > 0 ? formatMoney(average) : '----'}</strong>
                <span>Credits/hr</span><strong>${completed > 0 ? formatMoney(creditsPerHour) : '----'}</strong>
                <span>Missions/hr</span><strong>${completed > 0 ? missionsPerHour : '----'}</strong>
                <span>Success</span><strong>${successRate}</strong>
            </div>
        `;
    }

let sessionRuntimeTicker = null;

    function stopSessionRuntimeTicker() {
        if (!sessionRuntimeTicker) return;
        clearInterval(sessionRuntimeTicker);
        sessionRuntimeTicker = null;
    }

    function startSessionRuntimeTicker() {
        if (sessionRuntimeTicker) return;

        sessionRuntimeTicker = setInterval(() => {
            if (!document.getElementById('session-panel-content')) {
                stopSessionRuntimeTicker();
                return;
            }

            renderSessionPanel();
        }, 2000);
    }

    async function waitForMissionReady() {
        const timeoutMs = Math.max(4500, getMissionReadyDelay() + 2500);
        const started = Date.now();
        let stableSince = 0;
        let lastDeepProbeAt = 0;
        let hasPatientData = false;
        let hasUpdateRows = false;

        while (Date.now() - started < timeoutMs) {
            const hasMission = isMissionPage();
            const hasUnits = !!document.querySelector('a[search_attribute]');
            const hasMissionHelp = !!getMissionRequirementSource();
            const hasBasicMissionUi = hasMission && hasUnits && hasMissionHelp;

            if (hasBasicMissionUi) {
                if (!stableSince) stableSince = Date.now();

                const now = Date.now();

                if (now - lastDeepProbeAt >= 300) {
                    lastDeepProbeAt = now;
                    hasPatientData = findPatientCount(true) > 0;
                    hasUpdateRows = readMissionUpdateRows({
                        silent: true
                    }).length > 0;
                }

                // Give dynamic patient cards at least 1.5 seconds after the
                // basic mission controls appear. They often render later.
                if (
                    hasPatientData ||
                    hasUpdateRows ||
                    Date.now() - stableSince >= 650
                ) {
                    break;
                }
            } else {
                stableSince = 0;
                hasPatientData = false;
                hasUpdateRows = false;
            }

            await wait(150);
        }

        const configuredDelay = getMissionReadyDelay();
        const finalReadyDelay =
            hasPatientData || hasUpdateRows
                ? Math.min(configuredDelay, 350)
                : configuredDelay;

        await wait(finalReadyDelay);
        requireMissionUpdateFirstPass('mission ready / content refreshed');
    }

    function updateStatusBox(message) {
        const statusMessage =
            document.getElementById('status-box-message');

        if (statusMessage) {
            statusMessage.textContent = message;
        } else {
            const statusBox =
                document.getElementById('status-box');

            if (statusBox) {
                statusBox.textContent = message;
            }
        }

        if (mfDebugEnabled) {
            debugLog('STATUS', message);
        }
    }

    function normaliseAutoStopReason(reason) {
        const value = String(
            reason ||
            'Auto Mode stopped for an unknown reason.'
        )
            .replace(/\s+/g, ' ')
            .trim();

        return (
            value ||
            'Auto Mode stopped for an unknown reason.'
        ).slice(0, 800);
    }

    function readPersistentAutoStopRecord() {
        let raw = '';

        try {
            raw = localStorage.getItem(
                MF_AUTO_STOP_RECORD_KEY
            ) || '';
        } catch (_error) {
            return null;
        }

        if (!raw) return null;

        try {
            const parsed = JSON.parse(raw);
            const reason = normaliseAutoStopReason(
                parsed?.reason
            );
            const stoppedAt = Number(
                parsed?.stoppedAt
            );

            if (
                !parsed ||
                typeof parsed.reason !== 'string' ||
                !parsed.reason.trim() ||
                !Number.isFinite(stoppedAt) ||
                stoppedAt <= 0
            ) {
                throw new Error(
                    'Invalid Auto Mode stop record'
                );
            }

            return {
                reason,
                stoppedAt
            };
        } catch (_error) {
            try {
                localStorage.removeItem(
                    MF_AUTO_STOP_RECORD_KEY
                );
            } catch (_removeError) {}

            return null;
        }
    }

    function formatAutoStopTimestamp(stoppedAt) {
        try {
            return new Date(stoppedAt).toLocaleString(
                [],
                {
                    day: '2-digit',
                    month: '2-digit',
                    hour: '2-digit',
                    minute: '2-digit'
                }
            );
        } catch (_error) {
            return '';
        }
    }

    function renderPersistentAutoStopRecord(
        record = readPersistentAutoStopRecord()
    ) {
        const statusBox =
            document.getElementById('status-box');
        const flag =
            document.getElementById('mf-auto-stop-flag');
        const reason =
            document.getElementById('mf-auto-stop-reason');
        const time =
            document.getElementById('mf-auto-stop-time');

        if (!statusBox || !flag || !reason || !time) {
            return;
        }

        const hasRecord = !!record;

        flag.hidden = !hasRecord;
        statusBox.classList.toggle(
            'mf-auto-stopped',
            hasRecord
        );

        reason.textContent =
            hasRecord
                ? record.reason
                : '';

        time.textContent =
            hasRecord
                ? formatAutoStopTimestamp(
                    record.stoppedAt
                )
                : '';

        if (hasRecord) {
            updateStatusBox(
                'Start Auto Mode again to clear this warning.'
            );
        }
    }

    function persistAutomaticAutoStopRecord(reason) {
        const record = {
            reason: normaliseAutoStopReason(reason),
            stoppedAt: Date.now()
        };

        try {
            localStorage.setItem(
                MF_AUTO_STOP_RECORD_KEY,
                JSON.stringify(record)
            );
        } catch (_error) {}

        renderPersistentAutoStopRecord(record);

        return record;
    }

    function clearPersistentAutoStopRecord() {
        try {
            localStorage.removeItem(
                MF_AUTO_STOP_RECORD_KEY
            );
        } catch (_error) {}

        renderPersistentAutoStopRecord(null);
    }

    function removeAutoModeQueueHelperCopy() {
        const autoButton = Array.from(
            document.querySelectorAll('button')
        ).find(button => {
            const text = String(
                button.innerText ||
                button.textContent ||
                ''
            )
                .replace(/\s+/g, ' ')
                .trim();

            return /^(?:Start|Stop)\s+Auto\s+Mode$/i.test(text);
        });

        const autoBox = autoButton?.closest?.('.mf2026-box');
        const checkbox = autoBox?.querySelector?.('input[type="checkbox"]');

        if (!autoBox || !checkbox) return;

        const helperCandidates = new Set([
            ...Array.from(
                autoBox.querySelectorAll(
                    '.mf2026-small, small, p'
                )
            ),
            ...Array.from(autoBox.children || [])
        ]);

        helperCandidates.forEach(element => {
            if (
                !element ||
                element === autoButton ||
                element.contains(autoButton) ||
                element.contains(checkbox) ||
                element.querySelector?.(
                    'button, input, select, textarea'
                )
            ) {
                return;
            }

            const text = String(
                element.innerText ||
                element.textContent ||
                ''
            )
                .replace(/\s+/g, ' ')
                .trim();

            if (
                /unit finder/i.test(text) &&
                /mission update/i.test(text) &&
                /dispatch/i.test(text)
            ) {
                element.remove();
            }
        });
    }

    function updateAutoModeButton() {
        removeAutoModeQueueHelperCopy();
        setTimeout(
            removeAutoModeQueueHelperCopy,
            0
        );
        const button = document.getElementById('auto-mode-box');

        if (!button) return;

        if (autoModeRunning) {
            button.textContent = 'Auto Mode: Stop';
            button.style.backgroundColor = '#dc3545';
        } else {
            button.textContent = 'Auto Mode: Start';
            button.style.backgroundColor = '#6f42c1';
        }
    }

    function changeDispatchBoxColor(isComplete) {
        const problemAlert = getVisibleInlineProblemAlertText();

        if (isComplete && problemAlert) {
            isComplete = false;

            if (mfDebugEnabled) {
                debugLog('READY BLOCK', `Problem alert still visible, blocking ready: ${problemAlert.slice(0, 260)}`);
            }

            try {
                recordIssueEvent('READY BLOCKED BY PROBLEM ALERT', {
                    problemAlert
                }, true);
            } catch (error) {}
        }

        const dispatchBox = document.getElementById('dispatch-box');

        if (dispatchBox) {
            dispatchBox.style.backgroundColor = isComplete ? 'green' : 'grey';

            if (isComplete) {
                updateStatusBox('Units ready for dispatch.');
            }
        }

        vehicleLoadState.ready = !!isComplete;
        renderVehicleLoadList();

        try {
            mfPersistUnitFinderDiagnostic(
                isComplete
                    ? 'ready-for-dispatch'
                    : 'not-ready'
            );
        } catch (_error) {}
    }

    function resetVehicleLoadState() {
        clearSelectionGuards();
        invalidateVehicleCheckboxCache();
        vehicleLoadState = {
            rows: [],
            patients: 0,
            ambulances: 0,
            ambulanceOfficer: false,
            trainedPersonnelBlocked: false,
            trainedPersonnelBlockText: '',
            ready: false
        };
    }

    function blockTrainedPersonnelDispatch(
        shortfalls,
        source = 'Trained-personnel selection'
    ) {
        const detail = (Array.isArray(shortfalls) ? shortfalls : [shortfalls])
            .map(value => String(value || '').trim())
            .filter(Boolean)
            .join(' | ') ||
            'Verified trained personnel are still missing.';

        vehicleLoadState.trainedPersonnelBlocked = true;
        vehicleLoadState.trainedPersonnelBlockText = detail;
        changeDispatchBoxColor(false);
        updateStatusBox(
            `${source}: verified trained personnel are still missing. Dispatch blocked.`
        );

        if (mfDebugEnabled) {
            debugLog(
                'TRAINED PERSONNEL FAIL CLOSED',
                `${source} | ${detail}`
            );
        }
    }

    function addOrUpdateVehicleRow(originalName, mappedName, required, status, selected) {
        const safeRequired = Math.max(0, parseInt(required, 10) || 0);
        const safeSelected = Number.isFinite(Number(selected)) ? Math.max(0, Math.min(Number(selected), safeRequired)) : countSelectedMatchingVehicles(originalName, mappedName);
        const existing = vehicleLoadState.rows.find(row => row.originalName === originalName && row.mappedName === mappedName);

        if (existing) {
            existing.mappedName = mappedName;
            existing.required = safeRequired;
            existing.selected = Math.min(safeSelected, safeRequired);
            existing.status = status || (existing.selected >= safeRequired ? 'assigned' : existing.selected > 0 ? 'retrying' : 'pending');
            return;
        }

        vehicleLoadState.rows.push({
            originalName,
            mappedName,
            required: safeRequired,
            selected: Math.min(safeSelected, safeRequired),
            status: status || (safeSelected >= safeRequired ? 'assigned' : safeSelected > 0 ? 'retrying' : 'pending')
        });
    }

    function setVehicleStatus(originalName, status) {
        const row = vehicleLoadState.rows.find(r => r.originalName === originalName);
        if (row) {
            row.status = status;
            row.selected = Math.min(countSelectedMatchingVehicles(row.originalName, row.mappedName), Number(row.required || 0));
        }
    }

    const MF_SELECTED_TRAINING_LABEL_OVERRIDES =
        Object.freeze({
            critical_care: 'Critical Care',
            traffic_police: 'Roads Policing',
            swat: 'Firearms',
            police_horse: 'Mounted Officer',
            k9: 'Dog Handler',
            drone: 'Drone Operator',
            polizeihubschrauber: 'Police Aviation',
            railway_police_command: 'Mobile Operations Management',
            bomb_disposal_command: 'EOD Commander',
            bomb_disposal: 'Bomb Disposal',
            bomb_disposal_diver: 'Marine Bomb Disposal',
            elw2: 'Level 1 Incident Commander',
            gw_gefahrgut: 'HazMat',
            railway_fire: 'Railway Fire'
        });


    function getSelectedTrainingDisplayLabel(trainingCode) {
        const code = String(trainingCode || '').trim();
        if (!code) return 'Unknown training';

        const supportedDefinition =
            MF_TRAINED_PERSONNEL_PATTERNS.find(definition => {
                return String(definition?.code || '') === code;
            });

        if (supportedDefinition?.label) {
            return supportedDefinition.label;
        }

        if (MF_SELECTED_TRAINING_LABEL_OVERRIDES[code]) {
            return MF_SELECTED_TRAINING_LABEL_OVERRIDES[code];
        }

        return code
            .replace(/[_-]+/g, ' ')
            .replace(/\s+/g, ' ')
            .trim()
            .replace(/\b\w/g, character => character.toUpperCase());
    }


    function getSelectedTrainedPersonnelPanelModel() {
        let registry = { vehicles: {} };

        try {
            registry = readPersonnelTrainingRegistry();
        } catch (_error) {}

        return getVehicleCheckboxSnapshot(true)
            .filter(input => input?.checked)
            .map(input => {
                let registryMatch = null;

                try {
                    registryMatch = getRegistryEntryForMissionCheckbox(
                        input,
                        registry
                    );
                } catch (_error) {}

                const entry = registryMatch?.entry || null;
                if (!entry) return null;

                const profiles = (
                    Array.isArray(entry.assignedTrainingProfiles)
                        ? entry.assignedTrainingProfiles
                        : []
                ).map(profile => {
                    return Array.from(new Set(
                        (Array.isArray(profile) ? profile : [])
                            .map(value => String(value || '').trim())
                            .filter(Boolean)
                    ));
                }).filter(profile => profile.length > 0);

                const trainingCounts = Object.entries(
                    entry.trainingCounts &&
                    typeof entry.trainingCounts === 'object'
                        ? entry.trainingCounts
                        : {}
                ).map(([code, value]) => {
                    return {
                        code: String(code || ''),
                        label: getSelectedTrainingDisplayLabel(code),
                        count: Math.max(0, parseInt(value, 10) || 0)
                    };
                }).filter(item => item.code && item.count > 0)
                    .sort((left, right) => {
                        return left.label.localeCompare(right.label);
                    });

                if (profiles.length === 0 && trainingCounts.length === 0) {
                    return null;
                }

                return {
                    vehicleId: getMissionVehicleId(input),
                    vehicleName: getVehicleDebugName(input),
                    profiles,
                    profilesComplete:
                        entry.trainingProfilesComplete === true,
                    trainingCounts
                };
            })
            .filter(Boolean)
            .sort((left, right) => {
                return String(left.vehicleName || '')
                    .localeCompare(String(right.vehicleName || ''));
            });
    }


    const MF_TRAINED_PERSONNEL_MUTATION_REFRESH_DELAY_MS =
        1200;
    const MF_LIVE_TRAINED_PERSONNEL_DISPLAY_CACHE_MS =
        1500;
    let mfTrainedPersonnelMutationRefreshTimer = null;
    let mfLiveTrainedPersonnelDisplayCache = {
        missionId: '',
        expiresAt: 0,
        rows: []
    };

    function invalidateLiveTrainedPersonnelDisplayCache() {
        mfLiveTrainedPersonnelDisplayCache = {
            missionId: '',
            expiresAt: 0,
            rows: []
        };
    }

    function cancelTrainedPersonnelPanelRefresh() {
        if (mfTrainedPersonnelMutationRefreshTimer) {
            clearTimeout(
                mfTrainedPersonnelMutationRefreshTimer
            );
            mfTrainedPersonnelMutationRefreshTimer = null;
        }
        invalidateLiveTrainedPersonnelDisplayCache();
    }

    function scheduleTrainedPersonnelPanelRefresh() {
        if (mfTrainedPersonnelMutationRefreshTimer) return;

        mfTrainedPersonnelMutationRefreshTimer = setTimeout(
            () => {
                mfTrainedPersonnelMutationRefreshTimer = null;
                renderSelectedTrainedPersonnelPanel();
            },
            MF_TRAINED_PERSONNEL_MUTATION_REFRESH_DELAY_MS
        );
    }

    function applyTrainedPersonnelPanelTextRender(
        summary,
        content,
        summaryText,
        contentMarkup
    ) {
        if (summary.textContent !== summaryText) {
            summary.textContent = summaryText;
        }
        if (content.innerHTML !== contentMarkup) {
            content.innerHTML = contentMarkup;
        }
    }

    function applyTrainedPersonnelPanelMarkupRender(
        summary,
        content,
        summaryMarkup,
        contentMarkup
    ) {
        if (summary.innerHTML !== summaryMarkup) {
            summary.innerHTML = summaryMarkup;
        }
        if (content.innerHTML !== contentMarkup) {
            content.innerHTML = contentMarkup;
        }
    }

    function renderSelectedTrainedPersonnelPanel() {
        const summary =
            document.getElementById('trained-personnel-summary');
        const content =
            document.getElementById('trained-personnel-content');

        if (!summary || !content) return;


        let preloadState = { status: 'idle' };
        let requiredPersonnel = [];
        let liveMissingPersonnel = [];
        let missionVehiclesOnSceneForTrainedPersonnel =
            false;

        try {
            missionVehiclesOnSceneForTrainedPersonnel =
                hasMissionVehiclesOnSceneForTrainedPersonnelAuthority();
            preloadState =
                getMissionRequirementPreloadState();
            requiredPersonnel =
                getPreloadedMissionTrainedPersonnelRequirements();
            liveMissingPersonnel =
                getLiveMissionTrainedPersonnelRequirementsForDisplay();
        } catch (error) {
            if (mfDebugEnabled) {
                debugLog(
                    'MISSION PERSONNEL PRELOAD',
                    `panel cache read failed: ${error?.message || error}`
                );
            }
        }
        const selectedVehicles =
            getSelectedTrainedPersonnelPanelModel();
        const completeProfiles = selectedVehicles.reduce(
            (total, vehicle) => {
                return total + (
                    vehicle.profilesComplete
                        ? vehicle.profiles.length
                        : 0
                );
            },
            0
        );
        const aggregateOnlyVehicles = selectedVehicles.filter(vehicle => {
            return !vehicle.profilesComplete;
        }).length;
        const requiredTotal = requiredPersonnel.reduce(
            (total, requirement) => {
                return total + requirement.required;
            },
            0
        );
        const coveredTotal = requiredPersonnel.reduce(
            (total, requirement) => {
                return total + Math.min(
                    requirement.required,
                    getSelectedTrainedPersonnelCountForCode(
                        selectedVehicles,
                        requirement.code
                    )
                );
            },
            0
        );
        const liveMissingTotal = liveMissingPersonnel.reduce(
            (total, requirement) => {
                return total + requirement.missing;
            },
            0
        );

        if (
            requiredPersonnel.length === 0 &&
            liveMissingPersonnel.length === 0 &&
            selectedVehicles.length === 0
        ) {
            if (
                missionVehiclesOnSceneForTrainedPersonnel
            ) {
                applyTrainedPersonnelPanelTextRender(
                    summary,
                    content,
                    'No current trained-personnel shortage is reported.',
                    '<span class="mf2026-small">Vehicles are on scene. Live personnel and course shortages are authoritative; Mission Required Personnel is shown only before the first vehicle arrives on scene.</span>'
                );
                return;
            }

            if (preloadState.status === 'loading') {
                applyTrainedPersonnelPanelTextRender(
                    summary,
                    content,
                    'Loading mission Required Personnel...',
                    '<span class="mf2026-small">Reading the mission requirement table before unit selection.</span>'
                );
                return;
            }

            applyTrainedPersonnelPanelTextRender(
                summary,
                content,
                'No required or selected trained-personnel evidence is available.',
                '<span class="mf2026-small">Mission Required Personnel and selected trained personnel will appear here.</span>'
            );
            return;
        }

        const summaryParts = [];

        if (requiredPersonnel.length > 0) {
            summaryParts.push(`
                <div><strong>${requiredPersonnel.length}</strong> required course${requiredPersonnel.length === 1 ? '' : 's'}</div>
                <div><strong>${coveredTotal}</strong> / <strong>${requiredTotal}</strong> required trained-personnel coverage</div>
            `);
        }

        if (liveMissingPersonnel.length > 0) {
            summaryParts.push(`
                <div><strong>${liveMissingPersonnel.length}</strong> current missing course${liveMissingPersonnel.length === 1 ? '' : 's'}</div>
                <div><strong>${liveMissingTotal}</strong> trained personnel still missing</div>
            `);
        } else if (
            missionVehiclesOnSceneForTrainedPersonnel
        ) {
            summaryParts.push(`
                <div><strong>0</strong> current trained-personnel shortages</div>
            `);
        }

        if (selectedVehicles.length > 0) {
            summaryParts.push(`
                <div><strong>${selectedVehicles.length}</strong> selected trained vehicle${selectedVehicles.length === 1 ? '' : 's'}</div>
                <div><strong>${completeProfiles}</strong> trained personnel profile${completeProfiles === 1 ? '' : 's'}${aggregateOnlyVehicles ? ` · ${aggregateOnlyVehicles} aggregate-only` : ''}</div>
            `);
        }

        const summaryMarkup = summaryParts.join('');

        const requiredMarkup = requiredPersonnel.length > 0
            ? `
                <div class="mf2026-training-vehicle">
                    <div class="mf2026-training-vehicle-name">
                        Mission Required Personnel
                    </div>
                    ${requiredPersonnel.map(requirement => {
                        const selected = Math.min(
                            requirement.required,
                            getSelectedTrainedPersonnelCountForCode(
                                selectedVehicles,
                                requirement.code
                            )
                        );
                        const remaining = Math.max(
                            0,
                            requirement.required - selected
                        );

                        return `
                            <div class="mf2026-training-person">
                                <span class="mf2026-training-person-label">${selected} / ${requirement.required}</span>
                                <span class="mf2026-training-course-list">${escapeHtml(requirement.label)}${remaining > 0 ? ` · ${remaining} still needed` : ' · covered'}</span>
                            </div>
                        `;
                    }).join('')}
                </div>
            `
            : '';

        const liveMissingMarkup = liveMissingPersonnel.length > 0
            ? `
                <div class="mf2026-training-vehicle">
                    <div class="mf2026-training-vehicle-name">
                        Current Missing Personnel
                    </div>
                    ${liveMissingPersonnel.map(requirement => {
                        return `
                            <div class="mf2026-training-person">
                                <span class="mf2026-training-person-label">${requirement.missing} missing</span>
                                <span class="mf2026-training-course-list">${escapeHtml(requirement.label)} · current live shortage</span>
                            </div>
                        `;
                    }).join('')}
                </div>
            `
            : '';

        const selectedMarkup = selectedVehicles.map(vehicle => {
            const vehicleName =
                vehicle.vehicleName ||
                (vehicle.vehicleId
                    ? `Vehicle ${vehicle.vehicleId}`
                    : 'Selected vehicle');
            const profileMarkup =
                vehicle.profilesComplete &&
                vehicle.profiles.length > 0
                    ? vehicle.profiles.map((profile, index) => {
                        const labels = profile
                            .map(getSelectedTrainingDisplayLabel)
                            .sort((left, right) => left.localeCompare(right));

                        return `
                            <div class="mf2026-training-person">
                                <span class="mf2026-training-person-label">Person ${index + 1}</span>
                                <span class="mf2026-training-course-list">${labels.map(escapeHtml).join(', ')}</span>
                            </div>
                        `;
                    }).join('')
                    : vehicle.trainingCounts.map(item => {
                        return `
                            <div class="mf2026-training-person">
                                <span class="mf2026-training-person-label">${item.count}×</span>
                                <span class="mf2026-training-course-list">${escapeHtml(item.label)}</span>
                            </div>
                        `;
                    }).join('');

            return `
                <div class="mf2026-training-vehicle">
                    <div class="mf2026-training-vehicle-name">
                        ${escapeHtml(vehicleName)}
                        ${vehicle.vehicleId ? `<span class="mf2026-small"> #${escapeHtml(vehicle.vehicleId)}</span>` : ''}
                    </div>
                    ${profileMarkup}
                </div>
            `;
        }).join('');

        const contentMarkup =
            requiredMarkup +
            liveMissingMarkup +
            selectedMarkup;

        applyTrainedPersonnelPanelMarkupRender(
            summary,
            content,
            summaryMarkup,
            contentMarkup
        );
    }

    function renderVehicleLoadListNow() {
        const listContent = document.getElementById('vehicle-load-list-content');
        const patientContent = document.getElementById('vehicle-patient-content');
        const summary = document.getElementById('vehicle-load-summary');
        const progress = document.getElementById('vehicle-load-progress');

        if (!listContent || !patientContent || !summary || !progress) return;

        refreshVehicleRequirementCounters();

        const preloadState =
            getMissionRequirementPreloadState();
        const preloadedRows =
            vehicleLoadState.rows.length === 0
                ? getPreloadedMissionVehicleRequirementsForDisplay()
                : [];
        const usingPreloadedRows =
            preloadedRows.length > 0;
        const displayRows =
            usingPreloadedRows
                ? preloadedRows
                : vehicleLoadState.rows;

        const totalRequired = displayRows.reduce((sum, row) => sum + Number(row.required || 0), 0);
        const foundRequired = displayRows.reduce((sum, row) => sum + Number(row.selected || 0), 0);

        const percent = totalRequired > 0 ? Math.round((foundRequired / totalRequired) * 100) : vehicleLoadState.ready ? 100 : 0;
        const preloadedCoverageComplete = Boolean(
            usingPreloadedRows &&
            totalRequired > 0 &&
            foundRequired >= totalRequired
        );
        const statusText = usingPreloadedRows
            ? preloadedCoverageComplete
                ? 'Covered'
                : 'Requirements loaded'
            : vehicleLoadState.ready
                ? 'Ready'
                : 'Not Ready';
        const statusClass =
            vehicleLoadState.ready ||
            preloadedCoverageComplete
                ? 'mf2026-good'
                : 'mf2026-warn';

        summary.innerHTML = `
            <div>Vehicles: <strong>${foundRequired}</strong> / <strong>${totalRequired}</strong></div>
            <div>Status: <strong class="${statusClass}">${statusText}</strong></div>
        `;

        progress.style.width = `${percent}%`;

        if (displayRows.length === 0) {
            listContent.innerHTML = vehicleLoadState.ready
                ? `<span class="mf2026-good">✓ Ambulance-only mission ready</span>`
                : preloadState.status === 'loading'
                    ? `Loading mission vehicle requirements...`
                    : `Click Unit Finder to load vehicles.`;
        } else {
            listContent.innerHTML = displayRows.map(row => {
                let icon = '○';
                let cls = 'mf2026-warn';

                const selected = Math.min(Number(row.selected || 0), Number(row.required || 0));
                const required = Number(row.required || 0);

                if (selected >= required && required > 0) {
                    icon = '✓';
                    cls = 'mf2026-good';
                } else if (row.status === 'missing') {
                    icon = '✕';
                    cls = 'mf2026-bad';
                } else if (selected > 0 || row.status === 'retrying') {
                    icon = '↻';
                    cls = 'mf2026-warn';
                }

                return `
                    <div class="mf2026-row">
                        <div class="mf2026-name">
                            <span class="${cls}">${icon}</span>
                            ${escapeHtml(row.originalName)}
                            <div class="mf2026-small">${escapeHtml(row.mappedName)}</div>
                        </div>
                        <div class="mf2026-count ${selected >= required && required > 0 ? 'mf2026-good' : 'mf2026-warn'}">${selected} / ${required}</div>
                    </div>
                `;
            }).join('');
        }

        patientContent.innerHTML = `
            <div class="mf2026-row">
                <div>Patients found</div>
                <div class="mf2026-count">${vehicleLoadState.patients}</div>
            </div>
            <div class="mf2026-row">
                <div>Ambulances selected</div>
                <div class="mf2026-count">${vehicleLoadState.ambulances}</div>
            </div>
            <div class="mf2026-row">
                <div>Ambulance Officer</div>
                <div class="mf2026-count mf2026-warn">Live requirements only</div>
            </div>
        `;


        renderSelectedTrainedPersonnelPanel();
    }

    function renderVehicleLoadList() {
        if (mfVehicleLoadRenderFrame !== null) return;

        const run = () => {
            mfVehicleLoadRenderFrame = null;
            renderVehicleLoadListNow();
        };

        if (typeof requestAnimationFrame === 'function') {
            mfVehicleLoadRenderFrame = requestAnimationFrame(run);
        } else {
            mfVehicleLoadRenderFrame = setTimeout(run, 50);
        }
    }

    function escapeHtml(value) {
        return String(value)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
    }

    function getPatientSelectionMissionKey() {
        const localMissionKey =
            getLocalMissionInstanceKey();

        if (localMissionKey) {
            return localMissionKey;
        }

        const missionId =
            getCurrentMissionIdForQueueRestart();

        if (missionId) {
            return `mission:${missionId}`;
        }

        const missionName =
            String(
                getCurrentMissionName() ||
                'Mission'
            )
                .replace(/\s+/g, ' ')
                .trim();

        return `mission-name:${missionName}`;
    }

    function readPatientSelectionLedger() {
        const missionKey =
            getPatientSelectionMissionKey();

        if (
            mfPatientSelectionLedgerCache &&
            mfPatientSelectionLedgerCache.missionKey ===
                missionKey
        ) {
            return mfPatientSelectionLedgerCache;
        }

        let parsed = null;

        try {
            parsed = JSON.parse(
                sessionStorage.getItem(
                    MF_PATIENT_SELECTION_LEDGER_KEY
                ) ||
                'null'
            );
        } catch (_error) {
            parsed = null;
        }

        if (
            !parsed ||
            parsed.missionKey !== missionKey ||
            !parsed.counts ||
            typeof parsed.counts !== 'object'
        ) {
            parsed = {
                missionKey,
                counts: {}
            };
        }

        mfPatientSelectionLedgerCache = parsed;

        try {
            sessionStorage.setItem(
                MF_PATIENT_SELECTION_LEDGER_KEY,
                JSON.stringify(parsed)
            );
        } catch (_error) {}

        return parsed;
    }

    function savePatientSelectionLedger(ledger) {
        if (!ledger) return;

        mfPatientSelectionLedgerCache = ledger;

        try {
            sessionStorage.setItem(
                MF_PATIENT_SELECTION_LEDGER_KEY,
                JSON.stringify(ledger)
            );
        } catch (_error) {}
    }

    function getTrackedPatientUnitSelections(type) {
        const key =
            String(type || '')
                .trim()
                .toLowerCase();

        if (!key) return 0;

        const ledger =
            readPatientSelectionLedger();

        return Math.max(
            0,
            parseInt(
                ledger.counts[key],
                10
            ) || 0
        );
    }

    function setTrackedPatientUnitSelections(
        type,
        total
    ) {
        const key =
            String(type || '')
                .trim()
                .toLowerCase();

        if (!key) return 0;

        const ledger =
            readPatientSelectionLedger();

        const safeTotal =
            Math.max(
                0,
                parseInt(total, 10) || 0
            );

        ledger.counts[key] =
            Math.max(
                getTrackedPatientUnitSelections(key),
                safeTotal
            );

        savePatientSelectionLedger(ledger);

        return ledger.counts[key];
    }

    function incrementTrackedPatientUnitSelections(
        type,
        amount
    ) {
        const current =
            getTrackedPatientUnitSelections(type);

        const addition =
            Math.max(
                0,
                parseInt(amount, 10) || 0
            );

        return setTrackedPatientUnitSelections(
            type,
            current + addition
        );
    }

    function handlePatientSelector() {
        updateStatusBox('Handling patient ambulance selection...');

        const patientCount = findPatientCount(true);

        if (mfDebugEnabled) {
            debugLog('PATIENTS', `Patient badge count = ${patientCount}`);
        }

        vehicleLoadState.patients = patientCount;
        vehicleLoadState.ambulances = Math.max(
            countSelectedMatchingVehicles(
                'Ambulance',
                'Ambulance x 01'
            ),
            getTrackedPatientUnitSelections(
                'ambulance'
            )
        );
        vehicleLoadState.ambulanceOfficer =
            vehicleLoadState.ambulanceOfficer ||
            countSelectedMatchingVehicles(
                'Ambulance Officer',
                'Ambulance Officer'
            ) > 0;

        // V9.1: patient badge only sends ambulances.
        // Specialist ambulance units/officers are selected only when the live
        // mission requirements or the configured Officer threshold ask for them.
        if (patientCount > 0) {
            triggerAmbulanceClick(patientCount);
        }

        renderVehicleLoadList();

        return patientCount;
    }

    function getActiveMissionScopesForPatients() {
        // Use the same current-mission container resolution as Mission Update.
        // The old selector sweep could retain a visible patient badge/card from
        // the previously opened mission and make Auto Mode send Ambulances on a
        // Police-only mission.
        const contextRoots =
            getActiveMissionRequirementContexts()
                .map(context => context.root)
                .filter(Boolean);

        const currentMissionRoots =
            getCurrentMissionPatientAlertRoots(
                [],
                contextRoots
            );

        const visibleRoots =
            Array.from(
                new Set(
                    currentMissionRoots
                        .filter(root => {
                            if (!root) return false;
                            if (root.nodeType === 9) {
                                return isMissionDocumentVisible(root);
                            }

                            return isMissionElementVisible(root);
                        })
                )
            );

        if (visibleRoots.length > 0) {
            return visibleRoots;
        }

        const missionInfo =
            getActiveVisibleMissionInfo();

        if (missionInfo) {
            const missionContainer =
                missionInfo.closest?.(
                    '.vm--modal, .modal, .lightbox, #lightbox_box, ' +
                    '#iframe-inside-container, #mission_content, .mission_content'
                );

            if (missionContainer) {
                return [missionContainer];
            }

            return [
                missionInfo.ownerDocument ||
                document
            ];
        }

        return /^\/missions\//.test(
            window.location.pathname
        )
            ? [document]
            : [];
    }

    function invalidatePatientCountCache() {
        mfPatientCountCache = {
            expiresAt: 0,
            missionKey: '',
            value: 0
        };
    }

    function findPatientCount(forceRefresh = false) {
        if (!isCurrentMissionExecutionOwner('patient count read')) {
            return 0;
        }

        synchroniseMissionInstanceState('patient count');

        const now = Date.now();
        const missionKey = getLocalMissionInstanceKey();

        if (
            !forceRefresh &&
            missionKey === mfPatientCountCache.missionKey &&
            now < mfPatientCountCache.expiresAt
        ) {
            return mfPatientCountCache.value;
        }

        const value = computePatientCountNow();

        mfPatientCountCache = {
            expiresAt: now + 200,
            missionKey,
            value
        };

        return value;
    }

    function computePatientCountNow() {
        const scopes = getActiveMissionScopesForPatients();
        let highestBadgeCount = 0;

        for (const scope of scopes) {
            const badges = Array.from(scope.querySelectorAll('span.badge, .badge'));

            for (const badge of badges) {
                const text = (badge.textContent || '').replace(/\s+/g, ' ').trim();

                if (!/patients?/i.test(text)) continue;

                const numberMatch = text.match(/\d+/);
                const count = numberMatch ? parseInt(numberMatch[0], 10) : 0;

                if (Number.isFinite(count) && count > highestBadgeCount) {
                    highestBadgeCount = count;
                }
            }
        }

        if (highestBadgeCount > 0) return highestBadgeCount;

        // Some missions create the patient cards before updating the badge.
        // Count the visible patient cards as a second source.
        const patientCards = [];

        scopes.forEach(scope => {
            scope.querySelectorAll('.mission_patient, [id^="patient_"][class*="patient"], .patient').forEach(card => {
                if (patientCards.includes(card)) return;

                try {
                    if (!isElementVisible(card)) return;
                } catch (error) {}

                // Avoid counting tiny labels/icons as complete patient cards.
                const text = (card.innerText || card.textContent || '').replace(/\s+/g, ' ').trim();
                const hasPatientContent =
                    card.classList.contains('mission_patient') ||
                    /patient|we need:|transport/i.test(text) ||
                    !!card.querySelector('.alert, .patient_name, [id^="patient_"]');

                if (hasPatientContent) patientCards.push(card);
            });
        });

        return patientCards.length;
    }

    // Legacy helper kept for live mission requirement support. Patient handling no longer calls this.
    function triggerAmbulanceOfficerClick() {
        const ambulanceOfficer = findUnitButton('Ambulance Officer');

        if (ambulanceOfficer) {
            if (mfDebugEnabled) debugLog('AMBULANCE OFFICER', `Selecting ${getVehicleDebugName(ambulanceOfficer)}`);
            clickVehicleElement(ambulanceOfficer);
            vehicleLoadState.ambulanceOfficer = true;
            renderVehicleLoadList();
        } else if (mfDebugEnabled) {
            debugLog('AMBULANCE OFFICER', 'No Ambulance Officer checkbox/button found');
        }
    }

    // Legacy helper kept for future/manual use only. Mission updates use selectVehicleUnits directly.
    function triggerAmbulanceClick(number) {
        if (mfDebugEnabled) {
            debugLog('AMBULANCE SELECTOR', `Requested ${number} ambulance(s) from patient count`);
        }

        const trackedSelected =
            getTrackedPatientUnitSelections(
                'ambulance'
            );

        const domSelected =
            countSelectedMatchingVehicles(
                'Ambulance',
                'Ambulance x 01'
            );

        const alreadySelected =
            Math.min(
                Math.max(
                    domSelected,
                    trackedSelected
                ),
                number
            );

        const remaining =
            Math.max(
                0,
                number -
                alreadySelected
            );

        addOrUpdateVehicleRow(
            'Ambulance',
            'Ambulance x 01',
            number,
            remaining > 0
                ? 'pending'
                : 'assigned',
            alreadySelected
        );

        renderVehicleLoadList();

        let selectionResult = null;

        if (remaining > 0) {
            selectionResult =
                selectVehicleUnits(
                    'Ambulance',
                    'Ambulance x 01',
                    remaining,
                    'PATIENT'
                );
        }

        const selectedFromDom =
            Math.min(
                countSelectedMatchingVehicles(
                    'Ambulance',
                    'Ambulance x 01'
                ),
                number
            );

        const selectedFromThisAttempt =
            Math.min(
                number,
                alreadySelected +
                Math.max(
                    0,
                    parseInt(
                        selectionResult?.assigned,
                        10
                    ) || 0
                )
            );

        const selectedNow =
            Math.max(
                selectedFromDom,
                selectedFromThisAttempt
            );

        setTrackedPatientUnitSelections(
            'ambulance',
            selectedNow
        );

        addOrUpdateVehicleRow(
            'Ambulance',
            'Ambulance x 01',
            number,
            selectedNow >= number
                ? 'assigned'
                : 'missing',
            selectedNow
        );

        vehicleLoadState.ambulances =
            selectedNow;

        if (mfDebugEnabled) {
            debugLog(
                'AMBULANCE CAP',
                `Required=${number} | DOM selected=${domSelected} | tracked=${trackedSelected} | ` +
                `counted before=${alreadySelected} | clicked at most=${remaining} | final=${selectedNow}`
            );
        }

        renderVehicleLoadList();
    }

    function getMissionIdFromLocalScope(scope) {
        if (!scope) return '';

        const attributeNames = [
            'data-mission-id',
            'data-id',
            'mission_id',
            'data-mission'
        ];

        const attributeElements = [];

        if (scope.nodeType === 1) {
            attributeElements.push(scope);
        }

        try {
            attributeElements.push(
                ...scope.querySelectorAll(
                    '#mission_general_info, [data-mission-id], [mission_id]'
                )
            );
        } catch (_error) {}

        for (const element of attributeElements) {
            for (const attributeName of attributeNames) {
                const value = element?.getAttribute?.(attributeName);

                if (value && /^\d+$/.test(String(value).trim())) {
                    return String(value).trim();
                }
            }
        }

        const urlElements = [];

        try {
            urlElements.push(
                ...scope.querySelectorAll(
                    'a[href*="/missions/"], a[href*="mission_id="], ' +
                    'form[action*="/missions/"], form[action*="mission_id="]'
                )
            );
        } catch (_error) {}

        for (const element of urlElements) {
            const value =
                element?.href ||
                element?.action ||
                element?.getAttribute?.('href') ||
                element?.getAttribute?.('action') ||
                '';

            const missionId =
                parseMissionIdFromHrefForQueueRestart(value);

            if (missionId) return missionId;
        }

        try {
            const input = scope.querySelector(
                'input[name="mission_id"], input#mission_id'
            );

            const inputValue = String(input?.value || '').trim();

            if (/^\d+$/.test(inputValue)) {
                return inputValue;
            }
        } catch (_error) {}

        return '';
    }

    function getLocalMissionInstanceKey() {
        const locationMissionId =
            parseMissionIdFromHrefForQueueRestart(
                window.location.href
            );

        if (locationMissionId) {
            return `mission:${locationMissionId}`;
        }

        const visibleMissionInfo = Array.from(
            document.querySelectorAll('#mission_general_info')
        )
            .filter(element => isMissionElementVisible(element))
            .pop() || null;

        const localScope =
            visibleMissionInfo?.closest?.(
                '#iframe-inside-container, #mission_content, .mission_content, ' +
                '.vm--modal, .modal, .lightbox, #lightbox_box'
            ) ||
            visibleMissionInfo ||
            document;

        const scopedMissionId =
            getMissionIdFromLocalScope(localScope);

        if (scopedMissionId) {
            return `mission:${scopedMissionId}`;
        }

        try {
            const frameSource =
                window.frameElement?.getAttribute?.('src') ||
                window.frameElement?.src ||
                '';

            const frameMissionId =
                parseMissionIdFromHrefForQueueRestart(frameSource);

            if (frameMissionId) {
                return `mission:${frameMissionId}`;
            }
        } catch (_error) {}

        const localHelpLinks = Array.from(
            document.querySelectorAll('#mission_help')
        );

        const localHelpSource =
            localHelpLinks
                .map(link => {
                    return normaliseMissionRequirementSourceUrl(
                        link.getAttribute?.('href') ||
                            link.href ||
                            '',
                        '',
                        link.ownerDocument?.baseURI ||
                            window.location.href
                    );
                })
                .find(Boolean) ||
            null;

        if (localHelpSource?.missionId) {
            return `mission:${localHelpSource.missionId}`;
        }

        const helpHref = String(
            localHelpSource?.url ||
            localHelpLinks[
                localHelpLinks.length - 1
            ]?.getAttribute?.('href') ||
            ''
        ).trim();

        const missionTitle = String(
            visibleMissionInfo?.getAttribute?.('data-mission-title') ||
            document.querySelector('#missionH1')?.textContent ||
            ''
        )
            .replace(/\s+/g, ' ')
            .trim();

        return [
            'document',
            window.location.pathname,
            window.location.search,
            helpHref,
            missionTitle
        ].join('|');
    }

    function getPrimaryMissionRequirementDocument() {
        const candidates = [];

        getMissionAccessibleDocuments(true)
            .forEach((candidateDocument, documentIndex) => {
                if (
                    !candidateDocument ||
                    !isMissionDocumentVisible(candidateDocument)
                ) {
                    return;
                }

                let score = 0;
                let visibleMarkerCount = 0;

                const markerDefinitions = [
                    ['#mission_general_info', 500, true],
                    ['#mission_alarm_btn, #alarm_button', 350, true],
                    ['input.vehicle_checkbox', 250, true],
                    ['#mission_help', 180, false]
                ];

                markerDefinitions.forEach(([selector, weight, requireVisible]) => {
                    let visibleCount = 0;

                    try {
                        visibleCount = Array.from(
                            candidateDocument.querySelectorAll(selector)
                        ).filter(element => {
                            if (element.isConnected === false) return false;
                            return requireVisible
                                ? isMissionElementVisible(element)
                                : true;
                        }).length;
                    } catch (_error) {}

                    if (visibleCount > 0) {
                        score += weight;
                        visibleMarkerCount += visibleCount;
                    }
                });

                if (visibleMarkerCount === 0) return;

                try {
                    const frame =
                        candidateDocument.defaultView?.frameElement;

                    if (frame && isMissionElementVisible(frame)) {
                        score += 1000;

                        const ownerDocument = frame.ownerDocument;
                        const ownerWindow =
                            ownerDocument?.defaultView ||
                            window;

                        const ownerModal = frame.closest(
                            '.vm--modal, .modal, .lightbox, #lightbox_box'
                        );

                        if (ownerModal) {
                            const modalStyle =
                                ownerWindow.getComputedStyle(ownerModal);

                            const modalZIndex = parseInt(
                                modalStyle.zIndex,
                                10
                            );

                            if (Number.isFinite(modalZIndex)) {
                                score += Math.max(0, modalZIndex) * 10;
                            }

                            if (
                                ownerModal.getAttribute('aria-modal') === 'true' ||
                                ownerModal.getAttribute('aria-expanded') === 'true'
                            ) {
                                score += 2000;
                            }

                            const allModals = Array.from(
                                ownerDocument.querySelectorAll(
                                    '.vm--modal, .modal, .lightbox, #lightbox_box'
                                )
                            );

                            score += Math.max(
                                0,
                                allModals.indexOf(ownerModal)
                            ) * 20;
                        }

                        const frameStyle =
                            ownerWindow.getComputedStyle(frame);

                        const frameZIndex = parseInt(
                            frameStyle.zIndex,
                            10
                        );

                        if (Number.isFinite(frameZIndex)) {
                            score += Math.max(0, frameZIndex);
                        }

                        const allFrames = Array.from(
                            ownerDocument.querySelectorAll('iframe')
                        );

                        score += Math.max(0, allFrames.indexOf(frame));

                        try {
                            const rect = frame.getBoundingClientRect();
                            const probePoints = [
                                [rect.left + rect.width / 2, rect.top + rect.height / 2],
                                [rect.left + Math.min(30, rect.width / 4), rect.top + Math.min(30, rect.height / 4)],
                                [rect.right - Math.min(30, rect.width / 4), rect.top + Math.min(30, rect.height / 4)]
                            ];

                            const topmostHits = probePoints.filter(([x, y]) => {
                                if (
                                    x < 0 ||
                                    y < 0 ||
                                    x > ownerWindow.innerWidth ||
                                    y > ownerWindow.innerHeight
                                ) {
                                    return false;
                                }

                                const hit = ownerDocument.elementFromPoint(x, y);
                                return hit === frame;
                            }).length;

                            if (topmostHits > 0) {
                                score += 100000 + (topmostHits * 1000);
                            }
                        } catch (_error) {}
                    } else if (
                        candidateDocument ===
                        candidateDocument.defaultView?.top?.document
                    ) {
                        // Direct /missions/... page without an iframe.
                        score += 50000;
                    }
                } catch (_error) {}

                candidates.push({
                    document: candidateDocument,
                    score,
                    documentIndex
                });
            });

        candidates.sort((left, right) => {
            return (
                right.score - left.score ||
                right.documentIndex - left.documentIndex
            );
        });

        return candidates[0]?.document || document;
    }

    function getSharedTopWindow() {
        try {
            return window.top || window;
        } catch (_error) {
            return window;
        }
    }

    function claimCurrentMissionExecutionOwnership(reason = '') {
        const primaryDocument =
            getPrimaryMissionRequirementDocument();

        if (primaryDocument !== document) {
            return false;
        }

        const sharedTopWindow =
            getSharedTopWindow();

        try {
            sharedTopWindow[MF_SHARED_ACTIVE_INSTANCE_KEY] = {
                token: MF_INSTANCE_TOKEN,
                missionKey: getLocalMissionInstanceKey(),
                claimedAt: Date.now(),
                reason: String(reason || '')
            };
        } catch (_error) {}

        return true;
    }

    function isCurrentMissionExecutionOwner(reason = '') {
        const primaryDocument =
            getPrimaryMissionRequirementDocument();

        if (primaryDocument !== document) {
            return false;
        }

        const sharedTopWindow =
            getSharedTopWindow();

        try {
            const owner =
                sharedTopWindow[MF_SHARED_ACTIVE_INSTANCE_KEY];

            if (
                !owner ||
                owner.token === MF_INSTANCE_TOKEN ||
                owner.missionKey !== getLocalMissionInstanceKey() ||
                Date.now() - Number(owner.claimedAt || 0) > 5000
            ) {
                return claimCurrentMissionExecutionOwnership(reason);
            }

            return owner.token === MF_INSTANCE_TOKEN;
        } catch (_error) {
            return true;
        }
    }

    function getCurrentFrameOwnerMissionRoot(primaryDocument) {
        try {
            const frame =
                primaryDocument?.defaultView?.frameElement;

            if (!frame || !isMissionElementVisible(frame)) {
                return null;
            }

            const ownerRoot = frame.closest(
                '.vm--modal, .modal, .lightbox, #lightbox_box'
            );

            return ownerRoot && isMissionElementVisible(ownerRoot)
                ? ownerRoot
                : null;
        } catch (_error) {
            return null;
        }
    }

    function synchroniseMissionInstanceState(reason = '') {
        const nextMissionKey =
            getLocalMissionInstanceKey();

        if (!mfCurrentMissionInstanceKey) {
            mfCurrentMissionInstanceKey = nextMissionKey;
            return false;
        }

        if (
            !nextMissionKey ||
            nextMissionKey === mfCurrentMissionInstanceKey
        ) {
            return false;
        }

        const currentKeyIsStrong =
            /^mission:\d+$/.test(
                mfCurrentMissionInstanceKey
            );

        const nextKeyIsStrong =
            /^mission:\d+$/.test(
                nextMissionKey
            );

        // The mission ID can appear a fraction later than the initial DOM.
        // Promote a provisional document key to the real mission ID without
        // treating that as a second mission and clearing valid selections.
        if (!currentKeyIsStrong && nextKeyIsStrong) {
            mfCurrentMissionInstanceKey = nextMissionKey;
            invalidateMissionContextCaches();
            invalidatePatientCountCache();
            return false;
        }

        // Do not demote a known mission ID during a brief partial render.
        if (currentKeyIsStrong && !nextKeyIsStrong) {
            return false;
        }

        mfCurrentMissionInstanceKey = nextMissionKey;

        invalidateMissionContextCaches();
        invalidatePatientCountCache();
        invalidateVehicleCheckboxCache();
        clearSelectionGuards();
        clearAutoSelectionMissionGuard(
            `mission changed: ${reason || 'shared reader'}`
        );

        mfPatientSelectionLedgerCache = null;

        try {
            sessionStorage.removeItem(
                MF_PATIENT_SELECTION_LEDGER_KEY
            );
        } catch (_error) {}

        mfStaffingBlockActive = false;
        mfStaffingBlockText = '';
        mfStaffingBlockMissionKey = '';
        mfMissionUpdateFirstPassMissionKey = '';
        mfMissionUpdateFirstPassRequired = true;
        mfMissionUpdateFirstPassCompletedAt = 0;

        vehicleLoadState = {
            rows: [],
            patients: 0,
            ambulances: 0,
            ambulanceOfficer: false,
            trainedPersonnelBlocked: false,
            trainedPersonnelBlockText: '',
            ready: false
        };

        renderVehicleLoadList();

        return true;
    }

    function invalidateMissionContextCaches() {
        mfMissionDocumentCache = {
            expiresAt: 0,
            documents: []
        };

        mfMissionContextCache = {
            expiresAt: 0,
            missionKey: '',
            contexts: []
        };

        mfDispatchReadinessExpensiveCache = {
            expiresAt: 0,
            updateRowsSignature: '',
            staffingText: ''
        };

        mfMissionUpdateRowsCache = {
            expiresAt: 0,
            missionKey: '',
            rows: [],
            ambulanceOfficerSatisfied: false
        };
    }

    function isCachedMissionDocumentUsable(candidateDocument) {
        if (!candidateDocument?.documentElement) return false;

        try {
            const ownerWindow = candidateDocument.defaultView;

            if (ownerWindow && ownerWindow.document !== candidateDocument) {
                return false;
            }

            const frame = ownerWindow?.frameElement;
            return !frame || frame.isConnected !== false;
        } catch (_error) {
            return true;
        }
    }

    function getMissionAccessibleDocuments(forceRefresh = false) {
        const now = Date.now();
        const cachedDocuments = mfMissionDocumentCache.documents;

        if (
            !forceRefresh &&
            now < mfMissionDocumentCache.expiresAt &&
            cachedDocuments.every(isCachedMissionDocumentUsable)
        ) {
            return cachedDocuments;
        }

        const documents = [];

        const addDocument = candidate => {
            try {
                if (
                    candidate &&
                    candidate.documentElement &&
                    !documents.includes(candidate)
                ) {
                    documents.push(candidate);
                }
            } catch (_error) {}
        };

        addDocument(document);

        try {
            addDocument(window.parent?.document);
        } catch (_error) {}

        try {
            addDocument(window.top?.document);
        } catch (_error) {}

        let scanIndex = 0;

        while (scanIndex < documents.length) {
            const ownerDocument = documents[scanIndex];
            scanIndex += 1;

            try {
                ownerDocument.querySelectorAll('iframe').forEach(frame => {
                    try {
                        addDocument(
                            frame.contentDocument ||
                            frame.contentWindow?.document
                        );
                    } catch (_error) {}
                });
            } catch (_error) {}
        }

        mfMissionDocumentCache = {
            expiresAt: now + 5000,
            documents
        };

        return documents;
    }


    let mfIphoneLauncherLastNativeCluster = null;








    function isMissionFinderIphoneNativePickerElementVisible(
        element
    ) {
        if (
            !element ||
            element.isConnected === false
        ) {
            return false;
        }

        try {
            const ownerWindow =
                element.ownerDocument
                    ?.defaultView ||
                window;
            const style =
                ownerWindow.getComputedStyle(
                    element
                );

            if (
                style.display === 'none' ||
                style.visibility === 'hidden'
            ) {
                return false;
            }

            return element.getClientRects().length > 0;
        } catch (_error) {
            return true;
        }
    }

    function getMissionFinderIphoneNativePickerAnchors(
        candidateDocument
    ) {
        let anchors = [];

        try {
            anchors = Array.from(
                candidateDocument.querySelectorAll(
                    'a[search_attribute]'
                )
            ).filter(anchor => {
                return Boolean(
                    anchor &&
                    anchor.isConnected !== false &&
                    !anchor.closest?.(
                        '#mission-finder-wrapper'
                    )
                );
            });
        } catch (_error) {}

        const visibleAnchors =
            anchors.filter(
                isMissionFinderIphoneNativePickerElementVisible
            );

        return visibleAnchors.length >= 4
            ? visibleAnchors
            : anchors;
    }

    function getMissionFinderIphoneNativePickerGrid(
        candidateDocument,
        anchors
    ) {
        if (!anchors?.length) return null;

        const firstTable =
            anchors[0].closest?.('table');

        if (
            firstTable &&
            firstTable !== candidateDocument.body &&
            anchors.every(anchor =>
                firstTable.contains(anchor)
            )
        ) {
            return firstTable;
        }

        let ancestor =
            anchors[0].parentElement;

        while (
            ancestor &&
            ancestor !== candidateDocument.body &&
            ancestor !== candidateDocument.documentElement
        ) {
            if (
                anchors.every(anchor =>
                    ancestor.contains(anchor)
                )
            ) {
                if (
                    /^(?:TBODY|THEAD|TR|TD)$/i.test(
                        ancestor.tagName || ''
                    )
                ) {
                    const table =
                        ancestor.closest?.('table');

                    if (
                        table &&
                        anchors.every(anchor =>
                            table.contains(anchor)
                        )
                    ) {
                        return table;
                    }
                }

                return ancestor;
            }

            ancestor = ancestor.parentElement;
        }

        return null;
    }

    function getMissionFinderIphoneNativePickerShell(
        candidateDocument,
        grid
    ) {
        if (!grid) return null;

        const fallback =
            grid.parentElement;
        let candidate = fallback;
        let depth = 0;

        while (
            candidate &&
            candidate !== candidateDocument.body &&
            candidate !== candidateDocument.documentElement &&
            depth < 6
        ) {
            let hasSearch = false;
            let hasNavigation = false;

            try {
                hasSearch = Boolean(
                    candidate.querySelector(
                        'input[type="search"], ' +
                        'input[type="text"][placeholder*="search" i], ' +
                        'input[id*="search" i], ' +
                        'input[class*="search" i]'
                    )
                );

                hasNavigation = Boolean(
                    candidate.querySelector(
                        'ul.nav, .nav-tabs, [role="tablist"], ' +
                        '.btn-group, .btn-toolbar'
                    )
                );
            } catch (_error) {}

            if (hasSearch || hasNavigation) {
                return candidate;
            }

            candidate = candidate.parentElement;
            depth += 1;
        }

        return fallback;
    }

    function isMissionFinderIphoneNativePickerBeforeGrid(
        element,
        grid
    ) {
        if (!element || !grid || element === grid) {
            return false;
        }

        try {
            return Boolean(
                element.compareDocumentPosition(grid) &
                4
            );
        } catch (_error) {
            return false;
        }
    }

    function getMissionFinderIphoneNativePickerStrips(
        shell,
        grid
    ) {
        if (!shell || !grid) return [];

        const candidates = new Set();

        try {
            shell.querySelectorAll(
                'ul.nav, .nav-tabs, [role="tablist"], ' +
                '.btn-group, .btn-toolbar'
            ).forEach(candidate => {
                if (
                    !grid.contains(candidate) &&
                    !candidate.contains(grid) &&
                    isMissionFinderIphoneNativePickerBeforeGrid(
                        candidate,
                        grid
                    )
                ) {
                    candidates.add(candidate);
                }
            });
        } catch (_error) {}

        try {
            const controls = Array.from(
                shell.querySelectorAll(
                    'a:not([search_attribute]), button, [role="tab"]'
                )
            ).filter(control => {
                return Boolean(
                    !grid.contains(control) &&
                    isMissionFinderIphoneNativePickerBeforeGrid(
                        control,
                        grid
                    )
                );
            });

            const parents = new Set(
                controls
                    .map(control => control.parentElement)
                    .filter(Boolean)
            );

            parents.forEach(parent => {
                if (
                    parent === shell ||
                    parent.querySelector?.(
                        'a[search_attribute]'
                    )
                ) {
                    return;
                }

                let directControls = [];

                try {
                    directControls = Array.from(
                        parent.children || []
                    ).filter(child => {
                        return Boolean(
                            child.matches?.(
                                'a, button, [role="tab"], li'
                            ) ||
                            child.querySelector?.(
                                ':scope > a, :scope > button, :scope > [role="tab"]'
                            )
                        );
                    });
                } catch (_error) {}

                if (
                    directControls.length >= 3 &&
                    directControls.length <= 20 &&
                    isMissionFinderIphoneNativePickerBeforeGrid(
                        parent,
                        grid
                    )
                ) {
                    candidates.add(parent);
                }
            });
        } catch (_error) {}

        const candidateList = Array.from(candidates);

        return candidateList.filter(candidate => {
            return !candidateList.some(other => {
                return Boolean(
                    other !== candidate &&
                    candidate.contains(other)
                );
            });
        });
    }

    function getMissionFinderIphoneNativePickerSearchInputs(
        shell,
        grid
    ) {
        if (!shell || !grid) return [];

        try {
            return Array.from(
                shell.querySelectorAll(
                    'input[type="search"], ' +
                    'input[type="text"], ' +
                    'input:not([type])'
                )
            ).filter(input => {
                return Boolean(
                    !grid.contains(input) &&
                    isMissionFinderIphoneNativePickerBeforeGrid(
                        input,
                        grid
                    ) &&
                    isMissionFinderIphoneNativePickerElementVisible(
                        input
                    )
                );
            });
        } catch (_error) {
            return [];
        }
    }

    function getMissionFinderIphoneNativePickerDirectChild(
        ancestor,
        element
    ) {
        if (!ancestor || !element) return null;

        let current = element;

        while (
            current?.parentElement &&
            current.parentElement !== ancestor
        ) {
            current = current.parentElement;
        }

        return current?.parentElement === ancestor
            ? current
            : null;
    }

